import { Book } from "@/lib/types";

export const _1chronicles: Book = {
  id: "1chronicles",
  name: "1. Chronik",
  shortName: "1.Chr",
  testament: "old",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "*Adam, Set, Enosch,", heading: "Nachkommen Adams bis zu den Söhnen Isaaks 1", footnotes: ["℘ V. 1-4: 1Mo 5; Lk 3,36-38; V. 5-16: 1Mo 10,1-20"] },
      { number: 2, text: "Kenan, Mahalalel, Jered," },
      { number: 3, text: "Henoch*, Metuschelach, Lamech,", footnotes: ["℘ Hebr 11,5"] },
      { number: 4, text: "Noah*, Sem, Ham und Jafet.", footnotes: ["℘ Hes 14,14"] },
      { number: 5, text: "Die Söhne Jafets: Gomer und Magog und Madai und Jawan und Tubal und Meschech und Tiras." },
      { number: 6, text: "Und die Söhne Gomers: Aschkenas und Rifat und Togarma." },
      { number: 7, text: "Und die Söhne Jawans: Elischa* und Tarsis, die Kittäer und die Rodaniter.", footnotes: ["℘ Hes 27,7"] },
      { number: 8, text: "Die Söhne Hams: Kusch und Mizrajim, Put und Kanaan." },
      { number: 9, text: "Und die Söhne von Kusch: Seba und Hawila und Sabta und Ragma und Sabtecha. Und die Söhne Ragmas: Saba und Dedan." },
      { number: 10, text: "Und Kusch zeugte Nimrod; der fing an, ein Gewaltiger auf der Erde zu sein. —" },
      { number: 11, text: "Und Mizrajim zeugte die Luditer und die Anamiter und die Lehabiter und die Naftuhiter" },
      { number: 12, text: "und die Patrositer und die Kasluhiter, von denen die Philister ausgegangen sind, und die Kaftoriter*. —", footnotes: ["Andere üs. mit Textkorrektur: und die Kasluhiter und die Kaftoriter, von denen die Philister ausgegangen sind"] },
      { number: 13, text: "Und Kanaan zeugte Sidon, seinen Erstgeborenen, und Het" },
      { number: 14, text: "und den Jebusiter und den Amoriter und den Girgaschiter" },
      { number: 15, text: "und den Hiwiter und den Arkiter und den Siniter" },
      { number: 16, text: "und den Arwaditer und den Zemariter und den Hamatiter." },
      { number: 17, text: "*Die Söhne Sems: Elam und Assur und Arpachschad und Lud und Aram und Uz und Hul und Geter und Masch.", footnotes: ["℘ V. 17-23: 1Mo 10,21-31; V. 17-27: 1Mo 11,10-26; Lk 3,34-36"] },
      { number: 18, text: "Und Arpachschad zeugte Schelach, und Schelach zeugte Eber." },
      { number: 19, text: "Und Eber wurden zwei Söhne geboren: Der Name des einen war Peleg, denn in seinen Tagen wurde die Erde verteilt*; und der Name seines Bruders war Joktan.", footnotes: ["o. teilte sich die Bevölkerung der Erde"] },
      { number: 20, text: "Und Joktan zeugte Almodad und Schelef und Hazarmawet und Jerach" },
      { number: 21, text: "und Hadoram und Usal und Dikla" },
      { number: 22, text: "und Obal und Abimaël und Saba" },
      { number: 23, text: "und Ofir und Hawila und Jobab; diese alle waren Söhne Joktans." },
      { number: 24, text: "Sem, Arpachschad, Schelach," },
      { number: 25, text: "Eber, Peleg, Regu," },
      { number: 26, text: "Serug, Nahor, Terach," },
      { number: 27, text: "Abram, das ist Abraham*.", footnotes: ["℘ 1Mo 17,5"] },
      { number: 28, text: "*Die Söhne Abrahams: Isaak* und Ismael*. —", footnotes: ["℘ V. 28-31: 1Mo 25,12-18", "℘ 1Mo 25,19", "℘ 1Mo 16,15"] },
      { number: 29, text: "Das ist ihre Generationenfolge*: Der Erstgeborene Ismaels: Nebajot, und Kedar und Adbeel und Mibsam,", footnotes: ["hebr. toledot; d. h. w. Erzeugungen; bedeutet im AT Nachkommen, Generationenfolge, Entstehung, Entstehungsgeschichte"] },
      { number: 30, text: "Mischma und Duma, Massa, Hadad und Tema*,", footnotes: ["℘ Jes 21,14"] },
      { number: 31, text: "Jetur, Nafisch* und Kedma; das sind die Söhne Ismaels.", footnotes: ["℘ Kap. 5,19; 1Mo 25,15"] },
      { number: 32, text: "*Und die Söhne der Ketura, der Nebenfrau Abrahams: sie gebar Simran und Jokschan und Medan und Midian und Jischbak und Schuach. Und die Söhne Jokschans: Saba und Dedan.", footnotes: ["℘ V. 32.33: 1Mo 25,1-4"] },
      { number: 33, text: "Und die Söhne Midians: Efa und Efer und Henoch und Abida und Eldaa. Diese alle waren Söhne der Ketura. —" },
      { number: 34, text: "Und Abraham zeugte Isaak*. Die Söhne Isaaks: Esau* und Israel*.", footnotes: ["℘ 1Mo 25,19", "℘ 1Mo 25,25", "℘ 1Mo 32,29"] },
      { number: 35, text: "*Die Söhne Esaus: Elifas, Reguël und Jëusch und Jalam und Korach.", heading: "Nachkommen Esaus", footnotes: ["℘ V. 35-42: 1Mo 36,1-30"] },
      { number: 36, text: "Die Söhne des Elifas: Teman und Omar, Zefo und Gatam, Kenas und Timna und Amalek." },
      { number: 37, text: "Die Söhne Reguëls: Nahat, Serach, Schamma und Misa." },
      { number: 38, text: "Und die Söhne Seïrs: Lotan und Schobal und Zibon und Ana und Dischon und Ezer und Dischan." },
      { number: 39, text: "Und die Söhne Lotans: Hori und Hemam; und die Schwester Lotans: Timna." },
      { number: 40, text: "Die Söhne Schobals: Alwan und Manahat und Ebal, Schefi und Onam. Und die Söhne Zibons: Aja und Ana." },
      { number: 41, text: "Die Söhne Anas: Dischon. Und die Söhne Dischons: Hemdan und Eschban und Jitran und Keran. —" },
      { number: 42, text: "Die Söhne Ezers: Bilhan und Saawan und Akan. Die Söhne Dischans: Uz und Aran." },
      { number: 43, text: "*Und das sind die Könige, die im Land Edom regiert haben, ehe ein König über die Söhne Israel regierte: Bela, der Sohn Beors; und der Name seiner Stadt war Dinhaba.", footnotes: ["℘ V. 43-54: 1Mo 36,31-43"] },
      { number: 44, text: "Und Bela starb; und an seiner Stelle wurde Jobab, der Sohn Serachs, aus Bozra König." },
      { number: 45, text: "Und Jobab starb; und an seiner Stelle wurde Huscham aus dem Land der Temaniter König." },
      { number: 46, text: "Und Huscham starb; und an seiner Stelle wurde Hadad, der Sohn Bedads, König, der Midian schlug im Gebiet* Moabs; und der Name seiner Stadt war Awit.", footnotes: ["o. Feld"] },
      { number: 47, text: "Und Hadad starb; und an seiner Stelle wurde Samla aus Masreka König." },
      { number: 48, text: "Und Samla starb; und König an seiner Stelle wurde Schaul aus Rehobot am Strom." },
      { number: 49, text: "Und Schaul starb; und an seiner Stelle wurde Baal-Hanan, der Sohn Achbors, König." },
      { number: 50, text: "Und Baal-Hanan starb; und an seiner Stelle wurde Hadad König; und der Name seiner Stadt war Pagu, und der Name seiner Frau Mehetabel, die Tochter Matreds, die Tochter Me-Sahabs." },
      { number: 51, text: "Und Hadad starb. Und Fürsten* von Edom waren: Fürst Timna, Fürst Alwa, Fürst Jetet,", footnotes: ["w. Anführer einer Tausendschaft; d. i. die übliche Bezeichnung für die Stammesfürsten der Edomiter"] },
      { number: 52, text: "Fürst Oholibama, Fürst Ela, Fürst Pinon," },
      { number: 53, text: "Fürst Kenas, Fürst Teman, Fürst Mibzar," },
      { number: 54, text: "Fürst Magdiël, Fürst Iram. Das sind die Fürsten von Edom." },
    ]},
    { number: 2, verses: [
      { number: 1, text: "*Das sind die Söhne Israels: Ruben, Simeon, Levi und Juda, Issaschar und Sebulon,", heading: "Söhne Jakobs — Nachkommen Judas", footnotes: ["℘ V. 1-15: Mt 1,2-6; Lk 3,31-34"] },
      { number: 2, text: "Dan, Josef und Benjamin, Naftali, Gad und Asser*.", footnotes: ["℘ 1Mo 35,22-26"] },
      { number: 3, text: "Die Söhne Judas: Er und Onan und Schela*; diese drei wurden ihm geboren von der Tochter Schuas, der Kanaaniterin. Und Er, der Erstgeborene Judas, war böse in den Augen des HERRN, und er ließ ihn sterben*.", footnotes: ["℘ Kap. 4,21", "℘ 1Mo 38,2-7"] },
      { number: 4, text: "Und seine* Schwiegertochter Tamar gebar ihm Perez und Serach*. Alle Söhne Judas waren fünf.", footnotes: ["d. h. Judas", "℘ 1Mo 38,29.30"] },
      { number: 5, text: "*Die Söhne des Perez waren: Hezron* und Hamul*.", footnotes: ["℘ V. 4-16: Rt 4,18-22", "℘ Kap. 4,1", "℘ 1Mo 46,12"] },
      { number: 6, text: "Und die Söhne Serachs: Simri und Etan und Heman und Kalkol und Darda*; sie alle waren fünf. —", footnotes: ["℘ 1Kö 5,11"] },
      { number: 7, text: "Und die Söhne Karmis*: Achar*, der Israel ins Unglück brachte, weil er Untreue an dem Gebannten übte*.", footnotes: ["℘ Kap. 4,1", "in Jos 7 Achan", "℘ Jos 7,1.25"] },
      { number: 8, text: "Und die Söhne Etans: Asarja. —" },
      { number: 9, text: "Und die Söhne Hezrons, die ihm geboren wurden: Jerachmeel* und Ram und Kaleb*.", footnotes: ["℘ V. 25; 1Sam 27,10", "℘ V. 18.42"] },
      { number: 10, text: "Und Ram zeugte Amminadab; und Amminadab zeugte Nachschon, den Fürsten der Söhne Juda*.", footnotes: ["℘ 4Mo 1,7"] },
      { number: 11, text: "Und Nachschon zeugte Salmon, und Salmon zeugte Boas;" },
      { number: 12, text: "und Boas zeugte Obed, und Obed zeugte Isai." },
      { number: 13, text: "Und Isai zeugte Eliab*, seinen Erstgeborenen; und Abinadab, den zweiten; und Schamma, den dritten*;", footnotes: ["℘ Kap. 27,18", "℘ 1Sam 16,6-9; 2Sam 13,3"] },
      { number: 14, text: "Netanel, den vierten; Raddai, den fünften;" },
      { number: 15, text: "Ozem, den sechsten; David, den siebten*.", footnotes: ["℘ 1Sam 17,12.14"] },
      { number: 16, text: "Und ihre Schwestern waren: Zeruja und Abigal. Und die Söhne der Zeruja: Abischai* und Joab und Asaël, drei*.", footnotes: ["℘ Kap. 11,20; 1Sam 26,6", "℘ 2Sam 2,18"] },
      { number: 17, text: "Und Abigal gebar Amasa; und der Vater Amasas war Jeter, der Ismaeliter*.", footnotes: ["℘ 2Sam 17,25"] },
      { number: 18, text: "Und Kaleb, der Sohn Hezrons*, zeugte Söhne mit seiner Frau Asuba und mit Jeriot*; und das sind ihre Söhne: Jescher und Schobab und Ardon.", footnotes: ["℘ V. 9", "Vielleicht ist mit korrigiertem Text zu lesen: zeugte mit seiner Frau Asuba die Jeriot"] },
      { number: 19, text: "Und Asuba starb; und Kaleb nahm Efrata*, und sie gebar ihm Hur*.", footnotes: ["℘ V. 50; 2Mo 17,10", "℘ Kap. 4,1"] },
      { number: 20, text: "Und Hur zeugte Uri, und Uri zeugte Bezalel*. —", footnotes: ["℘ 2Mo 31,2"] },
      { number: 21, text: "Und danach ging Hezron ein zu der Tochter Machirs, des Vaters Gileads*; und er nahm sie, als er sechzig Jahre alt war, und sie gebar ihm Segub.", footnotes: ["℘ Kap. 7,14; 4Mo 26,29"] },
      { number: 22, text: "Und Segub zeugte Jaïr. Und der hatte 23 Städte im Land Gilead*;", footnotes: ["℘ 4Mo 32,40.41; 5Mo 3,15"] },
      { number: 23, text: "und Geschur und Aram* nahmen ihnen die Zeltdörfer Jaïrs weg, dazu Kenat und seine Tochterstädte, sechzig Städte*. Diese alle waren Söhne Machirs, des Vaters Gileads.", footnotes: ["o. die Geschuriter und die Aramäer", "℘ 1Kö 4,13"] },
      { number: 24, text: "*Und nach dem Tod Hezrons in Kaleb-Efrata, da gebar Abija, die Frau Hezrons, ihm Aschhur*, den Vater Tekoas*.", footnotes: ["Mit korrigiertem Text lesen andere: Und nach dem Tod Hezrons kam Kaleb nach Efrata; und eine Frau Hezrons war Abija, und sie gebar ihm Aschhur", "Mit korrigiertem Text lesen andere: Und nach dem Tod Hezrons kam Kaleb nach Efrata; und eine Frau Hezrons war Abija, und sie gebar ihm Aschhur", "℘ Kap. 4,5"] },
      { number: 25, text: "Und die Söhne Jerachmeels*, des Erstgeborenen Hezrons, waren: der Erstgeborene Ram und Buna und Oren und Ozem von Ahija*.", footnotes: ["℘ V. 9", "o. und Ahija"] },
      { number: 26, text: "Und Jerachmeel hatte noch eine andere Frau, ihr Name war Atara; sie war die Mutter Onams." },
      { number: 27, text: "Und die Söhne Rams, des Erstgeborenen Jerachmeels, waren: Maaz und Jamin und Eker. —" },
      { number: 28, text: "Und die Söhne Onams waren: Schammai und Jada. Und die Söhne Schammais: Nadab und Abischur." },
      { number: 29, text: "Und der Name der Frau Abischurs war Abihajil; und sie gebar ihm Achban und Molid." },
      { number: 30, text: "Und die Söhne Nadabs: Seled und Appajim. Und Seled starb ohne Söhne. —" },
      { number: 31, text: "Und die Söhne Appajims: Jischi. Und die Söhne Jischis: Scheschan. Und die Söhne Scheschans: Achlai. —" },
      { number: 32, text: "Und die Söhne Jadas, des Bruders Schammais: Jeter und Jonatan. Und Jeter starb ohne Söhne." },
      { number: 33, text: "Und die Söhne Jonatans: Pelet und Sasa. Das waren die Söhne Jerachmeels. —" },
      { number: 34, text: "Und Scheschan hatte keine Söhne, sondern nur Töchter. Und Scheschan hatte einen ägyptischen Knecht, sein Name war Jarha;" },
      { number: 35, text: "und Scheschan gab seinem Knecht Jarha seine Tochter zur Frau, und sie gebar ihm Attai." },
      { number: 36, text: "Und Attai zeugte Nathan, und Nathan zeugte Sabad," },
      { number: 37, text: "und Sabad zeugte Eflal, und Eflal zeugte Obed," },
      { number: 38, text: "und Obed zeugte Jehu, und Jehu zeugte Asarja," },
      { number: 39, text: "und Asarja zeugte Helez, und Helez zeugte Elasa," },
      { number: 40, text: "und Elasa zeugte Sismai, und Sismai zeugte Schallum," },
      { number: 41, text: "und Schallum zeugte Jekamja, und Jekamja zeugte Elischama." },
      { number: 42, text: "Und die Söhne Kalebs*, des Bruders Jerachmeels: Mescha, sein Erstgeborener — er ist der Vater Sifs* —, und die Söhne Mareschas*, des Vaters Hebrons.", footnotes: ["℘ Jos 15,24.55", "℘ Jos 15,24.55", "℘ Jos 15,44"] },
      { number: 43, text: "Und die Söhne Hebrons: Korach und Tappuach* und Rekem und Schema.", footnotes: ["℘ Jos 15,34"] },
      { number: 44, text: "Und Schema zeugte Raham, den Vater Jorkoams, und Rekem zeugte Schammai." },
      { number: 45, text: "Und der Sohn Schammais war Maon*, und Maon war der Vater Bet-Zurs*. —", footnotes: ["℘ Jos 15,55", "℘ Jos 15,58"] },
      { number: 46, text: "Und Efa, die Nebenfrau Kalebs, gebar Haran und Moza und Gases. Und Haran zeugte Gases. —" },
      { number: 47, text: "Und die Söhne Jahdais: Regem und Jotam und Geschan und Pelet und Efa und Schaaf." },
      { number: 48, text: "Maacha, die Nebenfrau Kalebs, gebar Scheber und Tirhana;" },
      { number: 49, text: "und sie gebar Schaaf, den Vater Madmannas*, Schewa, den Vater Machbenas und den Vater Gibeas*. Und die Tochter Kalebs war Achsa*.", footnotes: ["℘ Jos 15,31", "℘ Jos 15,57", "℘ Jos 15,16"] },
      { number: 50, text: "Das waren die Söhne Kalebs. Die Söhne* Hurs, des Erstgeborenen der Efrata*: Schobal, der Vater von Kirjat-Jearim*;", footnotes: ["w. Der Sohn", "℘ V. 19; Kap. 4,1-4", "℘ Jos 15,60"] },
      { number: 51, text: "Salmon, der Vater von Bethlehem*; Haref, der Vater von Bet-Gader.", footnotes: ["℘ Kap. 4,4; Rt 1,1"] },
      { number: 52, text: "Und Schobal, der Vater von Kirjat-Jearim, hatte Söhne: Haroeh und Hazi, den Menuchotiter*;", footnotes: ["Andere lesen mit Kap. 4,2 bzw. 2,54: Reaja und Hazi, den Manachtiter. — Andere üs.: Haroeh, halb Menuchot"] },
      { number: 53, text: "und die Sippen von Kirjat-Jearim waren: die Jeteriter* und die Putiter und die Schumatiter und die Mischraïter; von diesen sind ausgegangen die Zoratiter* und die Eschtaoliter.", footnotes: ["℘ Kap. 11,40; 2Sam 23,38", "℘ Kap. 4,2; Jos 15,33"] },
      { number: 54, text: "Die Söhne Salmons: Bethlehem* und die Netofatiter*, Atrot-Bet-Joab und Hazi, der Manachtiter, und die Zoriter;", footnotes: ["℘ Kap. 4,4; Rt 1,1", "℘ Kap. 9,16; 11,30"] },
      { number: 55, text: "und die Sippen der Schreiber, die Jabez bewohnten: die Tiratiter, die Schimatiter, die Suchatiter. Das sind die Kiniter*, die von Hammat, dem Vater des Hauses Rechab*, herkommen.", footnotes: ["℘ Ri 1,16", "℘ 2Kö 10,15; Jer 35,2"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "*Und das waren die Söhne Davids, die ihm in Hebron geboren wurden: Der erstgeborene Amnon, von Ahinoam, der Jesreeliterin; der zweite Daniel, von Abigajil, der Karmeliterin;", heading: "Nachkommen Davids", footnotes: ["℘ V. 1-9: 2Sam 3,2-5; 5,13-16"] },
      { number: 2, text: "der dritte Absalom, der Sohn der Maacha, der Tochter Talmais, des Königs von Geschur; der vierte Adonija, der Sohn der Haggit*;", footnotes: ["℘ 1Kö 1,6"] },
      { number: 3, text: "der fünfte Schefatja, von der Abital; der sechste Jitream, von seiner Frau Egla." },
      { number: 4, text: "Diese sechs wurden ihm in Hebron geboren. Und er regierte dort sieben Jahre und sechs Monate; und 33 Jahre regierte er in Jerusalem*.", footnotes: ["℘ Kap. 29,27; 2Sam 5,5"] },
      { number: 5, text: "*Und diese wurden ihm in Jerusalem geboren: Schammua und Schobab und Nathan und Salomo, diese vier von Bat-Schua*, der Tochter Ammiëls*;", footnotes: ["℘ V. 5-9: Kap. 14,4-7", "eine andere Form für Batschewa (Batseba)", "℘ 2Sam 11,3"] },
      { number: 6, text: "und Jibhar und Elischama und Elifelet" },
      { number: 7, text: "und Nogah und Nefeg und Jafia" },
      { number: 8, text: "und Elischama und Eljada und Elifelet, zusammen neun;" },
      { number: 9, text: "alles Söhne Davids*, ohne die Söhne der Nebenfrauen; und Tamar war ihre Schwester*.", footnotes: ["℘ Kap. 28,5", "℘ 2Sam 13,1"] },
      { number: 10, text: "*Und der Sohn Salomos war Rehabeam*; dessen Sohn Abija*, dessen Sohn Asa*, dessen Sohn Joschafat*,", footnotes: ["℘ V. 10-24: Mt 1,7-11", "℘ 1Kö 11,43", "℘ 1Kö 14,31", "℘ 1Kö 15,8", "℘ 1Kö 15,24"] },
      { number: 11, text: "dessen Sohn Joram*, dessen Sohn Ahasja*, dessen Sohn Joasch*,", footnotes: ["℘ 1Kö 22,51", "℘ 2Kö 8,25", "℘ 2Kö 11,2"] },
      { number: 12, text: "dessen Sohn Amazja*, dessen Sohn Asarja*, dessen Sohn Jotam*,", footnotes: ["℘ 2Kö 14,1", "℘ 2Kö 14,21", "℘ 2Kö 15,7"] },
      { number: 13, text: "dessen Sohn Ahas*, dessen Sohn Hiskia*, dessen Sohn Manasse*,", footnotes: ["℘ 2Kö 16,1", "℘ Kap. 4,41; 2Kö 18,1", "℘ 2Kö 20,21"] },
      { number: 14, text: "dessen Sohn Amon*, dessen Sohn Josia*.", footnotes: ["℘ 2Kö 21,18", "℘ 2Kö 21,26"] },
      { number: 15, text: "Und die Söhne Josias: Der Erstgeborene: Johanan; der zweite: Jojakim*; der dritte: Zedekia*; der vierte: Schallum*.", footnotes: ["℘ 2Kö 23,34; Jer 26,1", "℘ 2Kö 24,17; Jer 24,8; 37,1", "℘ 2Chr 36,1; Jer 22,11.18"] },
      { number: 16, text: "Und die Söhne Jojakims: sein Sohn Jechonja*, dessen Sohn Zedekia.", footnotes: ["℘ 2Kö 24,8; 2Chr 36,15.16; Jer 22,24"] },
      { number: 17, text: "Und die Söhne Jechonjas: Assir*; dessen Sohn Schealtiël*", footnotes: ["Andere üs. mit korrigiertem Text: Die Söhne Jechonjas, des Gefangenen", "℘ Lk 3,27"] },
      { number: 18, text: "und Malkiram und Pedaja und Schenazzar, Jekamja, Hoschama und Nedabja." },
      { number: 19, text: "Und die Söhne Pedajas: Serubbabel* und Schimi. Und die Söhne Serubbabels: Meschullam und Hananja; und Schelomit war ihre Schwester;", footnotes: ["℘ Esr 3,2"] },
      { number: 20, text: "und Haschuba und Ohel und Berechja und Hasadja, Juschab-Hesed, diese fünf." },
      { number: 21, text: "Und die Söhne Hananjas: Pelatja und Jesaja; die Söhne Refajas, die Söhne Arnans, die Söhne Obadjas, die Söhne Schechanjas*.", footnotes: ["Eine hebr. Handschr., LXX und Vulg. lesen: Pelatja und sein Sohn Jesaja, dessen Sohn Refaja, dessen Sohn Arnan, dessen Sohn Obadja, dessen Sohn Schechanja"] },
      { number: 22, text: "Und die Söhne Schechanjas: Schemaja. Und die Söhne Schemajas: Hattusch* und Jigal und Bariach und Nearja und Schafat, diese sechs.", footnotes: ["℘ Esr 8,2"] },
      { number: 23, text: "Und die Söhne Nearjas: Eljoënai und Hiskia und Asrikam, diese drei." },
      { number: 24, text: "Und die Söhne Eljoënais: Hodawja und Eljaschib und Pelaja und Akkub und Johanan und Delaja und Anani, diese sieben." },
    ]},
    { number: 4, verses: [
      { number: 1, text: "*Die Söhne Judas: Perez*, Hezron* und Karmi* und Hur und Schobal*.", heading: "Stamm Juda", footnotes: ["℘ 4Mo 26,19-22", "℘ Kap. 2,4; 1Mo 46,12; Lk 3,33", "℘ Kap. 2,5", "℘ Kap. 2,7", "℘ Kap. 2,50"] },
      { number: 2, text: "Und Reaja, der Sohn Schobals, zeugte Jahat; und Jahat zeugte Ahumai und Lahad. Das sind die Sippen der Zoratiter*. —", footnotes: ["℘ Kap. 2,53"] },
      { number: 3, text: "Und diese sind von dem Vater Etams: Jesreel und Jischma und Jidbasch; und der Name ihrer Schwester: Hazlelponi;" },
      { number: 4, text: "und Pnuël, der Vater Gedors; und Eser, der Vater Huschas. Das sind die Söhne Hurs, des Erstgeborenen von der Efrata*, des Vaters, von Bethlehem*. —", footnotes: ["℘ Kap. 2,19.50", "℘ Kap. 2,51"] },
      { number: 5, text: "Und Aschhur, der Vater Tekoas*, hatte zwei Frauen: Hela und Naara.", footnotes: ["℘ Kap. 2,24"] },
      { number: 6, text: "Und Naara gebar ihm Ahusam und Hefer und Temni und Ahaschtari. Das sind die Söhne der Naara." },
      { number: 7, text: "Und die Söhne der Hela: Zeret, Jizhar* und Etnan. —", footnotes: ["Leseform: Zeret und Zohar"] },
      { number: 8, text: "Und Koz zeugte Anub und Zobeba und die Sippen Aharhels, des Sohnes Harums." },
      { number: 9, text: "Und Jabez war angesehener als seine Brüder; zwar hatte seine Mutter ihm den Namen Jabez gegeben, denn sie sagte: Mit Schmerzen habe ich ihn geboren*.", footnotes: ["Jabez klingt an das hebr. Wort für Schmerz an.\n℘ 1Mo 3,16"] },
      { number: 10, text: "Aber Jabez hatte den Gott Israels angerufen und gesagt: Dass du mich doch segnen* und mein Gebiet erweitern mögest* und deine Hand mit mir sei* und du das Übel von mir fern hieltest, dass kein Schmerz mich treffe*! Und Gott ließ kommen, was er erbeten hatte*. —", footnotes: ["℘ 1Mo 32,27", "℘ Spr 10,22", "℘ Ps 119,173", "℘ 1Mo 28,20.21; Ps 121,7", "℘ 1Sam 1,26.27; Hi 22,27; Ps 145,19"] },
      { number: 11, text: "Und Kelub, der Bruder Schuhas, zeugte Mehir; der war der Vater Eschtons." },
      { number: 12, text: "Und Eschton zeugte Bet-Rafa und Paseach und Tehinna, den Vater der Stadt Nahasch; das sind die Männer von Recha. —" },
      { number: 13, text: "Und die Söhne des Kenas: Otniël* und Seraja. Und die Söhne Otniëls: Hatat und Meonotai*.", footnotes: ["℘ Jos 15,17", "so mit LXX und Vulg.; im Mas. T. fehlt die Namenangabe"] },
      { number: 14, text: "Und Meonotai zeugte Ofra; und Seraja zeugte Joab, den Vater des Tals der Handwerker*, denn sie waren Handwerker. —", footnotes: ["℘ Neh 11,35"] },
      { number: 15, text: "Und die Söhne Kalebs, des Sohnes des Jefunne*: Iru, Ela und Naam. Und die Söhne Elas: Kenas. —", footnotes: ["℘ 4Mo 13,6"] },
      { number: 16, text: "Und die Söhne Jehallelels: Sif und Sifa, Tirja und Asarel. —" },
      { number: 17, text: "Und die Söhne* Esras: Jeter und Mered und Efer und Jalon. Und Jeter zeugte* Mirjam und Schammai und Jischbach, den Vater Eschtemoas*.", footnotes: ["w. der Sohn", "so mit LXX; Mas. T.: Jalon. Und sie wurde schwanger und gebar", "℘ Jos 15,50"] },
      { number: 18, text: "Und seine judäische Frau gebar Jered, den Vater Gedors*, und Heber, den Vater Sochos*, und Jekutiël, den Vater Sanoachs*. Das sind die Söhne der Bitja, der Tochter des Pharao, die Mered zur Frau genommen hatte. —", footnotes: ["℘ V. 39; Jos 15,58", "℘ Jos 15,48", "℘ Jos 15,56"] },
      { number: 19, text: "Und die Söhne der Frau des Hodija, der Schwester Nahams: der Vater Keïlas, Hagarmi*, und Eschtemoa, der Maachatiter. —", footnotes: ["o. der Garmiter"] },
      { number: 20, text: "Und die Söhne Schimons: Amnon und Rinna, Ben-Hanan und Tilon. — Und die Söhne Jischis: Sohet und Ben-Sohet. —" },
      { number: 21, text: "Die Söhne Schelas, des Sohnes Judas*: Er, der Vater Lechas, und Lada, der Vater Mareschas*; und die Sippen des Hauses der Byssusbearbeiter* vom Hause Aschbea;", footnotes: ["℘ Kap. 2,3", "℘ Jos 15,44", "℘ Jes 19,9"] },
      { number: 22, text: "und Jokim und die Männer von Koseba; und Joasch und Saraf, die über Moab herrschten; und Jaschubi-Lechem. Die Berichte* sind aber alt.", footnotes: ["w. Worte, o. Dinge"] },
      { number: 23, text: "Das waren die Töpfer und die Bewohner von Netaim und Gedera; sie wohnten dort bei dem König in seinem Dienst*.", footnotes: ["℘ Spr 22,29"] },
      { number: 24, text: "*Die Söhne Simeons: Jemuël und Jamin, Jarib, Serach, Schaul*;", heading: "Stamm Simeon", footnotes: ["℘ V. 24-43: 4Mo 26,12-14", "℘ 1Mo 46,10; 2Mo 6,15"] },
      { number: 25, text: "dessen Sohn Schallum, dessen Sohn Mibsam, dessen Sohn Mischma." },
      { number: 26, text: "Und die Söhne Mischmas: dessen Sohn Hammuël, dessen Sohn Sakkur, dessen Sohn Schimi." },
      { number: 27, text: "Und Schimi hatte sechzehn Söhne und sechs Töchter; aber seine Brüder hatten nicht viele Söhne, und alle ihre Sippen vermehrten sich nicht so sehr wie die Söhne Judas." },
      { number: 28, text: "*Und sie wohnten in Beerscheba und Molada* und Hazar-Schual", footnotes: ["℘ V. 28-30: Jos 15,26-31; V. 28-33: Jos 19,2-8", "℘ Neh 11,26.27"] },
      { number: 29, text: "und in Bilha und in Ezem und in Tolad*", footnotes: ["d. i. wohl Eltolad"] },
      { number: 30, text: "und in Betuël und in Horma und in Ziklag*", footnotes: ["℘ Neh 11,28"] },
      { number: 31, text: "und in Bet-Markabot und in Hazar-Susa und in Bet-Biri und in Schaarajim. Das waren ihre Städte, bis David König wurde." },
      { number: 32, text: "Und ihre Gehöfte: Etam und Ajin*, Rimmon und Tochen und Aschan: fünf Ortschaften*,", footnotes: ["℘ Jos 21,16", "w. Städte"] },
      { number: 33, text: "samt allen ihren Gehöften, die rings um diese Ortschaften* waren bis nach Baal hin. Das waren ihre Wohnsitze; und sie hatten ihr eigenes Geschlechtsregister. —", footnotes: ["w. Städte"] },
      { number: 34, text: "Und Meschobab und Jamlech und Joscha, der Sohn Amazjas;" },
      { number: 35, text: "und Joel und Jehu, der Sohn Joschibjas, des Sohnes Serajas, des Sohnes Asiëls;" },
      { number: 36, text: "und Eljoënai und Jaakoba und Jeschohaja und Asaja und Adiël und Jesimiël und Benaja;" },
      { number: 37, text: "und Sisa, der Sohn Schifis, des Sohnes Allons, des Sohnes Jedajas, des Sohnes Schimris, des Sohnes Schemajas:" },
      { number: 38, text: "Diese mit Namen Angeführten waren Fürsten in ihren Sippen; und ihre Vaterhäuser breiteten sich sehr* aus.", footnotes: ["w. in Menge"] },
      { number: 39, text: "Und sie zogen bis nach Gedor* hin, bis an die Ostseite des Tales, um Weide für ihre Schafe zu suchen.", footnotes: ["℘ V. 18"] },
      { number: 40, text: "Und sie fanden fette und gute Weide und ein Land, geräumig nach beiden Seiten hin und ruhig und still*; denn die, die früher dort gewohnt hatten, waren von Ham.", footnotes: ["℘ Ri 18,7"] },
      { number: 41, text: "Und diese mit Namen Aufgeschriebenen kamen in den Tagen Hiskias, des Königs von Juda*, und sie zerstörten* ihre Zelte* und erschlugen die Mëuniter*, die sich dort befanden; und sie belegten sie mit dem Bann bis auf diesen Tag und wohnten an ihrer Stelle; denn dort war Weide für ihre Schafe*. —", footnotes: ["℘ Kap. 3,13", "w. schlugen", "d. h. die Zelte der Hamiten", "℘ Ri 10,12; 2Chr 20,1", "℘ 4Mo 32,1"] },
      { number: 42, text: "Und von ihnen, von den Söhnen Simeon, zogen fünfhundert Männer zum Gebirge Seïr, Pelatja und Nearja und Refaja und Usiël, die Söhne Jischis, an ihrer Spitze;" },
      { number: 43, text: "und sie erschlugen den Rest, die Entronnenen von Amalek*, und haben dort gewohnt bis zum heutigen Tag.", footnotes: ["℘ 2Mo 17,14; 1Sam 30,16.17"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "*Und die Söhne Rubens, des Erstgeborenen Israels* — denn er war der Erstgeborene; weil er aber das Lager seines Vaters entweiht hatte*, wurde sein Erstgeburtsrecht den Söhnen Josefs, des Sohnes Israels, gegeben; und er wird nicht nach der Erstgeburt im Geschlechtsregister eingetragen;", heading: "Stamm Ruben", footnotes: ["℘ V. 1-10: 4Mo 26,5-7", "℘ 1Mo 29,32", "℘ 1Mo 35,22"] },
      { number: 2, text: "denn Juda hatte die Oberhand unter seinen Brüdern, und aus ihm kommt der Fürst*; aber das Erstgeburtsrecht wurde Josef zuteil* —,", footnotes: ["℘ Kap. 28,4; 1Mo 49,8.10; Offb 5,5", "℘ 5Mo 21,17; 33,17"] },
      { number: 3, text: "die Söhne Rubens, des Erstgeborenen Israels: Henoch und Pallu, Hezron und Karmi*.", footnotes: ["℘ 1Mo 46,9; 2Mo 6,14"] },
      { number: 4, text: "Die Söhne Joels: dessen Sohn Schemaja, dessen Sohn Gog, dessen Sohn Schimi," },
      { number: 5, text: "dessen Sohn Micha, dessen Sohn Reaja, dessen Sohn Baal," },
      { number: 6, text: "dessen Sohn Beera, den Tiglat-Pileser, der König von Assur, gefangen wegführte*; er war ein Fürst der Rubeniter.", footnotes: ["℘ V. 26"] },
      { number: 7, text: "Und seine Brüder nach ihren Sippen, nach der Registrierung ihrer Generationenfolge*, waren: das Haupt: Jeïël; und Secharja", footnotes: ["hebr. toledot; d. h. w. Erzeugungen; bedeutet im AT Nachkommen, Generationenfolge, Entstehung, Entstehungsgeschichte"] },
      { number: 8, text: "und Bela, der Sohn des Asas, des Sohnes Schemas, des Sohnes Joels; dieser wohnte in Aroër und bis nach Nebo und Baal-Meon* hin;", footnotes: ["℘ Jos 13,17"] },
      { number: 9, text: "und gegen Osten wohnte er bis an die Wüste, die sich vom Euphratstrom her ausdehnt; denn ihre Herden waren zahlreich im Land Gilead*.", footnotes: ["℘ Jos 22,9"] },
      { number: 10, text: "Und in den Tagen Sauls führten sie Krieg mit den Hagaritern; und diese fielen durch ihre Hand*, und sie wohnten in deren Zelten auf der ganzen Ostseite von Gilead.", footnotes: ["℘ V. 19-22; Ps 83,7"] },
      { number: 11, text: "*Und die Söhne Gad wohnten ihnen gegenüber im Land Baschan bis nach Salcha*:", heading: "Stamm Gad — Halbstamm Manasse — Kriege, Treulosigkeit und Bestrafung der Ostjordanstämme", footnotes: ["℘ V. 11-17: 4Mo 26,15-17", "℘ Jos 13,11"] },
      { number: 12, text: "Joel, das Oberhaupt; und Schafam, der zweite; und Janai und Schafat in Baschan." },
      { number: 13, text: "Und ihre Brüder nach ihren Vaterhäusern: Michael und Meschullam und Scheba und Jorai und Jakan und Sia und Eber, zusammen sieben." },
      { number: 14, text: "Das waren die Söhne Abihajils, des Sohnes Huris, des Sohnes Jaroachs, des Sohnes Gileads, des Sohnes Michaels, des Sohnes Jeschischais, des Sohnes Jachdos, des Sohnes des Bus." },
      { number: 15, text: "Ahi, der Sohn Abdiëls, des Sohnes Gunis, war ihr Familienoberhaupt*.", footnotes: ["w. das Haupt ihres Vaterhauses"] },
      { number: 16, text: "Und sie wohnten in Gilead, in Baschan und in deren Tochterstädten und in allen Weidegebieten Scharons* bis zu ihrem Ausläufer*.", footnotes: ["℘ Kap. 27,29", "℘ Jos 13,24-28"] },
      { number: 17, text: "Diese alle sind registriert worden in den Tagen Jotams, des Königs von Juda*, und in den Tagen Jerobeams, des Königs von Israel*.", footnotes: ["℘ 2Kö 15,32", "℘ 2Kö 14,23"] },
      { number: 18, text: "Die Söhne Ruben und die Gaditer und der halbe Stamm Manasse*, was an tapferen Männern* da war, Männer, die Schild und Schwert trugen und den Bogen spannten und im Kampf erfahren waren, zählten 44 760 Mann, die mit dem Heer auszogen.", footnotes: ["℘ 4Mo 32,33; Jos 1,12", "w. Söhnen der Kraft"] },
      { number: 19, text: "Und sie führten Krieg mit den Hagaritern* und mit Jetur und Nafisch* und Nodab;", footnotes: ["℘ V. 10; Kap. 27,31", "℘ Kap. 1,31"] },
      { number: 20, text: "und es wurde ihnen im Kampf gegen sie geholfen*; und die Hagariter wurden in ihre Hand gegeben samt allen, die mit ihnen waren; denn sie hatten im Kampf zu Gott um Hilfe geschrien*, und er ließ sich von ihnen erbitten*, weil sie auf ihn vertraut hatten*.", footnotes: ["℘ 1Mo 49,19; Jos 23,10; 2Chr 26,7", "℘ 2Chr 13,14", "℘ 2Chr 18,31; Esr 8,23", "℘ 2Chr 13,18; Ps 22,5.6; 37,39.40; Spr 29,25; Jer 39,18"] },
      { number: 21, text: "Und sie führten ihr Vieh weg: 50 000 Kamele und 250 000 Schafe und 2 000 Esel und 100 000 Menschenseelen*.", footnotes: ["℘ 2Chr 14,12-14"] },
      { number: 22, text: "Denn es waren viele vom Schwert durchbohrt gefallen, weil der Kampf von Gott war*. Und sie wohnten an deren Stelle bis zur Wegführung*.", footnotes: ["℘ 1Mo 49,19; Jos 23,10; 2Chr 26,7", "℘ V. 26"] },
      { number: 23, text: "*Und die Söhne des halben Stammes Manasse wohnten im Land von Baschan bis Baal-Hermon und bis zum Senir und bis zum Berg Hermon*; sie waren zahlreich*.", footnotes: ["℘ V. 23.24: 4Mo 26,29-34", "℘ 5Mo 3,8.9", "℘ 5Mo 33,17"] },
      { number: 24, text: "Und dies waren ihre Familienoberhäupter*: nämlich Efer und Jischi und Eliël und Asriël und Jirmeja und Hodawja und Jachdiël, alles Männer, kriegstüchtige* Männer, Männer von Namen, Familienoberhäupter*.", footnotes: ["w. Häupter ihrer Vaterhäuser", "o. vermögende; o. angesehene", "o. vermögende; o. angesehene"] },
      { number: 25, text: "Aber sie handelten treulos gegen den Gott ihrer Väter und hurten den Göttern der Völker des Landes nach, die Gott vor ihnen ausgetilgt hatte*.", footnotes: ["℘ 2Kö 17,7-17"] },
      { number: 26, text: "Da erweckte der Gott Israels den Geist Puls, des Königs von Assur*, den Geist* Tilgat-Pilnesers*, des Königs von Assur, und er führte sie weg*, die Rubeniter und die Gaditer und den halben Stamm Manasse, und brachte sie nach Halach und an den Habor und nach Hara und an den Strom von Gosan* bis zum heutigen Tag.", footnotes: ["℘ V. 6; 2Kö 15,19.29; 2Chr 30,6", "Im Mas. T. steht hier: und den Geist", "Pul war der Name, den Tiglat-Pileser (hier Tilgat-Pilneser) als König von Babel trug\n℘ 1Mo 49,19; Jos 23,10; 2Chr 26,7", "℘ V. 22", "℘ 2Kö 17,6"] },
      { number: 27, text: "*Die Söhne Levis waren: Gerschon, Kehat und Merari*.", heading: "Stamm Levi", footnotes: ["℘ V. 27-30: 2Mo 6,16-25", "℘ Kap. 6,1; 15,5.6; 23,6; 4Mo 26,57"] },
      { number: 28, text: "Und die Söhne Kehats: Amram, Jizhar und Hebron* und Usiël*.", footnotes: ["℘ Kap. 15,9", "℘ Kap. 6,3; 15,10"] },
      { number: 29, text: "*Und die Söhne Amrams: Aaron und Mose*; und Mirjam. Und die Söhne Aarons: Nadab und Abihu, Eleasar und Itamar*.", footnotes: ["℘ V. 29-34: Kap. 6,35-38; V. 29-41: Esr 7,1-5", "℘ Kap. 23,13", "℘ Kap. 24,1.2; 4Mo 3,2"] },
      { number: 30, text: "Eleasar zeugte Pinhas*; Pinhas zeugte Abischua,", footnotes: ["℘ Esr 8,2"] },
      { number: 31, text: "und Abischua zeugte Bukki, und Bukki zeugte Usi," },
      { number: 32, text: "und Usi zeugte Serachja, und Serachja zeugte Merajot;" },
      { number: 33, text: "Merajot zeugte Amarja, und Amarja zeugte Ahitub," },
      { number: 34, text: "und Ahitub zeugte Zadok*, und Zadok zeugte Ahimaaz*,", footnotes: ["℘ Kap. 12,29; 2Sam 8,17; 1Kö 4,2", "℘ 2Sam 15,36"] },
      { number: 35, text: "und Ahimaaz zeugte Asarja, und Asarja zeugte Johanan," },
      { number: 36, text: "und Johanan zeugte Asarja; der ist es, der als Priester diente in dem Haus, das Salomo in Jerusalem gebaut hatte*.", footnotes: ["℘ 1Kö 6,37.38"] },
      { number: 37, text: "Und Asarja zeugte Amarja*, und Amarja zeugte Ahitub,", footnotes: ["℘ 2Chr 19,11"] },
      { number: 38, text: "und Ahitub zeugte Zadok, und Zadok zeugte Schallum," },
      { number: 39, text: "und Schallum zeugte Hilkija*, und Hilkija zeugte Asarja*,", footnotes: ["℘ 2Kö 22,4", "℘ Kap. 9,11"] },
      { number: 40, text: "und Asarja zeugte Seraja*, und Seraja zeugte Jozadak*;", footnotes: ["℘ 2Kö 25,18", "℘ Esr 3,2.8; Hag 1,1"] },
      { number: 41, text: "und Jozadak zog mit, als der HERR Juda und Jerusalem durch Nebukadnezar gefangen wegführte*.", footnotes: ["℘ 2Kö 25,21"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "*Die Söhne Levis: Gerschon, Kehat und Merari*.", footnotes: ["℘ V. 1-15: 2Mo 6,16-25; V. 1-48: vgl. 4Mo 3,14-39", "℘ Kap. 5,27; 1Mo 46,11"] },
      { number: 2, text: "Und das sind die Namen der Söhne Gerschons: Libni und Schimi*.", footnotes: ["℘ V. 27; Kap. 23,7"] },
      { number: 3, text: "Und die Söhne Kehats: Amram und Jizhar* und Hebron und Usiël*.", footnotes: ["℘ Kap. 24,22", "℘ Kap. 5,28; 15,10; 23,12"] },
      { number: 4, text: "Die Söhne Meraris*: Machli* und Muschi*. Und dies sind die Sippen der Leviten nach ihren Stammvätern:", footnotes: ["℘ Kap. 24,26", "℘ Esr 8,18", "℘ Kap. 23,21"] },
      { number: 5, text: "Von Gerschon: dessen Sohn Libni, dessen Sohn Jahat, dessen Sohn Simma*,", footnotes: ["℘ V. 27"] },
      { number: 6, text: "dessen Sohn Joach, dessen Sohn Iddo, dessen Sohn Serach*, dessen Sohn Jeotrai. —", footnotes: ["℘ V. 26"] },
      { number: 7, text: "Die Söhne Kehats: dessen Sohn Amminadab, dessen Sohn Korach*, dessen Sohn Assir*,", footnotes: ["℘ V. 22", "℘ 4Mo 26,11"] },
      { number: 8, text: "dessen Sohn Elkana und dessen Sohn Abiasaf und dessen Sohn Assir," },
      { number: 9, text: "dessen Sohn Tahat, dessen Sohn Uriël, dessen Sohn Usija, dessen Sohn Schaul." },
      { number: 10, text: "Und die Söhne Elkanas: Amasai und Ahimot;" },
      { number: 11, text: "Elkana, dessen Sohn war Elkana,* dessen Sohn Zofai und dessen Sohn Nahat,", footnotes: ["o. Elkana. Die Söhne Elkanas:"] },
      { number: 12, text: "dessen Sohn Eliab, dessen Sohn Jeroham, dessen Sohn Elkana*.", footnotes: ["℘ V. 19.20; 1Sam 1,1"] },
      { number: 13, text: "Und die Söhne Samuels*: Der Erstgeborene *Joel und der zweite Sohn Abija*. —", footnotes: ["℘ V. 18", "so mit alten Üs.; Mas. T.: Waschni und Abija", "so mit alten Üs.; Mas. T.: Waschni und Abija\n℘ 1Sam 8,2"] },
      { number: 14, text: "Die Söhne Meraris: Machli, dessen Sohn Libni, dessen Sohn Schimi, dessen Sohn Usa," },
      { number: 15, text: "dessen Sohn Schima, dessen Sohn Haggija, dessen Sohn Asaja." },
      { number: 16, text: "*Und diese sind es, die David zur Leitung des Gesanges im Haus des HERRN anstellte, nachdem die Lade einen Ruheplatz gefunden hatte*.", footnotes: ["℘ V. 16-32: Kap. 15,16-21; 25,1-31", "℘ Kap. 16,1"] },
      { number: 17, text: "Sie versahen den Dienst vor der Wohnung des Zeltes der Begegnung beim* Gesang*, bis Salomo das Haus des HERRN in Jerusalem gebaut hatte. Und sie standen nach ihrer Vorschrift ihrem Dienst vor.", footnotes: ["o. mit", "℘ Ps 81,1-3; 135,1-3"] },
      { number: 18, text: "Und diese sind es, die da standen, und ihre Söhne: Von den Söhnen der Kehatiter: Heman, der Sänger*, der Sohn Joels, des Sohnes Samuels*,", footnotes: ["℘ Kap. 15,17; Ps 88,1", "℘ V. 13"] },
      { number: 19, text: "des Sohnes Elkanas, des Sohnes Jerohams, des Sohnes Eliëls, des Sohnes Tohus," },
      { number: 20, text: "des Sohnes Zufs, des Sohnes Elkanas, des Sohnes Mahats, des Sohnes Amasais," },
      { number: 21, text: "des Sohnes Elkanas, des Sohnes Joels, des Sohnes Asarjas, des Sohnes Zefanjas," },
      { number: 22, text: "des Sohnes Tahats, des Sohnes Assirs, des Sohnes Abiasafs, des Sohnes Korachs*,", footnotes: ["℘ V. 7; Ps 42,1"] },
      { number: 23, text: "des Sohnes Jizhars, des Sohnes Kehats, des Sohnes Levis, des Sohnes Israels." },
      { number: 24, text: "Und sein Bruder Asaf*, der zu seiner Rechten stand: Asaf, der Sohn Berechjas, des Sohnes Schimas,", footnotes: ["℘ Kap. 9,15; 15,17; 16,5; Ps 50,1"] },
      { number: 25, text: "des Sohnes Michaels, des Sohnes Maasejas, des Sohnes Malkijas," },
      { number: 26, text: "des Sohnes Etnis, des Sohnes Serachs*, des Sohnes Adajas,", footnotes: ["℘ V. 6"] },
      { number: 27, text: "des Sohnes Etans, des Sohnes Simmas*, des Sohnes Schimis*,", footnotes: ["℘ V. 2.5", "℘ 4Mo 26,11"] },
      { number: 28, text: "des Sohnes Jahats, des Sohnes Gerschons, des Sohnes Levis." },
      { number: 29, text: "Und die Söhne Merari, ihre Brüder, standen zur Linken: Etan*, der Sohn Kuschajas, des Sohnes Abdis, des Sohnes Malluchs,", footnotes: ["℘ Kap. 15,17; 1Kö 5,11"] },
      { number: 30, text: "des Sohnes Haschabjas, des Sohnes Amazjas, des Sohnes Hilkijas," },
      { number: 31, text: "des Sohnes Amzis, des Sohnes Banis, des Sohnes Schemers," },
      { number: 32, text: "des Sohnes Machlis, des Sohnes Muschis, des Sohnes Meraris, des Sohnes Levis." },
      { number: 33, text: "Und ihre Brüder, die Leviten, waren für den gesamten Dienst an der Wohnung des Hauses Gottes gegeben*.", footnotes: ["℘ Kap. 23,2-5; 4Mo 3,9"] },
      { number: 34, text: "Und Aaron und seine Söhne brachten auf dem Brandopferaltar* und auf dem Rauchopferaltar* Rauchopfer dar, sie waren verantwortlich für alle Arbeit am Allerheiligsten und dazu, Sühnung zu erwirken für Israel*, nach allem, was Mose, der Knecht Gottes, geboten hatte*.", footnotes: ["℘ 3Mo 1,7-9", "℘ Kap. 23,13; 2Mo 30,7-9; 2Chr 29,11", "℘ 3Mo 16,17-19; Hebr 5,1", "℘ Kap. 24,19"] },
      { number: 35, text: "*Und dies waren die Söhne Aarons: dessen Sohn Eleasar, dessen Sohn Pinhas, dessen Sohn Abischua,", footnotes: ["℘ V. 35-38: Kap. 5,29-34"] },
      { number: 36, text: "dessen Sohn Bukki, dessen Sohn Usi, dessen Sohn Serachja," },
      { number: 37, text: "dessen Sohn Merajot, dessen Sohn Amarja, dessen Sohn Ahitub," },
      { number: 38, text: "dessen Sohn Zadok*, dessen Sohn Ahimaaz.", footnotes: ["℘ Kap. 27,17"] },
      { number: 39, text: "*Und das waren ihre Wohnsitze, nach ihren Zeltdörfern in ihrem Gebiet: Den Söhnen Aarons vom Geschlecht* der Kehatiter — denn ihnen war das erste Los zugefallen* —,", footnotes: ["℘ V. 39-45: Jos 21,9-19", "o. von der Sippe", "℘ Jos 21,4.10-19"] },
      { number: 40, text: "denen gaben sie Hebron im Land Juda und seine Weidegebiete rings um es her." },
      { number: 41, text: "Aber das Ackerland der Stadt und ihre* Gehöfte gaben sie Kaleb, dem Sohn des Jefunne*.", footnotes: ["o. seine", "℘ Jos 14,14"] },
      { number: 42, text: "Und sie gaben den Söhnen Aarons die Zufluchtsstadt* Hebron und Libna und seine Weidegebiete und Jattir und Eschtemoa und seine Weidegebiete", footnotes: ["w. Zufluchtsstädte"] },
      { number: 43, text: "und Holon und seine Weidegebiete, Debir und seine Weidegebiete" },
      { number: 44, text: "und Aschan und seine Weidegebiete und Bet-Schemesch und seine Weidegebiete." },
      { number: 45, text: "Und vom Stamm Benjamin: Geba und seine Weidegebiete und Alemet und seine Weidegebiete und Anatot und seine Weidegebiete. Alle ihre Städte zusammen: dreizehn Städte nach ihren Sippen*. —", footnotes: ["Andere lesen mit korrigiertem Text mit Jos 21,19: dreizehn Städte und ihre Weideplätze"] },
      { number: 46, text: "Und den Söhnen Kehats, die von dem Geschlecht* des Stammes noch übrig waren, gaben sie durchs Los von der Hälfte des Stammes Manasse zehn Städte*.", footnotes: ["o. von der Sippe", "w. von der Hälfte des Stammes des halben Manasse. — Andere lesen mit Textkorrektur: Und den übrigen Söhnen Kehats, ihren Sippen, gaben sie vom Stamm Ephraim und vom Stamm Dan und von der Hälfte des Stammes Manasse durchs Los zehn Städte"] },
      { number: 47, text: "Und den Söhnen Gerschons, nach ihren Sippen: vom Stamm Issaschar und vom Stamm Asser und vom Stamm Naftali und vom Stamm Manasse in Baschan dreizehn Städte*.", footnotes: ["℘ V. 56-61; Jos 21,27-33"] },
      { number: 48, text: "Den Söhnen Meraris, nach ihren Sippen: vom Stamm Ruben und vom Stamm Gad und vom Stamm Sebulon durchs Los zwölf Städte*.", footnotes: ["℘ V. 62-66; Jos 21,34-40"] },
      { number: 49, text: "Und die Söhne Israel gaben den Leviten die Städte und ihre Weidegebiete." },
      { number: 50, text: "Und zwar gaben sie durchs Los vom Stamm der Söhne Juda und vom Stamm der Söhne Simeon und vom Stamm der Söhne Benjamin diese Städte, die sie mit Namen nannten." },
      { number: 51, text: "*Und die Übrigen von den Sippen der Söhne Kehats erhielten die Städte ihres Gebietes vom Stamm Ephraim.", footnotes: ["℘ V. 51-55: Jos 21,5.20-26"] },
      { number: 52, text: "Und sie gaben ihnen die Zufluchtsstadt* Sichem und seine Weidegebiete auf dem Gebirge Ephraim und Geser und seine Weidegebiete", footnotes: ["w. Zufluchtsstädte"] },
      { number: 53, text: "und Jokmeam und seine Weidegebiete und Bet-Horon und seine Weidegebiete" },
      { number: 54, text: "und Ajalon und seine Weidegebiete und Gat-Rimmon und seine Weidegebiete." },
      { number: 55, text: "Und von der Hälfte des Stammes Manasse: Aner und seine Weidegebiete und Bileam und seine Weidegebiete — dem Geschlecht* der übrigen Söhne Kehats.", footnotes: ["o. der Sippe"] },
      { number: 56, text: "*Den Söhnen Gerschons: vom Geschlecht* des halben Stammes Manasse*: Golan in Baschan und seine Weidegebiete und Aschtarot und seine Weidegebiete;", footnotes: ["℘ V. 56-61: Jos 21,6.27-33", "o. von der Sippe", "℘ V. 47"] },
      { number: 57, text: "und vom Stamm Issaschar: Kedesch und seine Weidegebiete und Daberat und seine Weidegebiete" },
      { number: 58, text: "und Ramot* und seine Weidegebiete und Anem und seine Weidegebiete;", footnotes: ["℘ Jos 19,21"] },
      { number: 59, text: "und vom Stamm Asser: Mischal und seine Weidegebiete und Abdon und seine Weidegebiete" },
      { number: 60, text: "und Helkat und seine Weidegebiete und Rehob und seine Weidegebiete;" },
      { number: 61, text: "und vom Stamm Naftali: Kedesch in Galiläa und seine Weidegebiete und Hammon und seine Weidegebiete und Kirjatajim und seine Weidegebiete." },
      { number: 62, text: "*Den übrigen Söhnen Merari: vom Stamm Sebulon*: Rimmon und seine Weidegebiete, Tabor* und seine Weidegebiete;", footnotes: ["℘ V. 62-66: Jos 21,7.34-40", "℘ V. 48", "℘ Jos 19,22"] },
      { number: 63, text: "und vom Stamm Ruben, jenseits des Jordan gegenüber von Jericho, östlich vom Jordan: Bezer in der Steppe und seine Weidegebiete und Jahaz und seine Weidegebiete" },
      { number: 64, text: "und Kedemot und seine Weidegebiete und Mefaat und seine Weidegebiete;" },
      { number: 65, text: "und vom Stamm Gad: Ramot in Gilead und seine Weidegebiete und Mahanajim und seine Weidegebiete" },
      { number: 66, text: "und Heschbon und seine Weidegebiete und Jaser und seine Weidegebiete*.", footnotes: ["℘ 5Mo 4,43"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "*Und die Söhne Issaschars: Tola und Puwa, Jaschub und Schimron, diese vier*.", heading: "Stämme Issaschar, Benjamin, Naftali, Manasse, Ephraim, Asser", footnotes: ["℘ V. 1-5: 4Mo 26,23-25", "℘ 1Mo 46,13"] },
      { number: 2, text: "Und die Söhne Tolas: Usi und Refaja und Jeriël und Jachmai und Jibsam und Schemuël, ihre Familienoberhäupter*, von Tola, kriegstüchtige* Männer, nach ihrer Generationenfolge*; ihre Zahl war in den Tagen Davids 22 600.", footnotes: ["w. Häupter des Hauses ihrer Väter", "o. vermögende(n); o. angesehene(n)", "s. Anm. zu Kap. 5,7"] },
      { number: 3, text: "Und die Söhne Usis: Jisrachja; und die Söhne Jisrachjas: Michael und Obadja und Joel, Jischija; insgesamt fünf Oberhäupter." },
      { number: 4, text: "Und zu ihnen gehörten, nach ihrer Generationenfolge*, nach ihren Vaterhäusern, ein Kriegsheer* von 36 000 Mann, denn sie hatten viele Frauen und Kinder.", footnotes: ["s. Anm. zu Kap. 5,7", "w. Scharen des Kriegsheeres"] },
      { number: 5, text: "Und ihre Brüder, nach allen Sippen Issaschars, waren kriegstüchtige* Männer, 87 000, ergab ihre Registrierung insgesamt.", footnotes: ["o. vermögende(n); o. angesehene(n)"] },
      { number: 6, text: "*Von Benjamin: Bela und Becher und Jediaël, diese drei*.", footnotes: ["℘ V. 6-12: Kap. 8,1-28; 4Mo 26,38-41", "℘ Kap. 8,1.2; 1Mo 46,21"] },
      { number: 7, text: "Und die Söhne Belas: Ezbon und Usi und Usiël und Jerimot und Ir, diese fünf, Familienoberhäupter*, kriegstüchtige* Männer; und ihre Registrierung ergab: 22 034.", footnotes: ["w. Häupter des Hauses der Väter", "o. vermögende(n); o. angesehene(n)"] },
      { number: 8, text: "Und die Söhne Bechers: Semira und Joasch und Eliëser und Eljoënai und Omri und Jerimot und Abija und Anatot und Alemet; alle diese waren Söhne des Becher." },
      { number: 9, text: "Und ihre Registrierung nach ihrer Generationenfolge*, ihren Familienoberhäuptern*, kriegstüchtigen* Männern, ergab 20 200.", footnotes: ["s. Anm. zu Kap. 5,7", "w. den Häuptern des Hauses ihrer Väter", "o. vermögende(n); o. angesehene(n)"] },
      { number: 10, text: "Und die Söhne Jediaëls: Bilhan; und die Söhne Bilhans: Jëusch und Benjamin und Ehud* und Kenaana und Setan und Tarsis und Ahischahar.", footnotes: ["℘ Kap. 8,6"] },
      { number: 11, text: "Alle diese waren Söhne Jediaëls, nach den Familienoberhäuptern*, kriegstüchtige* Männer, 17 200, die mit dem Heer in den Krieg auszogen*. —", footnotes: ["w. den Häuptern der Väter", "o. vermögende(n); o. angesehene(n)", "℘ 2Chr 17,17.18"] },
      { number: 12, text: "Und Schuppim und Huppim, die Söhne des Ir. — Huschim, der Sohn* Ahers.", footnotes: ["w. die Söhne"] },
      { number: 13, text: "Die Söhne Naftalis*: Jachzeel und Guni und Jezer und Schillem, die Söhne der Bilha*.", footnotes: ["℘ 4Mo 26,48-50", "℘ 1Mo 46,24.25"] },
      { number: 14, text: "*Die Söhne Manasses: Asriël, den seine aramäische Nebenfrau geboren hatte; sie gebar auch Machir, den Vater Gileads*.", footnotes: ["℘ V. 14-29: 4Mo 26,28-37", "℘ Kap. 2,21; 1Mo 50,23"] },
      { number: 15, text: "Und Machir nahm eine Frau für Huppim und für Schuppim; und der Name seiner Schwester war Maacha. Und der Name des zweiten Sohnes war Zelofhad; und Zelofhad hatte nur Töchter*.", footnotes: ["℘ 4Mo 27,1"] },
      { number: 16, text: "Und Maacha, die Frau Machirs, gebar einen Sohn, und sie gab ihm den Namen Peresch. Und der Name seines Bruders war Scheresch; und dessen Söhne: Ulam und Rekem." },
      { number: 17, text: "Und die Söhne Ulams: Bedan. Das sind die Söhne Gileads, des Sohnes Machirs, des Sohnes Manasses. —" },
      { number: 18, text: "Und seine Schwester Molechet gebar Ischhod und Abiëser* und Machla. —", footnotes: ["℘ Jos 17,2"] },
      { number: 19, text: "Und die Söhne Schemidas waren Achjan und Sichem und Likhi und Aniam." },
      { number: 20, text: "Und die Söhne Ephraims: Schutelach und dessen Sohn Bered und dessen Sohn Tahat und dessen Sohn Elada und dessen Sohn Tahat" },
      { number: 21, text: "und dessen Sohn Sabad und dessen Sohn Schutelach und Eser und Elad. Und die Männer von Gat*, die Einheimischen des Landes, erschlugen sie; denn sie waren hinabgezogen, um ihnen ihre Herden wegzunehmen.", footnotes: ["℘ 1Sam 5,8"] },
      { number: 22, text: "Und ihr Vater Ephraim trauerte viele Tage; und seine Brüder kamen, um ihn zu trösten*.", footnotes: ["℘ 1Mo 37,35; Joh 11,19"] },
      { number: 23, text: "Und er ging ein zu seiner Frau, und sie wurde schwanger und gebar einen Sohn; und er gab ihm den Namen Beria, weil Unheil* in seinem Haus war.", footnotes: ["hebr. beraah; d. h. im Unheil"] },
      { number: 24, text: "Und seine Tochter war Scheera; und sie baute das untere und das obere Bet-Horon* und Usen-Scheera.", footnotes: ["℘ Jos 16,3.5"] },
      { number: 25, text: "Und sein Sohn war Refach und dessen Sohn Reschef* und dessen Sohn Telach und dessen Sohn Tahan;", footnotes: ["so mit mehreren hebr. Handschr. und einer LXX-Ausgabe; Mas. T.: Und sein Sohn war Refach und Reschef"] },
      { number: 26, text: "dessen Sohn Ladan, dessen Sohn Ammihud, dessen Sohn Elischama*,", footnotes: ["℘ 4Mo 1,10"] },
      { number: 27, text: "dessen Sohn Nun, dessen Sohn Josua*. —", footnotes: ["℘ 4Mo 13,8.16"] },
      { number: 28, text: "Und ihr Besitz und ihre Wohnsitze waren Bethel und seine Tochterstädte, und gegen Sonnenaufgang Naara, und gegen Sonnenuntergang Geser und seine Tochterstädte, und Sichem und seine Tochterstädte, bis nach Aja und seinen Tochterstädten*.", footnotes: ["℘ Jos 16,5-9"] },
      { number: 29, text: "Und in den Händen* der Söhne Manasse waren: Bet-Schean und seine Tochterstädte, Taanach und seine Tochterstädte, Megiddo und seine Tochterstädte, Dor und seine Tochterstädte. In ihnen wohnten die Söhne Josefs, des Sohnes Israels*.", footnotes: ["o. an der Seite", "℘ Jos 17,11"] },
      { number: 30, text: "*Die Söhne Assers: Jimna und Jischwa und Jischwi und Beria; und Serach war ihre Schwester*.", footnotes: ["℘ V. 30-40: 4Mo 26,44-47", "℘ 1Mo 46,17"] },
      { number: 31, text: "Und die Söhne Berias: Heber und Malkiël*; der war der Vater Birsajits.", footnotes: ["℘ 1Mo 46,17"] },
      { number: 32, text: "Und Heber zeugte Jaflet und Schemer und Hotam und ihre Schwester Schua." },
      { number: 33, text: "Und die Söhne Jaflets: Pasach und Bimhal und Aschwat. Das sind die Söhne Jaflets." },
      { number: 34, text: "Und die Söhne Schemers: Ahi und Rohga und Hubba und Aram." },
      { number: 35, text: "Und die Söhne seines Bruders Helem*: Zofach und Jimna und Schelesch und Amal.", footnotes: ["Andere lesen mit korrigiertem Text: Hotam"] },
      { number: 36, text: "Die Söhne Zofachs: Suach und Harnefer und Schual und Beri und Jimra," },
      { number: 37, text: "Bezer und Hod und Schamma und Schilscha und Jitran und Beera. —" },
      { number: 38, text: "Und die Söhne Jeters: Jefunne und Pispa und Ara. —" },
      { number: 39, text: "Und die Söhne Ullas: Arach und Hanniël und Rizja." },
      { number: 40, text: "Alle diese waren Söhne Assers, Familienoberhäupter*, auserlesene, kriegstüchtige* Männer, Oberhäupter der Fürsten. Und ihre Registrierung für den Heeresdienst im Krieg: Ihre Zahl war 26 000 Mann.", footnotes: ["w. Häupter des Hauses der Väter", "o. vermögende; o. angesehene"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "*Und Benjamin zeugte Bela, seinen Erstgeborenen*, Aschbel, den Zweiten, und Achrach, den Dritten,", heading: "Stamm Benjamin — Familie Sauls", footnotes: ["℘ V. 1-28: Kap. 7,6-12; 4Mo 26,38-41", "℘ 1Mo 46,21"] },
      { number: 2, text: "Noha, den Vierten, und Rafa, den Fünften*.", footnotes: ["℘ Kap. 7,6"] },
      { number: 3, text: "Und Bela hatte Söhne: Addar und Gera* und Abihud", footnotes: ["℘ Ri 3,15"] },
      { number: 4, text: "und Abischua und Naaman und Ahoach*", footnotes: ["℘ 2Sam 23,28"] },
      { number: 5, text: "und Gera* und Schefufan und Huram. —", footnotes: ["℘ Ri 3,15"] },
      { number: 6, text: "Und dies sind die Söhne Ehuds*, diese waren die Familienoberhäupter* der Bewohner von Geba*; und man führte sie gefangen weg nach Manahat,", footnotes: ["℘ Kap. 7,10", "w. Häupter der Väter", "℘ Jos 21,17"] },
      { number: 7, text: "nämlich Naaman und Ahija und Gera; dieser führte sie weg: Er zeugte Usa und Ahihud. —" },
      { number: 8, text: "Und Schaharajim zeugte Söhne im Gebiet* von Moab, nachdem er seine Frauen, Huschim und Baara, entlassen hatte;", footnotes: ["o. Feld"] },
      { number: 9, text: "und mit seiner Frau Hodesch zeugte er Jobab und Zibja und Mescha und Malkam" },
      { number: 10, text: "und Jëuz und Sacheja und Mirma. Das waren seine Söhne, Familienoberhäupter*.", footnotes: ["w. Häupter der Väter"] },
      { number: 11, text: "Und von Huschim zeugte er Abitub und Elpaal." },
      { number: 12, text: "Und die Söhne Elpaals: Eber und Mischam und Schemed; dieser baute Ono* und Lod* und seine Tochterstädte.", footnotes: ["℘ Esr 2,33; Neh 6,2; Apg 9,32", "℘ Ri 3,15"] },
      { number: 13, text: "Und Beria und Schema — diese waren die Familienoberhäupter* der Bewohner von Ajalon*; sie verjagten die Bewohner von Gat —", footnotes: ["w. Häupter der Väter", "℘ Jos 10,12"] },
      { number: 14, text: "und Achjo,* Schaschak und Jeremot", footnotes: ["Eine griech. Handschr. liest: ihre Brüder:"] },
      { number: 15, text: "und Sebadja und Arad und Eder" },
      { number: 16, text: "und Michael und Jischpa und Joha waren die Söhne Berias." },
      { number: 17, text: "Und Sebadja und Meschullam und Hiski und Heber" },
      { number: 18, text: "und Jischmerai und Jislia und Jobab waren die Söhne Elpaals. —" },
      { number: 19, text: "Und Jakim und Sichri und Sabdi" },
      { number: 20, text: "und Eliënai und Zilletai und Eliël" },
      { number: 21, text: "und Adaja und Beraja und Schimrat waren die Söhne Schimis. —" },
      { number: 22, text: "Und Jischpan und Eber und Eliël" },
      { number: 23, text: "und Abdon und Sichri und Hanan" },
      { number: 24, text: "und Hananja und Elam und Antotija" },
      { number: 25, text: "und Jifdeja und Pnuël waren die Söhne Schaschaks. —" },
      { number: 26, text: "Und Schamscherai und Scheharja und Atalja" },
      { number: 27, text: "und Jaareschja und Elia und Sichri waren die Söhne Jerohams." },
      { number: 28, text: "Diese waren Familienoberhäupter* nach ihrer Generationenfolge*, Oberhäupter; diese wohnten in Jerusalem*.", footnotes: ["w. Häupter der Väter", "s. Anm. zu Kap. 5,7", "℘ V. 32; Kap. 9,3.34; Jos 18,28; Neh 11,1"] },
      { number: 29, text: "*Und in Gibeon* wohnten der Vater Gibeons — und der Name seiner Frau war Maacha —,", footnotes: ["℘ V. 29-40: Kap. 9,35-44", "℘ Jos 18,25"] },
      { number: 30, text: "und sein erstgeborener Sohn war Abdon, und Zur und Kisch und Baal und Nadab" },
      { number: 31, text: "und Gedor und Achjo und Secher und Miklot;" },
      { number: 32, text: "und Miklot zeugte Schima. Und auch diese wohnten in Jerusalem bei ihren Brüdern*, ihnen gegenüber*. —", footnotes: ["℘ V. 28", "w. ihren Brüdern gegenüber"] },
      { number: 33, text: "Und Ner zeugte Kisch; und Kisch zeugte Saul*; und Saul zeugte Jonatan und Malkischua und Abinadab und Eschbaal*.", footnotes: ["℘ 1Sam 9,2", "℘ 1Sam 14,49.51; 2Sam 2,8"] },
      { number: 34, text: "Und der Sohn Jonatans war Merib-Baal*; und Merib-Baal zeugte Micha*.", footnotes: ["℘ 2Sam 4,4", "℘ 2Sam 9,12"] },
      { number: 35, text: "Und die Söhne Michas waren Piton und Melech und Tachrea und Ahas." },
      { number: 36, text: "Und Ahas zeugte Joadda; und Joadda zeugte Alemet und Asmawet und Simri; und Simri zeugte Moza;" },
      { number: 37, text: "und Moza zeugte Bina: Dessen Sohn war Rafa, dessen Sohn Elasa, dessen Sohn Azel." },
      { number: 38, text: "Und Azel hatte sechs Söhne; und dies sind ihre Namen: Asrikam, Bochru* und Ismael und Schearja und Obadja und Hanan. Alle diese waren Söhne Azels.", footnotes: ["Einige hebr. Handschr., LXX lesen: Asrikam, sein Erstgeborener"] },
      { number: 39, text: "Und die Söhne seines Bruders Eschek: Ulam, sein Erstgeborener, Jëusch, der Zweite, und Elifelet, der Dritte." },
      { number: 40, text: "Und die Söhne Ulams waren Männer, kriegstüchtige* Männer, die den Bogen spannten*; und sie hatten viele Söhne und Enkel, 150. Alle diese sind von den Söhnen Benjamin.", footnotes: ["o. angesehene; o. vermögende", "℘ Kap. 12,2"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "*Und ganz Israel wurde registriert*; und siehe, sie sind aufgeschrieben in dem Buch der Könige von Israel*. Und Juda wurde wegen seiner Untreue gefangen nach Babel weggeführt*.", heading: "Bewohner Jerusalems", footnotes: ["℘ V. 2-9: Neh 11,1-9", "℘ Neh 7,5", "℘ 1Kö 14,19", "℘ 2Kö 24,15.16; Esr 2,1; Jes 3,2; Jer 13,19; Mt 1,11"] },
      { number: 2, text: "Und die ersten Bewohner, die auf ihrem Grundbesitz in ihren Städten* wohnten, waren Israeliten*, die Priester, die Leviten und die Tempeldiener*.", footnotes: ["℘ Esr 2,1", "w. Israel. — Gemeint ist wohl das Volk im Unterschied zu den anschließend genannten Klassen.", "℘ Esr 2,43; Neh 10,29"] },
      { number: 3, text: "Und in Jerusalem wohnten einige von den Söhnen Juda und von den Söhnen Benjamin* und von den Söhnen Ephraim und Manasse*:", footnotes: ["℘ Kap. 8,28.32", "℘ 2Chr 30,11"] },
      { number: 4, text: "Utai, der Sohn Ammihuds, des Sohnes Omris, des Sohnes Imris, des Sohnes Banis, von den Söhnen des Perez, des Sohnes Judas*;", footnotes: ["℘ 1Mo 46,12"] },
      { number: 5, text: "und von den Schelanitern*: Asaja, der Erstgeborene, und seine Söhne;", footnotes: ["℘ 4Mo 26,20"] },
      { number: 6, text: "und von den Söhnen Serachs*: Jëuël und seine Brüder, insgesamt 690.", footnotes: ["℘ 1Mo 46,12"] },
      { number: 7, text: "Und von den Söhnen Benjamin*: Sallu, der Sohn Meschullams, des Sohnes Hodawjas, des Sohnes Senuas;", footnotes: ["℘ Kap. 8,28.32"] },
      { number: 8, text: "und Jibneja, der Sohn Jerohams; und Ela, der Sohn Usis, des Sohnes Michris; und Meschullam, der Sohn Schefatjas, des Sohnes Reguëls, des Sohnes Jibnijas;" },
      { number: 9, text: "und ihre Brüder nach ihrer Generationenfolge*, 956. Alle diese Männer waren Familienoberhäupter über ihre Vaterhäuser*.", footnotes: ["s. Anm. zu Kap. 5,7", "w. Häupter der Väter für das Haus ihrer Väter"] },
      { number: 10, text: "*Und von den Priestern: Jedaja und Jojarib und Jachin;", footnotes: ["℘ V. 10-13: Neh 11,10-14"] },
      { number: 11, text: "und Asarja, der Sohn Hilkijas, des Sohnes Meschullams, des Sohnes Zadoks, des Sohnes Merajots, des Sohnes Ahitubs*, Fürst des Hauses Gottes*;", footnotes: ["℘ Kap. 5,38.39", "℘ Kap. 24,5; 2Sam 8,17; 2Chr 31,13"] },
      { number: 12, text: "und Adaja, der Sohn Jerohams, des Sohnes Paschhurs*, des Sohnes Malkijas*; und Masai, der Sohn Adiëls, des Sohnes Jachseras, des Sohnes Meschullams, des Sohnes Meschillemots, des Sohnes Immers*;", footnotes: ["℘ Esr 2,38", "℘ Jer 21,1", "℘ Esr 2,37"] },
      { number: 13, text: "und ihre Brüder, Familienoberhäupter*, 1 760, tüchtige* Männer in der Arbeit des Dienstes des Hauses Gottes.", footnotes: ["w. Häupter ihrer Väter", "o. angesehene"] },
      { number: 14, text: "*Und von den Leviten: Schemaja, der Sohn Haschubs, des Sohnes Asrikams, des Sohnes Haschabjas, von den Söhnen Meraris;", footnotes: ["℘ V. 14-34: vgl. Kap. 25; 26; Neh 11,15-23"] },
      { number: 15, text: "und Bakbukja, Heresch und Galal und Mattanja, der Sohn Michas, des Sohnes Sichris, des Sohnes Asafs*;", footnotes: ["℘ Kap. 6,24"] },
      { number: 16, text: "und Obadja, der Sohn Schemajas, des Sohnes Galals, des Sohnes Jedutuns; und Berechja, der Sohn Asas, des Sohnes Elkanas, der in den Gehöften der Netofatiter* wohnte.", footnotes: ["℘ Kap. 2,54; Neh 12,28"] },
      { number: 17, text: "Und die Torhüter*: Schallum und Akkub* und Talmon und *Ahiman; und ihr Bruder Schallum* war das Oberhaupt", footnotes: ["℘ Kap. 23,5", "℘ Esr 2,42", "Mehrere hebr. Handschr. und LXX lesen: Ahiman und ihre Brüder. Schallum", "Mehrere hebr. Handschr. und LXX lesen: Ahiman und ihre Brüder. Schallum"] },
      { number: 18, text: "und hat bis heute die Wache am Königstor* im Osten. Sie waren die Torhüter für die Lager der Söhne Levis.", footnotes: ["℘ 2Kö 16,18"] },
      { number: 19, text: "Und Schallum, der Sohn des Kore, des Sohnes Abiasafs, des Sohnes Korachs, und seine Brüder vom Haus seines Vaters, die Korachiter*, waren über die Arbeit des Dienstes als Wächter an den Schwellen des Zeltes gesetzt. Und ihre Väter waren einst über das Lager des HERRN als Hüter des Eingangs eingesetzt*.", footnotes: ["℘ 4Mo 26,11", "℘ 2Kö 12,10"] },
      { number: 20, text: "Und Pinhas, der Sohn Eleasars, war vorher Fürst über sie*. Der HERR war mit ihm*.", footnotes: ["℘ Jos 22,13", "℘ 1Mo 39,2.21; 2Mo 3,12"] },
      { number: 21, text: "Secharja, der Sohn Meschelemjas, war Torhüter am Eingang des Zeltes der Begegnung." },
      { number: 22, text: "Sie alle, die als Torwächter an den Schwellen ausgewählt waren, zählten 212 Mann. Ihre Registrierung fand in ihren Gehöften statt. David und der Seher Samuel* hatten sie in ihr Amt* eingesetzt.", footnotes: ["℘ Kap. 29,29; 1Sam 9,9.11", "w. in ihre Treue; hier: ihre Amtspflicht"] },
      { number: 23, text: "Und sie und ihre Söhne standen an den Toren des Hauses des HERRN, des Zelthauses, als Wachen*.", footnotes: ["℘ 2Chr 23,19"] },
      { number: 24, text: "Die Torhüter standen nach den vier Winden: nach Osten, nach Westen, nach Norden und nach Süden*.", footnotes: ["℘ 2Chr 8,14"] },
      { number: 25, text: "Ihre Brüder in ihren Gehöften mussten alle sieben Tage, von einem Zeitpunkt zum andern, mit ihnen hereinkommen*.", footnotes: ["℘ 2Chr 23,4"] },
      { number: 26, text: "Denn in ständiger Amtspflicht* waren nur sie, die vier Obersten* der Torhüter, *das sind die Leviten. Und sie waren* über die Zellen und über die Schätze des Hauses Gottes eingesetzt.", footnotes: ["w. in ständiger Treue", "o. Gewaltigen", "Andere üs. mit Textkorrektur: und von den Leviten waren einige", "Andere üs. mit Textkorrektur: und von den Leviten waren einige"] },
      { number: 27, text: "Und sie übernachteten rings um das Haus her*; denn ihnen war die Wache übertragen, und sie hatten den Schlüssel*, um Morgen für Morgen zu öffnen*.", footnotes: ["℘ Ps 134,1", "w. waren über das Öffnen", "℘ Jer 35,4"] },
      { number: 28, text: "Und einige von ihnen* waren zur Aufsicht über die Geräte für den Dienst eingesetzt*; denn abgezählt* brachten sie sie hinein, und abgezählt* brachten sie sie heraus.", footnotes: ["d. h. von den Leviten (V. 14)", "℘ 4Mo 4,12", "w. nach der Zahl", "w. nach der Zahl"] },
      { number: 29, text: "Und einige von ihnen waren eingesetzt über die Geräte, und zwar über alle Geräte des Heiligtums und über den Weizengrieß und den Wein und das Öl und den Weihrauch und die Balsamöle*.", footnotes: ["℘ 2Mo 30,23-25.35"] },
      { number: 30, text: "Und von den Söhnen der Priester mischten einige die Salbenmischung aus den Balsamölen*.", footnotes: ["℘ 2Mo 30,23-25.35"] },
      { number: 31, text: "Und Mattitja von den Leviten — er war der Erstgeborene Schallums, des Korachiters — war das Pfannen-Backwerk anvertraut*.", footnotes: ["w. war in Treue; d. h. war in Amtspflicht über das Pfannenbackwerk\n℘ 3Mo 6,14"] },
      { number: 32, text: "Und von den Söhnen der Kehatiter, ihren Brüdern, waren einige über das Schaubrot* eingesetzt, um es Sabbat für Sabbat zuzurichten*.", footnotes: ["w. das aufgeschichtete Brot", "℘ 3Mo 24,5-8"] },
      { number: 33, text: "Und das waren die Sänger, die Familienoberhäupter* der Leviten, die, von anderen Diensten befreit*, in den Zellen wohnten; denn Tag und Nacht waren sie im Dienst*.", footnotes: ["w. die Häupter der Väter", "o. der Leviten, die, wenn sie dienstfrei hatten", "℘ Ps 134,1"] },
      { number: 34, text: "Das waren die Familienoberhäupter* der Leviten nach ihrer Generationenfolge*, die Oberhäupter; diese wohnten in Jerusalem*.", footnotes: ["w. die Häupter der Väter", "s. Anm. zu Kap. 5,7", "℘ Kap. 8,28"] },
      { number: 35, text: "*Und in Gibeon wohnten der Vater Gibeons, Jeïël — und der Name seiner Frau war Maacha —,", heading: "Bewohner Gibeons — Familie Sauls", footnotes: ["℘ Kap. 8,29-40"] },
      { number: 36, text: "und sein erstgeborener Sohn Abdon; und Zur und Kisch und Baal und Ner und Nadab" },
      { number: 37, text: "und Gedor und Achjo und Secher und Miklot;" },
      { number: 38, text: "und Miklot zeugte Schima. Und auch diese wohnten mit ihren Brüdern in Jerusalem, ihnen gegenüber*. —", footnotes: ["w. ihren Brüdern gegenüber"] },
      { number: 39, text: "Und Ner zeugte Kisch, und Kisch zeugte Saul; und Saul zeugte Jonatan und Malkischua und Abinadab und Eschbaal." },
      { number: 40, text: "Und der Sohn Jonatans war Merib-Baal; und Merib-Baal zeugte Micha." },
      { number: 41, text: "Und die Söhne Michas waren Piton und Melech und Tachrea." },
      { number: 42, text: "Und Ahas zeugte Jara, und Jara zeugte Alemet und Asmawet und Simri; und Simri zeugte Moza," },
      { number: 43, text: "und Moza zeugte Bina; und dessen Sohn war Refaja, dessen Sohn Elasa, dessen Sohn Azel." },
      { number: 44, text: "Und Azel hatte sechs Söhne; und das sind ihre Namen: Asrikam, Bochru* und Ismael und Schearja und Obadja und Hanan. Das waren die Söhne Azels.", footnotes: ["s. Anm. zu Kap. 8,38"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "*Und die Philister kämpften gegen Israel; und die Männer von Israel flohen vor den Philistern, und vom Schwert Durchbohrte fielen auf dem Gebirge Gilboa.", heading: "Sauls letzte Schlacht gegen die Philister und Tod", footnotes: ["℘ 1Sam 31"] },
      { number: 2, text: "Und die Philister setzten Saul und seinen Söhnen nach*; und sie* erschlugen Jonatan, Abinadab und Malkischua, die Söhne Sauls.", footnotes: ["o. Und die Philister bekamen Saul und seine Söhne zu fassen", "w. und die Philister"] },
      { number: 3, text: "Und der Kampf tobte heftig um Saul, und die Bogenschützen erreichten ihn; und er zitterte vor den Schützen*.", footnotes: ["Andere üs. mit einer LXX-Ausgabe: und er wurde von den Schützen verwundet"] },
      { number: 4, text: "Da sagte Saul zu seinem Waffenträger: Zieh dein Schwert und durchbohre mich damit, damit diese Unbeschnittenen nicht kommen und ihren Mutwillen mit mir treiben! Sein Waffenträger aber wollte nicht, denn er fürchtete sich sehr. Da nahm Saul das Schwert und stürzte sich hinein." },
      { number: 5, text: "Und als sein Waffenträger sah, dass Saul tot war, stürzte auch er sich in das Schwert und starb." },
      { number: 6, text: "So starben Saul und seine drei Söhne; und sein ganzes Haus starb zugleich mit ihm." },
      { number: 7, text: "Als aber alle Männer von Israel, die in der Ebene wohnten, sahen, dass sie geflohen und Saul und seine Söhne tot waren, verließen sie ihre Städte und flohen. Und die Philister kamen und wohnten darin." },
      { number: 8, text: "Und es geschah am folgenden Tag, da kamen die Philister, um die Erschlagenen auszuplündern; und sie fanden Saul und seine Söhne, wie sie gefallen auf dem Gebirge Gilboa lagen." },
      { number: 9, text: "Und sie plünderten ihn aus und nahmen seinen Kopf und seine Waffen; und sie sandten* im Land der Philister umher, um die Freudenbotschaft ihren Götzen und dem Volk zu verkünden.", footnotes: ["o. und sie sandten sie"] },
      { number: 10, text: "Und sie legten seine Waffen in das Haus ihres Gottes, und seinen Schädel nagelten sie an das Haus Dagons*. —", footnotes: ["℘ 1Sam 5,2"] },
      { number: 11, text: "Als aber ganz Jabesch-Gilead alles hörte, was die Philister Saul angetan hatten," },
      { number: 12, text: "machten sich alle tüchtigen Männer* auf und nahmen die Leiche Sauls und die Leichen seiner Söhne und brachten sie nach Jabesch*; und sie begruben ihre Gebeine unter der Terebinthe bei Jabesch* und fasteten sieben Tage.", footnotes: ["w. alle Männer der Kraft", "℘ 1Sam 11,1", "℘ Ps 134,1"] },
      { number: 13, text: "So starb Saul wegen seiner Untreue, die er gegen den HERRN begangen hatte in Bezug auf das Wort des HERRN, das er nicht beachtet hatte*, und auch, weil er den Totengeist befragt hatte, um Rat zu suchen*;", footnotes: ["℘ 1Sam 13,13; 15,11.23; Ps 25,3; 73,27; Spr 2,22", "℘ 1Sam 28,7.8; Röm 6,23"] },
      { number: 14, text: "aber bei dem HERRN hatte er keinen Rat gesucht*. Darum ließ er ihn sterben und wandte das Königtum David, dem Sohn Isais, zu*.", footnotes: ["℘ Jos 9,14; 2Chr 16,12", "℘ Apg 13,22"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "*Und ganz Israel versammelte sich bei David in Hebron. Und sie sagten: Siehe, wir sind dein Gebein und dein Fleisch.", heading: "Davids Salbung zum König — Eroberung Jerusalems", footnotes: ["℘ V. 1-3: Kap. 12,24-41; V. 1-9: 2Sam 5,1-10"] },
      { number: 2, text: "Schon früher*, schon als Saul König war, bist du es gewesen, der Israel ins Feld hinausführte und wieder heimbrachte. Und der HERR, dein Gott, hat zu dir gesprochen: Du sollst mein Volk Israel weiden, und du sollst Fürst sein über mein Volk Israel!*", footnotes: ["w. schon gestern und schon vorgestern", "℘ Mt 2,6"] },
      { number: 3, text: "Und alle Ältesten Israels kamen zum König nach Hebron, und David schloss vor dem HERRN einen Bund mit ihnen in Hebron. Und sie salbten David zum König über Israel, nach dem Wort des HERRN durch Samuel*.", footnotes: ["℘ V. 10; 1Sam 16,13"] },
      { number: 4, text: "Und David und ganz Israel zogen nach Jerusalem, das ist Jebus; und dort waren die Jebusiter, die Bewohner des Landes." },
      { number: 5, text: "Und die Bewohner von Jebus sagten zu David: Du wirst nicht hier hereinkommen! Aber David nahm die Bergfeste Zion ein, das ist die Stadt Davids." },
      { number: 6, text: "Und David sagte: Wer die Jebusiter zuerst schlägt, soll Oberhaupt und Oberster werden. Da stieg Joab, der Sohn der Zeruja, zuerst hinauf, und er wurde Oberhaupt*.", footnotes: ["℘ Kap. 27,34; 2Sam 8,16"] },
      { number: 7, text: "Und David wohnte in der Bergfeste; darum nannte man sie Stadt Davids." },
      { number: 8, text: "Und er baute die Stadt ringsum, vom Millo* an rund umher*. Und Joab stellte die übrige Stadt wieder her*.", footnotes: ["d. h. Aufschüttung; der Millo diente zur Befestigung der Stadt", "w. bis zum Umkreis; 2Sam 5,9 hat hier: nach innen zu", "o. ließ die übrige Stadt am Leben; w. belebte das Übrige der Stadt"] },
      { number: 9, text: "Und David wurde immer mächtiger, und der HERR der Heerscharen war mit ihm." },
      { number: 10, text: "*Und das sind die Oberhäupter der Helden*, die David hatte, die ihm mit ganz Israel mutig beistanden* in seiner Königsherrschaft, um ihn zum König zu machen* nach dem Wort des HERRN über Israel*.", heading: "Davids Helden", footnotes: ["℘ Kap. 27,1-15; 2Sam 23,8-39", "o. Gewaltigen", "o. fest zu ihm hielten", "℘ Kap. 12,24.39", "℘ V. 3"] },
      { number: 11, text: "Und dies ist die Zahl der Helden*, die David hatte: Joschobam, der Sohn Hachmonis, das Haupt der »Drei«*; er schwang seinen Speer über dreihundert Mann, die er auf einmal erschlagen hatte.", footnotes: ["o. Gewaltigen", "So liest eine Ausgabe der LXX; mit der Schreibform des Mas. T.: das Haupt der Dreißig; mit der Leseform: das Haupt der Offiziere"] },
      { number: 12, text: "Und nach ihm kommt Eleasar, der Sohn des Dodo, der Ahoachiter; er war unter den drei Helden." },
      { number: 13, text: "Er war mit David in Pas-Dammim*, als die Philister dort zum Kampf versammelt waren. Da war ein Feldstück voller Gerste; und das Volk floh vor den Philistern.", footnotes: ["℘ 1Sam 17,1"] },
      { number: 14, text: "Da stellten sie sich* mitten auf das Stück und entrissen es ihnen und schlugen die Philister; so schaffte der HERR eine große Rettung.", footnotes: ["das sind Eleasar und David"] },
      { number: 15, text: "Und drei von den dreißig Helden* gingen zu dem Felsen hinab, zu David in die Höhle Adullam*; und das Heer der Philister lagerte in der Ebene Refaïm.", footnotes: ["w. Häuptern\n℘ Kap. 12,4", "℘ 1Sam 22,1"] },
      { number: 16, text: "David war aber damals in der Bergfeste*, und ein Posten der Philister war damals in Bethlehem.", footnotes: ["℘ 1Sam 22,5"] },
      { number: 17, text: "Und David verspürte ein Verlangen und sagte: Wer gibt mir Wasser zu trinken aus der Zisterne in Bethlehem, die im Tor ist?" },
      { number: 18, text: "Da drangen die Drei in das Heerlager der Philister ein und schöpften Wasser aus der Zisterne von Bethlehem, die im Tor ist, und nahmen es mit und brachten es zu David. Aber David wollte es nicht trinken, sondern goss es als Trankopfer für den HERRN aus." },
      { number: 19, text: "Und er sagte: Das lasse mein Gott fern von mir sein, dass ich das tue! Sollte ich das Blut dieser Männer trinken, die um ihr Leben hingegangen sind? Denn um ihr Leben haben sie es mir gebracht. Und er wollte es nicht trinken. Das haben die drei Helden getan." },
      { number: 20, text: "Und Abischai*, der Bruder Joabs, er war das Oberhaupt der Dreißig*. Und er schwang seinen Speer über dreihundert, die er erschlagen hatte; aber er hatte keinen Namen unter den Dreien.", footnotes: ["℘ Kap. 2,16", "so mit der syr. Üs.; Mas. T.: unter den Dreien"] },
      { number: 21, text: "Vor den Dreißig* war er geehrt *neben den Zweien*, so dass er ihr Oberster wurde; aber an die ersten Drei reichte er nicht heran.", footnotes: ["so mit der syr. Üs.; Mas. T.: unter den Dreien", "Der Mas. T. ist hier unklar. Die Worte fehlen in der syr. Üs.", "Der Mas. T. ist hier unklar. Die Worte fehlen in der syr. Üs."] },
      { number: 22, text: "Benaja*, der Sohn Jojadas, ein tüchtiger Mann*, groß an Taten, aus Kabzeel, der erschlug die beiden Kriegshelden* von Moab. Und er stieg hinab und erschlug den Löwen in der Zisterne an einem Schneetag.", footnotes: ["℘ Kap. 12,28", "w. der Sohn eines Mannes der Kraft", "Der Sinn des hebr. Wortes ist nicht gesichert. Andere üs.: Gotteslöwen"] },
      { number: 23, text: "Und er war es, der den ägyptischen Mann erschlug, einen Mann von fünf Ellen Länge. Und der Ägypter hatte einen Speer in der Hand, der war wie ein Weberbaum. Er aber ging mit einem Stock zu ihm hinab und riss dem Ägypter den Speer aus der Hand und brachte ihn mit dessen eigenem Speer um." },
      { number: 24, text: "Das tat Benaja, der Sohn Jojadas; und er hatte einen Namen unter den dreißig Helden*.", footnotes: ["Andere üs.: aber unter die drei Helden wurde er nicht versetzt\n℘ Kap. 12,28"] },
      { number: 25, text: "Mehr als die Dreißig — siehe — war er geehrt, aber an die Drei reichte er nicht heran. Und David setzte ihn über seine Leibwache." },
      { number: 26, text: "Und kriegstüchtige Helden* waren: Asaël, der Bruder Joabs; Elhanan, der Sohn des Dodo, aus Bethlehem;", footnotes: ["w. die Starken der Streitkräfte"] },
      { number: 27, text: "Schammot, der Haroditer; Helez, der Peletiter;" },
      { number: 28, text: "Ira, der Sohn des Ikkesch, der Tekoïter; Abiëser, der Anatotiter;" },
      { number: 29, text: "Sibbechai, der Huschatiter*; Ilai, der Ahoachiter;", footnotes: ["℘ 2Sam 21,18"] },
      { number: 30, text: "Mahrai, der Netofatiter; Heled, der Sohn Baanas, der Netofatiter*;", footnotes: ["℘ Kap. 2,54"] },
      { number: 31, text: "Ittai, der Sohn Ribais, aus Gibea der Söhne Benjamin; Benaja, der Piratoniter;" },
      { number: 32, text: "Hurai*, aus Nahale-Gaasch; Abiël, der Arbatiter;", footnotes: ["Andere lesen mit 2Sam 23,30: Hiddai"] },
      { number: 33, text: "Asmawet, der Bahurimiter; Eljachba, der Schaalboniter;" },
      { number: 34, text: "von den Söhnen des Jaschen*, der Guniter; Jonatan, der Sohn Schages, der Harariter;", footnotes: ["so mit 2Sam 23,32; Mas. T.: des Haschem"] },
      { number: 35, text: "Ahiam, der Sohn Sachars, der Harariter; Elifal, der Sohn des Ur;" },
      { number: 36, text: "Hefer, der Mecheratiter; Ahija, der Paloniter;" },
      { number: 37, text: "Hezro, der Karmeliter; Naarai, der Sohn Esbais;" },
      { number: 38, text: "Joel, der Bruder Nathans; Mibhar, der Sohn Hagris;" },
      { number: 39, text: "Zelek, der Ammoniter; Nachrai, der Beerotiter, der Waffenträger Joabs, des Sohnes der Zeruja;" },
      { number: 40, text: "Ira, der Jattiriter*; Gareb, der Jattiriter;", footnotes: ["℘ Kap. 2,53"] },
      { number: 41, text: "Uria, der Hetiter; Sabad, der Sohn Achlais;" },
      { number: 42, text: "Adina, der Sohn Schisas, der Rubeniter, ein Oberhaupt der Rubeniter, und dreißig Mann bei ihm;" },
      { number: 43, text: "Hanan, der Sohn Maachas; und Joschafat, der Mitniter;" },
      { number: 44, text: "Usija, der Aschtarotiter; Schama und Jeïël, die Söhne Hotams, des Aroëriters*;", footnotes: ["℘ 1Sam 30,28"] },
      { number: 45, text: "Jediaël, der Sohn Schimris, und Joha, sein Bruder, der Tiziter;" },
      { number: 46, text: "Eliël, der Mahawiter*; und Jeribai und Joschawja, die Söhne Elnaams; und Jitma, der Moabiter;", footnotes: ["T.; Mas. T.: der Machawim"] },
      { number: 47, text: "Eliël und Obed, und Jaasiël, der Mezobaïter*.", footnotes: ["Andere lesen: Jaasiël aus Zoba"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "Und diese sind es, die zu David nach Ziklag* kamen, als er sich noch vor Saul, dem Sohn des Kisch, verborgen hielt; auch sie waren unter den Helden, als Helfer im Kampf,", heading: "Davids Anhänger zur Zeit Sauls", footnotes: ["℘ 1Sam 27,6"] },
      { number: 2, text: "ausgerüstet mit dem Bogen und geschickt, mit der Rechten und mit der Linken Steine zu schleudern und Pfeile mit dem Bogen abzuschießen*. Von den Brüdern Sauls, aus Benjamin:", footnotes: ["℘ Kap. 8,40; Ri 20,16"] },
      { number: 3, text: "das Oberhaupt Ahiëser, und Joasch, die Söhne Schemaas, des Gibeatiters; und Jesiël und Pelet, die Söhne Asmawets*; und Beracha, und Jehu, der Anatotiter;", footnotes: ["℘ 2Sam 23,31"] },
      { number: 4, text: "und Jischmaja, der Gibeoniter, ein Held unter den Dreißig und Anführer über die Dreißig*;", footnotes: ["℘ Kap. 11,15.25"] },
      { number: 5, text: "und Jirmeja und Jahasiël und Johanan, und Josabad, der Gederatiter;" },
      { number: 6, text: "Elusai und Jerimot und Bealja und Schemarja, und Schefatja, der Harufiter;" },
      { number: 7, text: "Elkana und Jischija und Asarel und Joëser und Joschobam, die Korachiter;" },
      { number: 8, text: "und Joëla und Sebadja, die Söhne Jerohams, von Gedor. —" },
      { number: 9, text: "Und von den Gaditern gingen tapfere Helden zu David über, zur Bergfeste in die Wüste, Männer des Heeres, zum Kampf mit Schild und Spieß ausgerüstet, deren Gesichter wie Löwengesichter waren* und die schnell wie Gazellen auf den Bergen waren*:", footnotes: ["℘ 5Mo 33,20", "℘ 1Mo 49,19; 2Sam 2,18"] },
      { number: 10, text: "Eser, das Oberhaupt, Obadja, der zweite, Eliab, der dritte," },
      { number: 11, text: "Mischmanna, der vierte; Jirmeja, der fünfte," },
      { number: 12, text: "Attai, der sechste, Eliël, der siebte," },
      { number: 13, text: "Johanan, der achte, Elsabad, der neunte," },
      { number: 14, text: "Jirmeja, der zehnte, Machbannai, der elfte." },
      { number: 15, text: "Diese Männer von den Söhnen Gad waren Oberhäupter des Heeres, und zwar jeder; der Kleinste konnte es mit hundert und der Größte mit tausend aufnehmen*.", footnotes: ["o. der Kleinste war Oberhaupt für hundert und der Größte für tausend"] },
      { number: 16, text: "Diese sind es, die im ersten Monat über den Jordan gingen, als er alle seine Ufer überflutet hatte*, und die alle Täler, gegen Osten und gegen Westen, abriegelten*.", footnotes: ["℘ Jos 3,15", "o. und die alle Bewohner der Täler gegen Osten und gegen Westen in die Flucht jagten"] },
      { number: 17, text: "Und es kamen einige von den Söhnen Benjamin und Juda in die Bergfeste zu David." },
      { number: 18, text: "Und David ging hinaus, ihnen entgegen, und er fing an und sagte zu ihnen: Wenn ihr zum Frieden zu mir gekommen seid*, um mir zu helfen, dann wird mein Herz sich mit euch vereinigen*; wenn aber, um mich an meine Gegner zu verraten, ohne dass Gewalttat in meiner Hand ist, dann soll der Gott unserer Väter es sehen und strafen*!", footnotes: ["℘ 1Sam 16,4", "℘ 2Kö 10,15", "℘ 1Sam 24,12.13.16"] },
      { number: 19, text: "Da kam der Geist* über* Amasai*, das Oberhaupt der Dreißig*: Dein sind wir, David, und zu dir, Sohn Isais, stehen wir! Friede*, Friede dir*, und Friede deinen Helfern! Denn dein Gott hilft dir*! Und David nahm sie auf und reihte sie unter die Oberhäupter der Streifschar ein.", footnotes: ["℘ Ri 6,34", "w. Und der Geist bekleidete", "℘ 2Sam 17,25", "so mit der Schreibform des Mas. T.; mit der Leseform: das Oberhaupt der Offiziere", "o. Heil", "℘ 1Mo 43,23", "℘ Sach 8,2"] },
      { number: 20, text: "Und von Manasse liefen einige zu David über, als er mit den Philistern gegen Saul in den Kampf zog. Aber er half* ihnen nicht; denn nach einer Beratung schickten ihn die Fürsten der Philister weg, indem sie sagten: Um den Preis unserer Köpfe könnte er* zu seinem Herrn, zu Saul, überlaufen*!", footnotes: ["so mit LXX; Mas. T.: sie halfen", "o. wird er", "℘ 1Sam 29,4"] },
      { number: 21, text: "Als er nun nach Ziklag zog*, liefen von Manasse zu ihm über: Adnach und Josabad und Jediaël und Michael und Josabad und Elihu und Zilletai, Oberhäupter der Tausendschaften von Manasse.", footnotes: ["℘ 1Sam 30,1"] },
      { number: 22, text: "Und sie halfen David gegen die Streifschar*, denn sie waren alle kriegstüchtige* Männer; und sie wurden Oberste im Heer.", footnotes: ["℘ 1Sam 30,1", "o. vermögende; o. angesehene"] },
      { number: 23, text: "Denn es kamen von Tag zu Tag Leute zu David, um ihm zu helfen, bis es ein großes Heerlager wurde wie ein Heerlager Gottes*.", footnotes: ["℘ 1Mo 32,3"] },
      { number: 24, text: "*Und dies sind die Zahlen* der zum Heeresdienst Gerüsteten, die zu David nach Hebron kamen, um ihm das Königreich Sauls zuzuwenden nach dem Befehl* des HERRN*:", heading: "Davids Heer in Hebron", footnotes: ["℘ Kap. 11,1-3; 2Sam 5,1-3", "w. Köpfe", "w. Mund", "℘ Kap. 11,10; 1Mo 49,10"] },
      { number: 25, text: "*Die Söhne Juda, die Schild und Spieß trugen, 6 800 zum Heeresdienst Gerüstete.", footnotes: ["℘ V. 25-38: 1Mo 35,23-26"] },
      { number: 26, text: "Von den Söhnen Simeon: 7 100 zum Heeresdienst tüchtige Männer*.", footnotes: ["o. vermögende Männer zum Heer"] },
      { number: 27, text: "Von den Söhnen Levi: 4 600;" },
      { number: 28, text: "und Jojada*, der Fürst des Hauses Aaron, und mit ihm 3 700;", footnotes: ["℘ Kap. 11,22.24; 27,5"] },
      { number: 29, text: "und Zadok*, ein junger kriegstüchtiger* Mann, und das Haus seines Vaters: 22 Oberste.", footnotes: ["℘ Kap. 5,34; 27,17; 2Sam 8,17", "o. vermögender; o. angesehener"] },
      { number: 30, text: "Und von den Söhnen Benjamin, den Brüdern Sauls: 3 000. Aber der größte Teil von ihnen hielt bis dahin noch treu zum Hause Sauls*.", footnotes: ["o. versah bis dahin noch den Dienst am Hause Sauls\n℘ 2Sam 2,8.9; 3,19"] },
      { number: 31, text: "Und von den Söhnen Ephraim: 20 800* kriegstüchtige* Männer, Männer von Namen, nach ihren Vaterhäusern.", footnotes: ["℘ 5Mo 33,17", "o. vermögende; o. angesehene"] },
      { number: 32, text: "Und vom halben Stamm Manasse: 18 000*, die mit Namen bestimmt wurden, dass sie hingingen, um David zum König zu machen.", footnotes: ["℘ 5Mo 33,17"] },
      { number: 33, text: "Und von den Söhnen Issaschar solche, die die Zeiten zu beurteilen verstanden* und wussten*, was Israel tun musste: ihre Oberhäupter 200, und alle ihre Brüder unter ihrem Befehl*.", footnotes: ["℘ Est 1,13", "w. die das Verständnis für Zeiten kannten, um zu erkennen", "w. Mund"] },
      { number: 34, text: "Von Sebulon: die, die mit dem Heer auszogen, zum Kampf geordnet, mit allen Kriegswaffen, 50 000, und zwar um sich um David zu scharen* mit ungeteiltem Herzen.", footnotes: ["Mehrere hebr. Handschr. und LXX bieten: um David zu helfen"] },
      { number: 35, text: "Und von Naftali: 1 000 Oberste und mit ihnen 37 000 mit Schild und Speer." },
      { number: 36, text: "Und von den Danitern: 28 600, zum Kampf geordnet." },
      { number: 37, text: "Und von Asser: 40 000, die mit dem Heer auszogen, zum Kampf geordnet*.", footnotes: ["w. um sich zum Kampf zu ordnen"] },
      { number: 38, text: "Und von jenseits des Jordan, von den Rubenitern und den Gaditern und dem halben Stamm Manasse: 120 000 mit allen Waffen eines Kriegsheeres." },
      { number: 39, text: "Alle diese Kriegsleute in Heeresordnung* kamen mit ungeteiltem Herzen nach Hebron, um David zum König über ganz Israel zu machen*. Und auch alle übrigen in Israel waren eines Herzens, David zum König zu machen.", footnotes: ["w. in Heeresordnung geschart", "℘ Kap. 11,10; 1Mo 49,10"] },
      { number: 40, text: "Und sie waren dort bei David drei Tage, aßen und tranken*, denn ihre Brüder hatten alles für sie bereitgestellt.", footnotes: ["℘ Kap. 29,22"] },
      { number: 41, text: "Und auch die, die nahe bei ihnen wohnten, bis nach Issaschar und Sebulon und Naftali hin, brachten Lebensmittel* auf Eseln und auf Kamelen und auf Maultieren und auf Rindern: Mehlspeisen, Feigenkuchen* und Rosinenkuchen und Wein und Öl und Rinder und Schafe in Menge; denn es war Freude in Israel*.", footnotes: ["w. Brot", "℘ 1Sam 25,18", "℘ 2Chr 23,21"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "*Und David beriet sich mit den Obersten über Tausend und über Hundert, mit allen Fürsten*.", heading: "Misslungene Überführung der Bundeslade nach Jerusalem", footnotes: ["℘ 2Sam 6,1-11", "℘ Spr 15,22"] },
      { number: 2, text: "Und David sagte zur ganzen Versammlung Israels: Wenn es euch gut erscheint und wenn es von dem HERRN, unserem Gott, ist*, dann lasst uns überallhin senden* zu unseren übrigen Brüdern in allen Landen Israels und außerdem* zu den Priestern und zu den Leviten in den Städten und ihren Weidegebieten*, dass sie sich bei uns versammeln*.", footnotes: ["℘ Jak 4,15", "w. lasst uns ausbreiten und senden", "w. mit ihnen", "℘ 4Mo 35,2", "℘ Kap. 15,3.4"] },
      { number: 3, text: "Und wir wollen die Lade unseres Gottes zu uns herüberholen; denn in den Tagen Sauls haben wir sie nicht aufgesucht*.", footnotes: ["o. haben wir nicht nach ihr gefragt; o. haben wir sie nicht befragt\n℘ Kap. 15,13"] },
      { number: 4, text: "Und die ganze Versammlung sagte, dass man es so tun solle. Denn die Sache war recht in den Augen des ganzen Volkes." },
      { number: 5, text: "Und David versammelte ganz Israel, vom Schihor* Ägyptens bis nach Hamat* hin, um die Lade Gottes von Kirjat-Jearim zu holen*.", footnotes: ["℘ Jos 13,3", "℘ 4Mo 34,8", "℘ Kap. 15,3; 1Sam 7,1.2"] },
      { number: 6, text: "Und David und ganz Israel zogen hinauf nach Baala*, nach Kirjat-Jearim, das zu Juda gehört, um von dort die Lade Gottes, des HERRN, heraufzuholen, der über den Cherubim thront, dessen Name dort ausgerufen worden ist.", footnotes: ["℘ Jos 15,9"] },
      { number: 7, text: "Und sie fuhren die Lade Gottes auf einem neuen Wagen aus dem Haus Abinadabs weg; und Usa und Achjo lenkten den Wagen." },
      { number: 8, text: "Und David und ganz Israel tanzten* vor Gott mit aller Kraft: mit Liedern und mit Zithern und mit Harfen und mit Tamburinen und mit Zimbeln und mit Trompeten*.", footnotes: ["o. spielten", "℘ Kap. 15,16.28; 25,1"] },
      { number: 9, text: "Und als sie zur Tenne des Kidon kamen, da streckte Usa seine Hand aus, um die Lade festzuhalten, denn die Rinder hatten sich losgerissen*.", footnotes: ["o. wollten den Wagen umwerfen"] },
      { number: 10, text: "Da entbrannte der Zorn des HERRN gegen Usa, und er schlug ihn, weil er seine Hand nach der Lade ausgestreckt hatte; und er starb dort vor Gott." },
      { number: 11, text: "Und es wurde David heiß vor Schrecken*, weil der HERR den Usa so weggerissen hatte*; und man nannte diesen Ort Perez-Usa* bis zum heutigen Tag.", footnotes: ["o. Und David entbrannte", "w. an Usa einen Riss gerissen hatte\n℘ 2Mo 19,22.24", "d. h. Riss Usas"] },
      { number: 12, text: "Und David fürchtete sich vor Gott* an diesem Tag und sagte: Wie kann ich die Lade Gottes zu mir bringen?", footnotes: ["℘ Kap. 21,30"] },
      { number: 13, text: "Und David ließ die Lade nicht zu sich in die Stadt Davids bringen; und er ließ sie beiseite schaffen in das Haus Obed-Edoms, des Gatiters." },
      { number: 14, text: "Und die Lade Gottes blieb bei dem Haus Obed-Edoms, in seinem Haus, drei Monate. Und der HERR segnete das Haus Obed-Edoms und alles, was er hatte*.", footnotes: ["℘ Kap. 26,4.5"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "*Und Hiram, der König von Tyrus, sandte Boten* zu David, und Zedernholz und Mauerleute und Zimmerleute, damit sie ihm ein Haus bauten*.", heading: "Davids Palastbau — Seine Söhne — Sieg über die Philister", footnotes: ["℘ V. 1-7: 2Sam 5,11-16", "℘ 1Kö 5,15", "℘ Kap. 17,1; 2Chr 2,2"] },
      { number: 2, text: "Und David erkannte, dass der HERR ihn als König über Israel eingesetzt hatte; denn seine Königsherrschaft war hoch erhöht wegen seines Volkes Israel*.", footnotes: ["℘ 2Chr 2,10"] },
      { number: 3, text: "Und David nahm noch mehr Frauen* in Jerusalem, und David zeugte noch mehr Söhne und Töchter.", footnotes: ["℘ 5Mo 17,17"] },
      { number: 4, text: "*Und das sind die Namen derer, die ihm in Jerusalem geboren wurden: Schammua und Schobab, Nathan und Salomo", footnotes: ["℘ V. 4-7: Kap. 3,5-9"] },
      { number: 5, text: "und Jibhar und Elischua und Elpelet" },
      { number: 6, text: "und Nogah und Nefeg und Jafia" },
      { number: 7, text: "und Elischama und Beeljada und Elifelet." },
      { number: 8, text: "*Und als die Philister hörten, dass David zum König über ganz Israel gesalbt worden war, zogen alle Philister herauf, um David zu suchen*. Und David hörte es und zog ihnen entgegen.", footnotes: ["℘ V. 8-17: 2Sam 5,17-25", "o. um David herauszufordern"] },
      { number: 9, text: "Die Philister waren nämlich schon gekommen und hatten sich in der Ebene Refaïm ausgebreitet." },
      { number: 10, text: "Da befragte David Gott: Soll ich gegen die Philister hinaufziehen? Wirst du sie in meine Hand geben? Und der HERR sprach zu ihm: Zieh hinauf! Und ich werde sie in deine Hand geben*.", footnotes: ["℘ 1Sam 23,4"] },
      { number: 11, text: "Da zogen sie hinauf nach Baal-Perazim, und David schlug sie dort. Und David sagte: Durchbrochen* hat Gott meine Feinde durch meine Hand, wie ein Wasserdurchbruch. Daher gab man jenem Ort den Namen Baal-Perazim*.", footnotes: ["hebr. paraz", "d. h. Herr der Durchbrüche"] },
      { number: 12, text: "Und sie ließen dort ihre Götter zurück; und David gab Befehl, und sie wurden mit Feuer verbrannt*.", footnotes: ["℘ 5Mo 7,5.25; 2Kö 10,26"] },
      { number: 13, text: "Und die Philister zogen noch einmal herauf und breiteten sich in der Ebene aus." },
      { number: 14, text: "Und David befragte Gott wieder; Gott aber sprach zu ihm: Du sollst nicht hinaufziehen hinter ihnen her! Umgehe sie*, dass du von der Seite der Bakabäume an sie herankommst!", footnotes: ["w. Wende dich von ihnen ab"] },
      { number: 15, text: "Und sobald du das Geräusch eines Daherschreitens in den Wipfeln der Bakabäume hörst, dann sollst du zum Angriff schreiten*! Denn Gott ist vor dir ausgezogen*, um das Heerlager der Philister zu schlagen.", footnotes: ["w. dann sollst du in den Kampf ausziehen", "℘ 5Mo 20,4"] },
      { number: 16, text: "Da machte David es so, wie Gott ihm geboten hatte; und sie schlugen das Heerlager der Philister von Gibeon bis nach Geser*.", footnotes: ["℘ Kap. 20,4; Jes 28,21"] },
      { number: 17, text: "Und der Name Davids ging hinaus in alle Länder*, und der HERR legte Furcht vor ihm auf alle Nationen*.", footnotes: ["℘ Kap. 17,8; Jos 6,27; 2Chr 26,8", "℘ 5Mo 11,25"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "*Und David* machte sich Häuser in der Stadt Davids, und er richtete eine Stätte für die Lade Gottes her und schlug ein Zelt für sie auf*.", heading: "Überführung der Bundeslade nach Jerusalem", footnotes: ["℘ V. 1-29: 2Sam 6,12-23", "w. er", "℘ Kap. 16,1; 2Chr 1,4; 5,2"] },
      { number: 2, text: "Damals sagte David: Die Lade Gottes soll niemand tragen außer den Leviten; denn sie hat der HERR erwählt, die Lade des HERRN zu tragen* und seinen Dienst* zu verrichten* auf ewig.", footnotes: ["℘ 2Mo 25,14; 4Mo 4,15; 5Mo 10,8", "o. den Dienst an ihr", "℘ 4Mo 3,6-9"] },
      { number: 3, text: "Und David versammelte ganz Israel nach Jerusalem, um die Lade des HERRN an ihre Stätte hinaufzubringen*, die er für sie hergerichtet hatte*.", footnotes: ["℘ Kap. 13,5; 1Kö 8,1", "℘ Kap. 16,1; 2Chr 1,4; 5,2"] },
      { number: 4, text: "Und David versammelte die Söhne Aarons und die Leviten*.", footnotes: ["℘ Kap. 13,2"] },
      { number: 5, text: "Von den Söhnen Kehat*: Uriël, den Obersten, und seine Brüder, 120;", footnotes: ["℘ Kap. 5,27"] },
      { number: 6, text: "von den Söhnen Merari*: Asaja, den Obersten, und seine Brüder, 220;", footnotes: ["℘ Kap. 5,27"] },
      { number: 7, text: "von den Söhnen Gerschon*: Joel, den Obersten, und seine Brüder, 130;", footnotes: ["℘ Kap. 5,27"] },
      { number: 8, text: "von den Söhnen Elizafan*: Schemaja, den Obersten, und seine Brüder, 200;", footnotes: ["℘ 2Mo 6,22"] },
      { number: 9, text: "von den Söhnen Hebron*: Eliël, den Obersten, und seine Brüder, 80;", footnotes: ["℘ Kap. 5,28"] },
      { number: 10, text: "von den Söhnen Usiël*: Amminadab, den Obersten, und seine Brüder, 112. —", footnotes: ["℘ Kap. 6,3; 2Mo 6,18"] },
      { number: 11, text: "Und David berief die Priester Zadok und Abjatar* und die Leviten Uriël, Asaja und Joel, Schemaja und Eliël und Amminadab", footnotes: ["℘ 2Sam 8,17"] },
      { number: 12, text: "und sagte zu ihnen: Ihr seid die Familienoberhäupter* der Leviten. Heiligt euch*, ihr und eure Brüder, und bringt die Lade des HERRN, des Gottes Israels, hinauf an die Stätte, die ich für sie hergerichtet habe!*", footnotes: ["w. Häupter der Väter", "℘ 2Chr 29,5; Jes 52,11", "℘ Kap. 16,1; 2Chr 1,4; 5,2"] },
      { number: 13, text: "Denn weil beim ersten Mal nicht ihr es getan habt, machte der HERR, unser Gott, einen Riss unter uns*, weil wir ihn nicht nach der Vorschrift gesucht haben*.", footnotes: ["℘ Kap. 13,11; 2Sam 6,8", "o. befragt haben"] },
      { number: 14, text: "Da heiligten sich die Priester und die Leviten*, um die Lade des HERRN, des Gottes Israels, heraufzubringen.", footnotes: ["℘ 2Chr 5,11; Neh 12,30"] },
      { number: 15, text: "Und die Söhne der Leviten trugen die Lade Gottes auf ihren Schultern*, wobei die Tragstangen auf ihnen lagen, wie Mose es geboten hatte nach dem Wort des HERRN*.", footnotes: ["℘ 4Mo 4,15", "℘ 2Mo 25,14; 4Mo 4,15; 5Mo 10,8"] },
      { number: 16, text: "*Und David befahl den Obersten der Leviten, ihre Brüder, die Sänger, zu bestellen*, mit Musikinstrumenten, Harfen und Zithern und Zimbeln, damit sie laut musizierten*, indem sie die Stimme erhoben mit Freude*.", footnotes: ["℘ V. 16-21: Kap. 6,16-32; 25,1-31", "℘ Neh 12,27", "w. mit bronzenen Zimbeln sich laut hören zu lassen", "℘ Kap. 13,8; 16,5.28.41.42; 25,1; 2Chr 7,6; 20,19; Ps 81,3"] },
      { number: 17, text: "Und die Leviten bestellten Heman*, den Sohn Joels, und von seinen Brüdern Asaf, den Sohn Berechjas; und von den Söhnen Merari, ihren Brüdern, Etan, den Sohn Kuschajas;", footnotes: ["℘ Kap. 6,18.24.29"] },
      { number: 18, text: "und mit ihnen ihre Brüder der zweiten Ordnung: Secharja und Jaasiël* und Schemiramot und Jehiël und Unni, Eliab und Benaja und Maaseja und Mattitja und Elifelehu und Mikneja und Obed-Edom* und Jeïël, die Torhüter.", footnotes: ["so mit LXX; Mas. T.: Secharja, der Sohn des Jaasiël", "℘ Kap. 26,4; 2Sam 6,10"] },
      { number: 19, text: "Und zwar bestellten sie die Sänger Heman, Asaf und Etan mit bronzenen Zimbeln zum Musizieren*;", footnotes: ["w. mit bronzenen Zimbeln sich laut hören zu lassen\n℘ Kap. 13,8; 16,5.28.41.42; 25,1; 2Chr 7,6; 20,19; Ps 81,3"] },
      { number: 20, text: "und Secharja und Jaasiël und Schemiramot und Jehiël und Unni und Eliab und Maaseja und Benaja mit Harfen* nach Alamoth*;", footnotes: ["℘ Ps 150,3.5", "Die Bedeutung des Wortes ist unsicher; einige vermuten: in höherer Tonlage\n℘ Ps 46,1"] },
      { number: 21, text: "und Mattitja und Elifelehu und Mikneja und Obed-Edom und Jeïël und Asasja mit Zithern nach Scheminith*: um den Gesang zu leiten.", footnotes: ["Die Bedeutung des Wortes ist unsicher, wahrscheinlich hängt es mit der Zahl acht zusammen; manche vermuten: Instrument mit acht Saiten; andere: in einer tieferen Oktave\n℘ Ps 6,1"] },
      { number: 22, text: "Und Kenanja war der Oberste der Leviten beim Anstimmen des Gesanges*; er war Unterweiser beim Anstimmen*, denn er verstand sich darauf.", footnotes: ["o. beim Tragen der Lade", "o. beim Tragen der Lade"] },
      { number: 23, text: "Und Berechja und Elkana waren Torhüter bei der Lade." },
      { number: 24, text: "Und die Priester Schebanja und Joschafat und Netanel und Amasai und Secharja und Benaja und Eliëser trompeteten mit den Trompeten vor der Lade Gottes her*. Und Obed-Edom* und Jehija waren Torhüter bei der Lade.", footnotes: ["℘ 2Chr 5,12.13", "℘ Kap. 26,4; 2Sam 6,10"] },
      { number: 25, text: "Und so zogen David und die Ältesten von Israel und die Obersten der Tausendschaften hin, um die Lade des Bundes des HERRN aus dem Hause Obed-Edoms heraufzuholen mit Freuden." },
      { number: 26, text: "Und es geschah, als Gott den Leviten half, die die Lade des Bundes des HERRN trugen, opferte man sieben Stiere und sieben Widder." },
      { number: 27, text: "Und David war mit einem Oberkleid aus Byssus bekleidet, ebenso alle Leviten, die die Lade trugen, und die Sänger und Kenanja, der Oberste beim Anstimmen des Gesangs* der Sänger*; und David trug ein leinenes Efod*.", footnotes: ["o. beim Tragen der Lade", "Vielleicht ist das Wort »der Sänger« im Mas. T. irrtümlich wiederholt.", "℘ 1Sam 2,18"] },
      { number: 28, text: "Und ganz Israel brachte die Lade des Bundes des HERRN hinauf mit Jauchzen und mit Hörnerschall* und mit Trompeten und mit Zimbeln, musizierend* mit Harfen und Zithern*.", footnotes: ["℘ Ps 47,6", "w. sich laut hören lassend", "℘ Ps 98,5"] },
      { number: 29, text: "Und es geschah, als die Lade des Bundes des HERRN in die Stadt Davids kam, schaute Michal, die Tochter Sauls, aus dem Fenster; und sie sah den König David hüpfen und tanzen*, und sie verachtete ihn in ihrem Herzen.", footnotes: ["o. spielen"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "*Und sie brachten die Lade Gottes hinein und stellten sie in die Mitte des Zeltes, das David für sie aufgeschlagen hatte*. Und sie brachten Brandopfer und Heilsopfer* dar vor Gott*.", footnotes: ["℘ V. 1-3: 2Sam 6,17-19", "℘ Kap. 6,16; 15,1.3.12", "o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "℘ 1Kö 3,15; 8,62"] },
      { number: 2, text: "Und als David die Darbringung der Brandopfer und der Heilsopfer* beendet hatte, segnete er das Volk im Namen des HERRN*.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "℘ 1Kö 8,55"] },
      { number: 3, text: "Und er verteilte an jeden Israeliten, vom Mann bis zur Frau an jeden, einen Laib Brot, einen Dattelkuchen und einen Rosinenkuchen*.", footnotes: ["℘ 1Kö 3,15"] },
      { number: 4, text: "Und er setzte einige von den Leviten als Diener vor der Lade des HERRN ein, dass sie den HERRN, den Gott Israels, rühmen, preisen und loben sollten*:", footnotes: ["℘ Kap. 23,5; 25,1.6; 2Chr 5,13; Esr 3,10; Neh 12,24"] },
      { number: 5, text: "Asaf*, das Oberhaupt, und als Zweiten nach ihm Secharja, nach ihm dann Jeïël* und Schemiramot und Jehiël und Mattitja und Eliab und Benaja und Obed-Edom und Jeïël mit Harfeninstrumenten und mit Zithern; und Asaf, auf Zimbeln musizierend*;", footnotes: ["℘ Kap. 6,24", "Vielleicht ist mit Kap. 15,18.20 Jaasiël zu lesen.", "w. sich laut hören lassend\n℘ Kap. 15,18-21"] },
      { number: 6, text: "und die Priester Benaja und Jahasiël, ständig mit Trompeten vor der Lade des Bundes Gottes*.", footnotes: ["℘ Kap. 15,18-21"] },
      { number: 7, text: "Damals, an jenem Tag, trug David zum ersten Mal dem Asaf und seinen Brüdern auf, den HERRN zu preisen:", heading: "Davids Dankpsalm" },
      { number: 8, text: "*Preist den HERRN, ruft seinen Namen an, macht unter den Völkern kund seine Taten!", footnotes: ["℘ V. 8-22: Ps 105,1-15"] },
      { number: 9, text: "Singt ihm, spielt ihm*! Redet von allen seinen Wundern*!", footnotes: ["℘ Ps 95,1.2", "℘ V. 24; Ps 145,5"] },
      { number: 10, text: "Rühmt euch seines heiligen Namens*! Es freue sich das Herz derer, die den HERRN suchen*!", footnotes: ["℘ Ps 34,3.4", "℘ Kap. 22,19; 2Chr 15,15; Ps 22,27"] },
      { number: 11, text: "Fragt nach dem HERRN und seiner Stärke*, sucht sein Angesicht beständig!", footnotes: ["℘ Ps 84,6"] },
      { number: 12, text: "Gedenkt seiner Wunder, die er getan hat, seiner Wahrzeichen und der Urteile seines Mundes*!", footnotes: ["℘ 2Mo 13,3.14"] },
      { number: 13, text: "Ihr Nachkommen Israels, seines Knechtes, ihr Söhne Jakobs, seine Auserwählten*!", footnotes: ["℘ 5Mo 10,15; Jes 41,8.9; Apg 13,17"] },
      { number: 14, text: "Er ist der HERR, unser Gott*; seine Urteile ergehen auf der ganzen Erde.", footnotes: ["℘ 1Mo 17,7"] },
      { number: 15, text: "Gedenkt ewig seines Bundes — des Wortes, das er geboten hat auf tausend Generationen hin —," },
      { number: 16, text: "den er geschlossen hat mit Abraham, und seines Eides an Isaak*.", footnotes: ["℘ 1Mo 17,2; 5Mo 7,8"] },
      { number: 17, text: "Er richtete ihn auf für Jakob zur Ordnung, für Israel zum ewigen Bund," },
      { number: 18, text: "indem er sprach: Dir will ich das Land Kanaan geben als euch zugemessenes Erbe*,", footnotes: ["w. als die Messschnur eures Erbes"] },
      { number: 19, text: "als ihr noch gering wart an Zahl, nur wenige, und Fremdlinge darin*.", footnotes: ["℘ Hebr 11,9"] },
      { number: 20, text: "Als sie von Nation zu Nation wanderten und von einem Reich zu einem anderen Volk*,", footnotes: ["℘ Hebr 11,9"] },
      { number: 21, text: "da gestattete er keinem Menschen, sie zu bedrücken, und ihretwegen wies er Könige zurecht*:", footnotes: ["℘ Zef 2,10"] },
      { number: 22, text: "»Tastet meine Gesalbten nicht an, tut meinen Propheten nichts Übles!«" },
      { number: 23, text: "*Singt dem HERRN, ganze Erde! Verkündet von Tag zu Tag sein Heil*!", footnotes: ["℘ V. 23-33: Ps 96", "℘ Ps 71,15"] },
      { number: 24, text: "Erzählt unter den Nationen seine Herrlichkeit, unter allen Völkern seine Wundertaten*!", footnotes: ["℘ Ps 26,7"] },
      { number: 25, text: "Denn groß ist der HERR und sehr zu loben*, furchtbar ist er über alle Götter*.", footnotes: ["℘ Ps 145,3", "℘ 2Mo 15,11; Ps 76,8; Jer 10,6.7; Mal 1,11"] },
      { number: 26, text: "Denn alle Götter der Völker sind Götzen*, aber der HERR hat den Himmel gemacht*.", footnotes: ["Das sehr verächtliche hebr. Wort bedeutet eigentlich »Nichtse«.\n℘ Gal 4,8", "℘ Hi 9,8; Jer 10,12"] },
      { number: 27, text: "Majestät und Pracht sind vor seinem Angesicht*, Kraft und Freude* in seiner Stätte.", footnotes: ["℘ Hes 1,27", "℘ Neh 8,10"] },
      { number: 28, text: "Gebt dem HERRN, ihr Völkerstämme, gebt dem HERRN Ehre* und Macht*!", footnotes: ["o. Herrlichkeit", "o. Kraft\n℘ Ps 29,1; Jud 25"] },
      { number: 29, text: "Gebt dem HERRN die Ehre* seines Namens! Bringt Speisopfer und kommt vor sein Angesicht! Betet den HERRN an in heiliger Pracht*!", footnotes: ["o. Herrlichkeit", "Im Ugaritischen hat das Wort die Bedeutung »Gottes-Offenbarung, -Erscheinung«; das hieße hier »bei seiner heiligen Offenbarung«."] },
      { number: 30, text: "Erzittere* vor ihm, ganze Erde*! Auch steht der Erdkreis fest, er wird nicht wanken*.", footnotes: ["so mit LXX; Mas. T.: Erzittert", "℘ Ps 99,1", "℘ Ps 93,1; Offb 19,6"] },
      { number: 31, text: "Es freue sich der Himmel, und es jauchze die Erde! Und man sage unter den Nationen: Der HERR ist König*!", footnotes: ["℘ Ps 93,1; Offb 19,6"] },
      { number: 32, text: "Es brause das Meer und seine Fülle*! Es jauchze das Feld und alles, was darauf ist*!", footnotes: ["℘ Ps 69,35", "℘ Jes 44,23"] },
      { number: 33, text: "Dann werden jubeln die Bäume des Waldes* vor dem HERRN; denn er kommt, die Erde zu richten*!", footnotes: ["℘ Jes 44,23", "℘ 1Mo 18,25; Ps 9,9"] },
      { number: 34, text: "Preist den HERRN! Denn er ist gut, denn seine Gnade währt ewig*.", footnotes: ["℘ 2Chr 5,13; Ps 106,1; 136,1; Jer 33,11"] },
      { number: 35, text: "*Und sagt: Rette uns, Gott unserer Rettung, und sammle und befreie uns aus den Nationen*, dass wir deinen heiligen Namen preisen, dass wir uns rühmen deines Lobes!", footnotes: ["℘ V. 35.36: Ps 106,47.48", "℘ 5Mo 30,3"] },
      { number: 36, text: "Gepriesen sei der HERR, der Gott Israels, von Ewigkeit zu Ewigkeit*! Und alles Volk sprach: Amen*! und lobte den HERRN.", footnotes: ["℘ Neh 9,5; Ps 41,14", "℘ 1Kor 14,16"] },
      { number: 37, text: "Und David* ließ dort, vor der Lade des Bundes des HERRN, den Asaf und seine Brüder, damit sie ständig vor der Lade Dienst täten nach dem täglichen Bedarf*;", heading: "Dienst der Leviten", footnotes: ["w. er", "w. für die Sache des Tages an ihrem Tag\n℘ Ps 145,2"] },
      { number: 38, text: "und Obed-Edom und seine* Brüder, 68 Mann, und zwar Obed-Edom, den Sohn Jedutuns, und Hosa* als Torhüter.", footnotes: ["w. und ihre Brüder; vielleicht ist ein Name ausgefallen", "℘ Kap. 26,10"] },
      { number: 39, text: "Den Priester Zadok aber und seine Brüder, die Priester, ließ er bei der Wohnung des HERRN auf der Höhe, die bei Gibeon ist*,", footnotes: ["℘ Kap. 21,29; 1Kö 3,4"] },
      { number: 40, text: "dem HERRN regelmäßig Brandopfer auf dem Brandopferaltar darzubringen, am Morgen und am Abend, und zwar nach allem, was in dem Gesetz des HERRN geschrieben steht, das er Israel geboten hat*.", footnotes: ["℘ 2Mo 29,38-42; Esr 3,3-5"] },
      { number: 41, text: "Und mit ihnen ließ er Heman und Jedutun und die übrigen Auserlesenen da, die mit Namen bestimmt waren*, den HERRN zu preisen*, dass seine Gnade ewig währt*;", footnotes: ["℘ Kap. 15,17.19", "℘ Kap. 25,3", "℘ V. 34"] },
      { number: 42, text: "und bei ihnen, bei Heman und Jedutun, waren Trompeten und Zimbeln für die Musizierenden* und die Musikinstrumente zur Ehre Gottes. Und die Söhne Jedutuns waren für das Tor da*.", footnotes: ["w. für die ihre Stimme laut hören Lassenden", "℘ Kap. 15,17.19"] },
      { number: 43, text: "Und das ganze Volk ging fort, jeder in sein Haus; und David kehrte zurück, um seinem Haus den Segensgruß zu bringen*.", footnotes: ["w. um sein Haus zu segnen\n℘ 2Sam 6,19.20"] },
    ]},
    { number: 17, verses: [
      { number: 1, text: "*Und es geschah, als David in seinem Haus wohnte*, sagte David zum Propheten Nathan: Siehe, ich wohne in einem Haus aus Zedern, die Lade des Bundes des HERRN aber wohnt unter Zeltdecken*.", heading: "Verheißung Gottes für David und sein Königtum", footnotes: ["℘ V. 1-14: Kap. 22,7-10; 28,2-7; 2Sam 7,1-16", "℘ Kap. 14,1", "℘ 2Mo 26,1"] },
      { number: 2, text: "Und Nathan sagte zu David: Tu alles, was du im Herzen hast*! Denn Gott ist mit dir.", footnotes: ["℘ 1Kö 8,17.18"] },
      { number: 3, text: "Und es geschah in jener Nacht, da geschah das Wort Gottes zu Nathan:" },
      { number: 4, text: "Geh hin und sage zu meinem Knecht David: So spricht der HERR: Nicht du sollst mir das Haus zur Wohnung bauen!" },
      { number: 5, text: "Wahrhaftig, nie habe ich in einem Haus gewohnt von dem Tag an, als ich Israel heraufgeführt habe, bis zum heutigen Tag*; sondern ich bin von Zelt zu Zelt und von Wohnung zu Wohnung umhergezogen.", footnotes: ["℘ 2Chr 6,5"] },
      { number: 6, text: "In der ganzen Zeit, die ich in ganz Israel umhergezogen bin, habe ich da jemals zu einem der Richter Israels, dem ich gebot, mein Volk zu weiden, ein Wort geredet und gesagt: Warum habt ihr mir nicht ein Haus aus Zedern gebaut*?", footnotes: ["℘ 1Kö 8,16"] },
      { number: 7, text: "Und nun, so sollst du zu meinem Knecht, zu David, sagen: So spricht der HERR der Heerscharen: Ich selbst habe dich von der Weide genommen, hinter der Schafherde weg, dass du Fürst sein solltest über mein Volk Israel*.", footnotes: ["℘ 2Chr 6,6"] },
      { number: 8, text: "Und ich bin mit dir gewesen überall, wohin du gegangen bist, und ich habe alle deine Feinde vor dir ausgerottet. Und ich mache dir einen Namen*, gleich dem Namen der Großen, die auf Erden sind*.", footnotes: ["o. ich habe dir einen Namen gemacht", "℘ Kap. 14,17"] },
      { number: 9, text: "Und ich setze für mein Volk Israel einen Ort fest und pflanze es ein*, dass es an seiner Stätte sicher wohne und nicht mehr in Unruhe gerate; und die Söhne der Ruchlosigkeit sollen es nicht mehr aufreiben wie früher,", footnotes: ["o. Ich habe . . . einen Ort festgesetzt und habe es eingepflanzt"] },
      { number: 10, text: "und zwar seit den Tagen, da ich Richter über mein Volk Israel bestellt habe. Und ich werde alle deine Feinde demütigen*. So verkündige ich dir nun, dass der HERR dir ein Haus bauen wird.", footnotes: ["o. Ich habe alle deine Feinde gedemütigt"] },
      { number: 11, text: "Und es wird geschehen, wenn deine Tage erfüllt sind, so dass du zu deinen Vätern hingehst, dann werde ich deinen Nachkommen* nach dir aufstehen lassen, der von deinen Söhnen sein wird, und werde seine Königsherrschaft festigen.", footnotes: ["w. deinen Samen"] },
      { number: 12, text: "Der wird mir ein Haus bauen*; und ich werde seinen Thron festigen für ewig*.", footnotes: ["℘ 1Kö 8,19", "℘ Ps 72,17; 89,5.37.38; Lk 1,31-33; Hebr 1,5"] },
      { number: 13, text: "Ich will ihm Vater sein, und er soll mir Sohn sein. Und ich will meine Gnade nicht von ihm weichen lassen*, wie ich sie von dem habe weichen lassen, der vor dir war.", footnotes: ["℘ Ps 89,34"] },
      { number: 14, text: "Und ich will ihm Bestand geben in meinem Haus und in meiner Königsherrschaft auf ewig; und sein Thron soll fest stehen für ewig*.", footnotes: ["℘ Hebr 1,8"] },
      { number: 15, text: "*Nach all diesen Worten und nach dieser ganzen Vision, so redete Nathan zu David.", footnotes: ["℘ V. 15-27: 2Sam 7,17-29"] },
      { number: 16, text: "Da ging der König David hinein und setzte sich vor dem HERRN nieder und sagte: Wer bin ich*, HERR, Gott, und was ist mein Haus, dass du mich bis hierher gebracht hast*?", footnotes: ["℘ Kap. 29,14", "℘ 2Chr 1,8"] },
      { number: 17, text: "Und das war noch zu gering in deinen Augen, Gott! Und du hast sogar über das Haus deines Knechtes auf ferne Zukunft hin geredet. Und du hast mich angesehen nach der Weise eines hochgestellten Menschen*, HERR, Gott!", footnotes: ["Der Mas. T. lässt eine sichere Üs. nicht zu. Wörtliche Üs. etwa: Du hast mich angesehen gleich der Reihe des Menschen (o. der Menschen) des Hinaufzugs. Andere üs. mit Textkorrektur: Und du hast mich Generationen von Menschen sehen lassen"] },
      { number: 18, text: "Was soll David noch weiter zu dir reden von der Ehre an deinem Knecht? Du selbst hast ja deinen Knecht erkannt." },
      { number: 19, text: "HERR, wegen deines Knechtes* und nach deinem Herzen hast du all dies Große getan, um ihn all diese großen Dinge erkennen zu lassen.", footnotes: ["℘ Ps 116,16; Jes 37,35"] },
      { number: 20, text: "HERR, niemand ist dir gleich*, und es gibt keinen Gott außer dir*, nach allem, was wir mit unseren Ohren gehört haben.", footnotes: ["℘ Ps 97,9", "℘ 5Mo 4,35.39"] },
      { number: 21, text: "Und wer ist wie dein Volk Israel, die einzige Nation auf Erden, für die Gott hingegangen ist, sie sich zum Volk zu erlösen, um dir einen Namen zu machen und große und furchtgebietende Taten zu tun, indem du vor deinem Volk, das du aus Ägypten erlöst hast, Nationen vertrieben hast?" },
      { number: 22, text: "Und du hast dir dein Volk Israel zum Volk bestimmt für ewig; und du, HERR, bist ihr Gott* geworden.", footnotes: ["w. ihnen zum Gott"] },
      { number: 23, text: "Und nun, HERR, das Wort, das du über deinen Knecht und über sein Haus geredet hast, möge sich ewig als zuverlässig erweisen! Und tue, wie du geredet hast*!", footnotes: ["℘ 1Kö 8,26; 2Chr 1,9"] },
      { number: 24, text: "Ja, es möge sich als zuverlässig erweisen! Und dein Name sei groß für ewig, dass man sage: Der HERR der Heerscharen, der Gott Israels*, ist Gott für Israel! Und das Haus deines Knechtes David möge fest stehen vor dir!", footnotes: ["℘ Jer 38,17"] },
      { number: 25, text: "Denn du, mein Gott, hast das Ohr deines Knechtes geöffnet und gesagt, dass du ihm ein Haus bauen willst. Darum hat dein Knecht es gewagt, vor dir zu beten." },
      { number: 26, text: "Und nun, HERR, du bist es, der da Gott ist*, und du hast dieses Gute über deinen* Knecht geredet.", footnotes: ["o. du bist derselbe Gott", "o. zu deinem"] },
      { number: 27, text: "Und nun, es hat dir gefallen, das Haus deines Knechtes zu segnen, dass es ewig vor dir sei; denn du, HERR, hast es gesegnet, und es wird gesegnet sein für ewig*.", footnotes: ["℘ 4Mo 23,20; 5Mo 15,6; 1Kö 2,33.45"] },
    ]},
    { number: 18, verses: [
      { number: 1, text: "*Und es geschah danach, da schlug David die Philister und demütigte sie; und er nahm Gat* und seine Tochterstädte aus der Hand der Philister.", heading: "Davids Kriege — Seine Beamten", footnotes: ["℘ 2Sam 8", "℘ 1Sam 7,14; 2Chr 11,8"] },
      { number: 2, text: "Er schlug auch die Moabiter; und die Moabiter wurden David zu Knechten, die Tribut entrichten mussten." },
      { number: 3, text: "David schlug auch Hadad-Eser, den König von Zoba, bei Hamat*, als er hinzog, um seine Macht am Strom Euphrat aufzurichten*.", footnotes: ["℘ 2Chr 8,3", "o. zu festigen"] },
      { number: 4, text: "Und David nahm von ihm 1 000 Wagen und 7 000 Berittene und 20 000 Mann Fußvolk gefangen. Und David lähmte alle Wagenpferde, aber 100 Wagenpferde ließ er von ihm übrig." },
      { number: 5, text: "Da kamen die Aramäer von Damaskus, um Hadad-Eser, dem König von Zoba, zu helfen. David aber schlug unter den Aramäern 22 000 Mann*.", footnotes: ["℘ Ps 60,2"] },
      { number: 6, text: "Und David setzte in Aram-Damaskus Vögte ein*; und die Aramäer wurden David zu Knechten, die Tribut entrichten mussten. So half der HERR dem David überall, wohin er zog*.", footnotes: ["o. Gouverneure. — Andere üs.: David legte Besatzung nach Edom", "o. sooft er auszog\n℘ 1Sam 18,14"] },
      { number: 7, text: "Und David nahm die goldenen Schilde, die den Knechten Hadad-Esers gehörten, und brachte sie nach Jerusalem." },
      { number: 8, text: "Und aus Tibhat und aus Kun, den Städten Hadad-Esers, nahm David sehr viel Bronze; daraus machte Salomo das bronzene Meer und die Säulen und die bronzenen Geräte*.", footnotes: ["℘ 1Kö 7,15-47; 2Chr 3,15-17; 4,2-6.12-18"] },
      { number: 9, text: "Und als Toï, der König von Hamat, hörte, dass David die ganze Heeresmacht Hadad-Esers, des Königs von Zoba, geschlagen hatte," },
      { number: 10, text: "sandte er seinen Sohn Hadoram zum König David, um ihn nach seinem Wohlergehen zu fragen und ihm Glück zu wünschen*, weil er gegen Hadad-Eser gekämpft und ihn geschlagen hatte — denn Hadad-Eser war Toïs Kriegsgegner gewesen —, und er brachte allerlei goldene, silberne und bronzene Geräte mit.", footnotes: ["o. und ihn zu segnen"] },
      { number: 11, text: "Auch diese heiligte der König David dem HERRN*, samt dem Silber und Gold, das er von all den Nationen genommen hatte: von den Edomitern und von den Moabitern und von den Söhnen Ammon und von den Philistern und von den Amalekitern. —", footnotes: ["℘ Kap. 26,27; Jos 6,19.24"] },
      { number: 12, text: "Und Abischai, der Sohn der Zeruja, schlug die Edomiter im Salztal*, 18 000 Mann.", footnotes: ["℘ Ps 60,2"] },
      { number: 13, text: "Und er setzte in Edom Vögte ein*, und alle Edomiter wurden David zu Knechten. So half der HERR dem David überall, wohin er zog*.", footnotes: ["o. Gouverneure. — Andere üs.: David legte Besatzung nach Edom", "o. sooft er auszog\n℘ 1Sam 18,14"] },
      { number: 14, text: "Und David war König über ganz Israel. Und er übte Recht und Gerechtigkeit an seinem ganzen Volk*.", footnotes: ["℘ Ps 72,1.2"] },
      { number: 15, text: "Und Joab, der Sohn der Zeruja, war über das Heer gesetzt*. Und Joschafat, der Sohn Ahiluds, war Berater*.", footnotes: ["℘ Kap. 27,34", "w. Erinnerer; o. der Bekanntmachende"] },
      { number: 16, text: "Und Zadok, der Sohn Ahitubs, und Ahimelech*, der Sohn Abjatars*, waren Priester. Und Schawscha war Schreiber.", footnotes: ["℘ Kap. 24,3.6", "℘ 1Sam 22,20"] },
      { number: 17, text: "Und Benaja, der Sohn Jojadas, war über die Kreter und Pleter gesetzt. Und die Söhne Davids waren die Ersten zur Seite des Königs." },
    ]},
    { number: 19, verses: [
      { number: 1, text: "*Und es geschah danach, da starb Nahasch, der König der Söhne Ammon; und sein Sohn wurde an seiner Stelle König.", heading: "Kriege gegen die Ammoniter und Aramäer — Eroberung Rabbas", footnotes: ["℘ 2Sam 10"] },
      { number: 2, text: "Und David sagte: Ich will Gnade erweisen an Hanun, dem Sohn des Nahasch, denn sein Vater hat Gnade an mir erwiesen. Und David sandte Boten, um ihn wegen seines Vaters zu trösten. Und die Knechte Davids kamen in das Land der Söhne Ammon zu Hanun, um ihn zu trösten." },
      { number: 3, text: "Da sagten die Obersten der Söhne Ammon zu Hanun: Will David in deinen Augen wirklich deinen Vater ehren, wenn er Tröster zu dir gesandt hat? Sind nicht seine Knechte zu dir gekommen, um das Land zu erforschen und auszukundschaften und umzukehren*?", footnotes: ["w. und umzukehren und auszukundschaften. — Andere lesen mit Textkorrektur: um das Land zu erforschen, zu erkunden und auszukundschaften"] },
      { number: 4, text: "Da nahm Hanun die Knechte Davids und ließ sie scheren und ihre Kleider zur Hälfte abschneiden bis ans Gesäß*; und er schickte sie weg.", footnotes: ["w. bis an die Stelle der Bedeckung"] },
      { number: 5, text: "Und man ging und berichtete David von den Männern. Da sandte er ihnen Boten entgegen, denn die Männer waren sehr geschändet*; und der König ließ ihnen sagen: Bleibt in Jericho, bis euer Bart gewachsen ist, dann kommt zurück!", footnotes: ["o. die Männer schämten sich sehr"] },
      { number: 6, text: "Als nun die Söhne Ammon sahen, dass sie sich bei David stinkend gemacht hatten, da sandten Hanun und die Söhne Ammon tausend Talente Silber, um sich aus Mesopotamien und aus Aram-Maacha und aus Zoba Streitwagen und Reiter anzuwerben." },
      { number: 7, text: "Und sie warben sich 32 000 Streitwagen und den König von Maacha mit seinem Volk an; und die kamen und lagerten sich vor Medeba*. Auch die Söhne Ammon sammelten sich aus ihren Städten und kamen zum Kampf.", footnotes: ["℘ Jos 13,9.16"] },
      { number: 8, text: "Als nun David davon hörte, sandte er Joab aus und das ganze Heer, die Helden." },
      { number: 9, text: "Und die Söhne Ammon zogen aus und ordneten sich am Eingang der Stadt zur Schlacht; und die Könige, die gekommen waren, standen gesondert auf dem freien Feld." },
      { number: 10, text: "Und als Joab sah, dass die Kampffront von vorn und von hinten gegen ihn gerichtet war, da wählte er von allen Auserlesenen Israels einen Teil aus und ordnete sich mit ihnen zur Schlacht gegen die Aramäer;" },
      { number: 11, text: "den Rest des Kriegsvolkes aber übergab er der Hand seines Bruders Abischai, und sie ordneten sich zur Schlacht gegen die Söhne Ammon." },
      { number: 12, text: "Und er sagte: Wenn die Aramäer stärker sind als ich, dann sollst du mir Hilfe leisten; und wenn die Söhne Ammon stärker sind als du, dann will ich dir helfen." },
      { number: 13, text: "Sei stark und lass uns stark sein für unser Volk und für die Städte unseres Gottes! Der HERR aber möge tun, was gut ist in seinen Augen*.", footnotes: ["℘ 1Sam 3,18"] },
      { number: 14, text: "Da rückte Joab und das Volk, das bei ihm war, zum Kampf gegen die Aramäer vor; und sie flohen vor ihm." },
      { number: 15, text: "Als aber die Söhne Ammon sahen, dass Aram floh, da flohen auch sie vor seinem Bruder Abischai und zogen sich in die Stadt zurück. Und Joab kam nach Jerusalem." },
      { number: 16, text: "Als nun Aram sah, dass es vor Israel geschlagen war, da sandten sie Boten hin und ließen auch die Aramäer, die jenseits des Stromes waren, in den Kampf ausziehen; und Schobach, der Heeroberste Hadad-Esers, zog vor ihnen her." },
      { number: 17, text: "Das wurde David berichtet. Da versammelte er ganz Israel und ging über den Jordan, kam an sie heran und ordnete sich gegen sie. Und David ordnete sich zur Schlacht, den Aramäern gegenüber. Und sie kämpften mit ihm." },
      { number: 18, text: "Aram aber floh vor Israel, und David erschlug von Aram 7 000 Wagenkämpfer und 40 000 Mann Fußvolk. Auch den Heerobersten Schobach tötete er." },
      { number: 19, text: "Als nun die Knechte Hadad-Esers sahen, dass sie vor Israel geschlagen waren, schlossen sie Frieden mit David und dienten ihm. Und die Aramäer wollten den Söhnen Ammon nicht mehr helfen." },
    ]},
    { number: 20, verses: [
      { number: 1, text: "*Und es geschah bei der Wiederkehr* des Jahres, zu der Zeit, wenn die Könige ins Feld ausziehen, da führte Joab die Heeresmacht heran und verheerte das Land der Söhne Ammon; und er kam und belagerte Rabba. David aber blieb in Jerusalem. Und Joab schlug Rabba und zerstörte es.", footnotes: ["℘ V. 1-3: 2Sam 11,1; 12,26-31", "w. zur Zeit der Rückkehr des Jahres, d. h. im folgenden Frühjahr"] },
      { number: 2, text: "Und David nahm ihrem König die Krone vom Haupt*; und er fand sie ein Goldtalent schwer, und ein Edelstein war an ihr; und sie kam auf das Haupt Davids. Und er brachte eine große Menge Beute aus der Stadt heraus.", footnotes: ["w. die Krone ihres Königs von seinem Haupt. — Andere lesen mit LXX-Ausgaben: die Krone des Milkom von seinem Haupt; Milkom war ein Gott der Ammoniter"] },
      { number: 3, text: "Das Volk aber, das darin war, holte er heraus und stellte es an die Steinsäge, an die eisernen Pickel und an die Beile*. So machte es David mit allen Städten der Söhne Ammon. Und David und das ganze Volk kehrten nach Jerusalem zurück.", footnotes: ["T. in Übereinstimmung mit 2Sam 12,31; Mas. T.: und zersägte es mit der Steinsäge, mit den eisernen Pickeln und mit den Steinsägen. Das hebr. Wort für »zersägte« ist unsicher. Andere üs.: und es stand der Steinsäge vor"] },
      { number: 4, text: "*Und es geschah danach, da entstand ein Kampf mit den Philistern bei Geser*. Damals erschlug Sibbechai*, der Huschatiter, den Sippai, einen von den Söhnen des Rafa*; und sie wurden gedemütigt.", heading: "Heldentaten der Männer Davids", footnotes: ["℘ 2Sam 21,15-22", "℘ Kap. 14,16; Jos 16,3", "℘ Kap. 27,11", "so mit mehreren Handschr.; Mas. T.: von den Söhnen der Refaïter"] },
      { number: 5, text: "Und wieder gab es einen Kampf mit den Philistern. Und Elhanan, der Sohn Jaïrs, erschlug Lachmi, den Bruder Goliats, den Gatiter; und der Schaft seines Speeres war wie ein Weberbaum*.", footnotes: ["℘ 1Sam 17,7"] },
      { number: 6, text: "Und wieder kam es zum Kampf bei Gat. Da war ein langer Mann, der hatte je sechs Finger und Zehen, zusammen 24; und auch er war dem Rafa geboren worden." },
      { number: 7, text: "Und er verhöhnte Israel; da erschlug ihn Jonatan*, der Sohn Schimas, des Bruders Davids.", footnotes: ["℘ Kap. 27,32"] },
      { number: 8, text: "Diese wurden dem Rafa in Gat geboren; und sie fielen durch die Hand Davids und durch die Hand seiner Knechte." },
    ]},
    { number: 21, verses: [
      { number: 1, text: "*Und Satan stellte* sich gegen Israel und reizte David, Israel zu zählen.", heading: "Davids Volkszählung und deren Folgen", footnotes: ["℘ 2Sam 24", "℘ Hi 1,6-12; Lk 22,31; Joh 13,27"] },
      { number: 2, text: "Und David sagte zu Joab und zu den Obersten des Volkes: Geht hin, zählt Israel von Beerscheba bis Dan* und bringt mir Bericht, damit ich ihre Zahl kenne!", footnotes: ["℘ Ri 20,1"] },
      { number: 3, text: "Und Joab sagte: Der HERR möge zu seinem Volk, so viele sie sein mögen, hundertmal mehr hinzufügen! Sind sie nicht alle, mein Herr und König, die Knechte meines Herrn? Warum verlangt mein Herr das? Warum soll es Israel zur Schuld werden*?", footnotes: ["℘ 2Mo 30,12"] },
      { number: 4, text: "Aber das Wort des Königs blieb fest gegen Joab. So zog Joab aus und zog durch ganz Israel und kam nach Jerusalem zurück." },
      { number: 5, text: "Und Joab gab David das Ergebnis der Volkszählung* an. Und zwar gab es in ganz Israel 1 100 000 Mann, die das Schwert zogen, und in Juda 470 000 Mann, die das Schwert zogen.", footnotes: ["w. die Zahl der Zählung des Volkes"] },
      { number: 6, text: "Levi aber und Benjamin musterte er nicht mit ihnen*; denn das Wort des Königs war Joab ein Gräuel.", footnotes: ["℘ Kap. 27,24"] },
      { number: 7, text: "Und diese Sache war böse in den Augen Gottes*, und er schlug Israel*.", footnotes: ["℘ 2Sam 11,27", "℘ Jos 7,1"] },
      { number: 8, text: "Da sagte David zu Gott: Ich habe sehr gesündigt, dass ich diese Sache getan habe. Und nun lass doch die Schuld deines Knechtes vorübergehen! Denn ich habe sehr töricht gehandelt." },
      { number: 9, text: "Und der HERR redete zu Gad, dem Seher Davids*, und sprach:", footnotes: ["℘ Kap. 29,29; 1Sam 22,5; 2Chr 29,25"] },
      { number: 10, text: "Geh hin, rede zu David: So spricht der HERR: Dreierlei lege ich dir vor*. Wähle dir eins davon, dass ich es dir tue!", footnotes: ["so mit mehreren hebr. Handschr. und LXX; Mas. T.: wende ich dir zu"] },
      { number: 11, text: "Und Gad kam zu David und sagte zu ihm: So spricht der HERR: Nimm dir," },
      { number: 12, text: "entweder drei Jahre Hungersnot oder drei Monate lang Niederlage* vor deinen Bedrängern, wobei das Schwert deiner Feinde dich einholt, oder drei Tage das Schwert des HERRN und Pest im Land, und dass der Engel des HERRN Verderben bringt im ganzen Gebiet Israels! Und nun sieh zu, was für eine Antwort ich dem zurückbringen soll, der mich gesandt hat.", footnotes: ["w. Dahingerafftwerden"] },
      { number: 13, text: "Und David sagte zu Gad: Mir ist sehr angst! Lass mich doch in die Hand des HERRN fallen! Denn seine Erbarmungen sind sehr groß*. Aber in die Hand der Menschen lass mich nicht fallen!*", footnotes: ["℘ Ps 86,15; 119,156", "℘ 2Chr 28,9"] },
      { number: 14, text: "Da gab der HERR die Pest in Israel; und es fielen von Israel 70 000 Mann. —" },
      { number: 15, text: "Und Gott sandte den Engel nach Jerusalem, um es zu vernichten. Und als er zu vernichten begann, sah es der HERR, und er hatte Mitleid wegen des Unheils*. Und er sprach zu dem Engel, der vernichtete: Genug! Lass deine Hand jetzt sinken! Der Engel des HERRN stand aber gerade bei der Tenne Ornans*, des Jebusiters.", footnotes: ["℘ Am 7,3.6", "In 2Sam 24,16 lautet der Name Arauna."] },
      { number: 16, text: "Und als David seine Augen erhob, sah er den Engel des HERRN zwischen der Erde und dem Himmel stehen, sein Schwert gezückt in seiner Hand*, ausgestreckt über Jerusalem. Da fielen David und die Ältesten, in Sacktuch gehüllt*, auf ihr Angesicht*.", footnotes: ["℘ 4Mo 22,31", "℘ 1Kö 21,27", "℘ Hes 9,8"] },
      { number: 17, text: "Und David sagte zu Gott: Habe nicht ich befohlen*, das Volk zu zählen? Bin ich es doch, der gesündigt und Böses getan hat! Aber diese Schafe, was haben sie getan? HERR, mein Gott, lass doch deine Hand gegen mich und gegen das Haus meines Vaters sein, aber nicht gegen dein Volk mit dieser Plage*!", footnotes: ["w. gesagt", "w. zur Plage"] },
      { number: 18, text: "Und der Engel des HERRN sprach zu Gad, dass er zu David sage, David solle hinaufgehen, um dem HERRN einen Altar zu errichten auf der Tenne Ornans, des Jebusiters*.", footnotes: ["℘ 2Chr 3,1"] },
      { number: 19, text: "Da ging David hinauf auf das Wort Gads hin, das der im Namen des HERRN geredet hatte." },
      { number: 20, text: "Und Ornan wandte sich um und sah den Engel; und seine vier Söhne bei ihm versteckten sich. Ornan aber drosch Weizen." },
      { number: 21, text: "Und David kam zu Ornan heran; und Ornan blickte auf und sah David, und er ging aus der Tenne hinaus und warf sich vor David nieder, mit dem Gesicht zur Erde*.", footnotes: ["℘ Ri 13,20; 1Sam 25,23"] },
      { number: 22, text: "Und David sagte zu Ornan: Gib mir den Platz der Tenne, dass ich dem HERRN einen Altar darauf baue! Für den vollen Preis sollst du ihn mir geben*, damit die Plage vom Volk abgewehrt wird*.", footnotes: ["℘ 1Mo 23,9", "℘ 4Mo 25,8"] },
      { number: 23, text: "Da sagte Ornan zu David: Nimm ihn dir! Mein Herr, der König, tue, was gut ist in seinen Augen! Siehe, ich gebe die Rinder für die Brandopfer und die Dreschschlitten als Brennholz und den Weizen zum Speisopfer; das alles gebe ich." },
      { number: 24, text: "Aber der König David sagte zu Ornan: Nein, sondern kaufen will ich es, und zwar für den vollen Preis*. Denn ich will nicht, was dir gehört, für den HERRN nehmen und umsonst Brandopfer opfern.", footnotes: ["℘ 1Mo 23,9"] },
      { number: 25, text: "Und David gab Ornan für den Platz Gold im Gewicht von sechshundert Schekeln." },
      { number: 26, text: "Und David baute dort dem HERRN einen Altar und opferte Brandopfer und Heilsopfer*. Und er rief zu dem HERRN, und der antwortete ihm mit Feuer, das vom Himmel auf den Altar des Brandopfers fiel*.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "℘ 3Mo 9,24; Ri 13,20; 2Chr 7,1"] },
      { number: 27, text: "Und der HERR sprach zu dem Engel, und der steckte sein Schwert wieder in seine Scheide." },
      { number: 28, text: "Zu jener Zeit, als David sah, dass der HERR ihm auf der Tenne Ornans, des Jebusiters, geantwortet hatte, und als er dort opferte —" },
      { number: 29, text: "die Wohnung des HERRN aber, die Mose in der Wüste gemacht hatte, und der Brandopferaltar waren zu jener Zeit auf der Höhe bei Gibeon*,", footnotes: ["℘ Kap. 16,39"] },
      { number: 30, text: "doch David konnte nicht hingehen und vor ihn treten, um Gott zu suchen*, denn er war von Schrecken erfasst* vor dem Schwert des Engels des HERRN —,", footnotes: ["o. zu befragen", "℘ Kap. 13,12"] },
    ]},
    { number: 22, verses: [
      { number: 1, text: "da sagte David: Das hier soll das Haus Gottes, des HERRN, sein und das der Altar zum Brandopfer für Israel*.", footnotes: ["℘ 5Mo 12,5; 2Chr 3,1"] },
      { number: 2, text: "*Und David befahl, dass man die Fremden versammeln solle, die im Land Israel waren; und er stellte sie an als Steinhauer, um Quader für den Bau des Hauses Gottes zu behauen*.", heading: "Auftrag an Salomo, den Tempel zu bauen — Seine Einsetzung zum König", footnotes: ["℘ V. 2-5: Kap. 29,1-5", "℘ 2Chr 2,16"] },
      { number: 3, text: "Und David ließ Eisen in Menge für die Nägel zu den Torflügeln und für die Klammern bereitstellen; und Bronze in einer Menge, dass es nicht zu wiegen war*;", footnotes: ["℘ V. 14; 5Mo 8,9; 1Kö 7,47"] },
      { number: 4, text: "auch Zedernholz ohne Zahl, denn die Sidonier und die Tyrer brachten Zedernholz in Menge* zu David.", footnotes: ["℘ 1Kö 5,20-24"] },
      { number: 5, text: "Und David sagte sich: Mein Sohn Salomo ist noch jung* und zart*. Das Haus aber, das dem HERRN gebaut werden soll, soll überaus groß werden*, zum Preis* und zum Ruhm* in allen Ländern*. So will ich denn das Nötige für ihn bereitstellen. Und so stellte David Vorrat in Menge bereit vor seinem Tod.", footnotes: ["o. ein Junge", "℘ 1Kö 3,7", "℘ 2Chr 2,4.8; Hag 2,3", "w. zum Namen", "o. zum Stolz; o. zur Zierde", "w. für alle Länder"] },
      { number: 6, text: "*Und er rief seinen Sohn Salomo und gebot ihm, dem HERRN, dem Gott Israels, ein Haus zu bauen*.", footnotes: ["℘ V. 7-10: Kap. 17,1-14; 28,2-7; 2Sam 7,1-16", "℘ 1Kö 5,19"] },
      { number: 7, text: "Und David sagte zu Salomo: Mein Sohn, ich selbst* hatte in meinem Herzen vor, dem Namen des HERRN, meines Gottes, ein Haus zu bauen.", footnotes: ["o. zu Salomo, seinem Sohn: Ich selbst"] },
      { number: 8, text: "Aber das Wort des HERRN geschah zu mir, indem er sprach: Du hast Blut in Menge fließen lassen und große Kriege geführt. Du sollst meinem Namen kein Haus bauen! Denn viel Blut hast du vor mir auf die Erde fließen lassen*.", footnotes: ["℘ 1Kö 5,17"] },
      { number: 9, text: "Siehe, ein Sohn wird dir geboren werden, der wird ein Mann der Ruhe sein*, denn ich werde ihm Ruhe schaffen vor allen seinen Feinden ringsum. Denn Salomo* wird sein Name sein, und Frieden und Ruhe werde ich Israel geben in seinen Tagen*.", footnotes: ["℘ 2Sam 12,24; Ps 72,1", "d. h. der Friedliche", "℘ 1Kö 5,4; 8,56; Ps 72,7"] },
      { number: 10, text: "Der soll meinem Namen ein Haus bauen*; und er soll mir Sohn und ich will ihm Vater sein; und ich werde den Thron seiner Königsherrschaft über Israel festigen für ewig*. —", footnotes: ["℘ 1Kö 8,19", "℘ 1Kö 2,15"] },
      { number: 11, text: "Nun, mein Sohn, der HERR sei mit dir*, dass es dir gelinge und du das Haus des HERRN, deines Gottes, bauest, wie er über dich geredet hat*!", footnotes: ["℘ 1Sam 20,13; 2Chr 1,1", "℘ 2Chr 6,10"] },
      { number: 12, text: "Auch dir wird der HERR Einsicht und Verstand geben*, und er wird dich über Israel setzen, dass du das Gesetz des HERRN, deines Gottes, beachtest*.", footnotes: ["℘ 1Kö 3,9.12", "℘ Ps 119,34"] },
      { number: 13, text: "Dann wird es dir gelingen, wenn du darauf achtest, die Ordnungen und die Rechtsbestimmungen zu befolgen, die der HERR dem Mose für Israel geboten hat*. Sei stark und mutig*, fürchte dich nicht und sei nicht niedergeschlagen*!", footnotes: ["℘ Kap. 28,7; 2Chr 14,6; 26,5; Ps 1,3", "℘ Kap. 28,10.20; 1Kö 2,2.3", "℘ 5Mo 31,7.8"] },
      { number: 14, text: "Und siehe, durch meine Bemühung habe ich für das Haus des HERRN 100 000 Talente Gold und 1 000 000 Talente Silber bereitgestellt; und die Bronze und das Eisen sind nicht zu wiegen*, denn es ist in großer Menge vorhanden; auch Holz und Steine habe ich bereitgestellt, und du wirst noch mehr hinzufügen*.", footnotes: ["℘ V. 3", "℘ Kap. 29,2; 1Kö 7,47"] },
      { number: 15, text: "Und Handwerker sind bei dir in Menge: Steinhauer und Arbeiter in Stein und Holz, und allerlei Sachverständige in jeder Arbeit*.", footnotes: ["℘ 2Chr 2,6"] },
      { number: 16, text: "Das Gold, das Silber und die Bronze und das Eisen sind nicht zu zählen*. Mache dich auf und handle*! Und der HERR sei mit dir!*", footnotes: ["℘ 1Sam 20,13; 2Chr 1,1", "℘ 1Sam 20,13; 2Chr 1,1", "℘ 1Sam 20,13; 2Chr 1,1"] },
      { number: 17, text: "Und David gebot allen Obersten Israels, seinem Sohn Salomo beizustehen:" },
      { number: 18, text: "Ist nicht der HERR, euer Gott, mit euch, und hat er euch nicht Ruhe verschafft ringsumher*? Denn er hat die Bewohner des Landes in meine Hand gegeben, und das Land ist unterworfen vor dem HERRN und vor seinem Volk.", footnotes: ["℘ Kap. 23,25; 5Mo 12,10; Jos 22,4"] },
      { number: 19, text: "Richtet nun euer Herz und eure Seele darauf, den HERRN, euren Gott, zu suchen*! Und macht euch auf und baut das Heiligtum Gottes*, des HERRN, dass ihr die Lade des Bundes des HERRN und die Geräte des Heiligtums Gottes in das Haus bringt, das dem Namen des HERRN gebaut werden soll*.", footnotes: ["o. nach dem HERRN, eurem Gott, zu fragen\n℘ Kap. 16,10.11; Ps 119,2", "℘ 2Mo 25,8; Hag 1,8", "℘ 1Kö 8,6"] },
    ]},
    { number: 23, verses: [
      { number: 1, text: "Und David war alt und der Tage satt*; und er machte seinen Sohn Salomo zum König über Israel*.", footnotes: ["℘ Kap. 29,28; 1Mo 25,8; 1Kö 1,1.27", "℘ Kap. 28,5; 29,22"] },
      { number: 2, text: "Und er versammelte alle Obersten Israels* und die Priester und die Leviten.", heading: "Zahl, Ordnung und Dienst der Leviten", footnotes: ["℘ Kap. 28,1; Jos 23,2"] },
      { number: 3, text: "Und die Leviten wurden gezählt von dreißig Jahren an und darüber*; und ihre Zahl war, Kopf für Kopf, an Männern 38 000.", footnotes: ["℘ 4Mo 4,46-48"] },
      { number: 4, text: "Und David sagte: Von diesen sind 24 000 für die Aufsicht über die Arbeit am Haus des HERRN bestimmt,* und 6 000 sollen Aufseher* und Richter sein*", footnotes: ["℘ 2Chr 23,18", "w. Schreiber; d. i. eine Beamtenbezeichnung", "℘ Kap. 26,29; 5Mo 16,18; 2Chr 19,8"] },
      { number: 5, text: "und 4 000 Torhüter* und 4 000, die den HERRN loben* mit den Instrumenten, die ich zum Loben gemacht habe.", footnotes: ["℘ Kap. 9,17-27; 26,1-19; 2Chr 34,13", "℘ V. 30; Kap. 6,33; 16,4; 2Chr 29,25.26; Jes 64,10"] },
      { number: 6, text: "Und David teilte sie in Abteilungen ein* nach den Söhnen Levis, nach Gerschon, Kehat und Merari*.", footnotes: ["℘ Kap. 24,1; 2Chr 8,14; 35,4.5", "℘ Kap. 5,27; 4Mo 3; 4; 2Chr 31,2"] },
      { number: 7, text: "Von den Gerschonitern: Ladan und Schimi*.", footnotes: ["℘ Kap. 6,2"] },
      { number: 8, text: "Die Söhne Ladans: das Oberhaupt, Jehiël, dann Setam und Joel, zusammen drei*.", footnotes: ["℘ Kap. 26,21.22"] },
      { number: 9, text: "Die Söhne Schimis: Schelomit und Hasiël und Haran, zusammen drei. Diese waren die Familienoberhäupter* von Ladan.", footnotes: ["w. Häupter(n) der Väter"] },
      { number: 10, text: "Und die Söhne Schimis: Jahat, Sisa und Jëusch und Beria; das waren die Söhne Schimis, zusammen vier." },
      { number: 11, text: "Und Jahat war das Oberhaupt und Sisa der zweite; und Jëusch und Beria hatten nicht viele Söhne, und so bildeten sie ein Vaterhaus, eine Dienstabteilung." },
      { number: 12, text: "Die Söhne Kehats: Amram, Jizhar, Hebron und Usiël, zusammen vier*.", footnotes: ["℘ Kap. 5,28; 6,3; 2Mo 6,18; 4Mo 3,27"] },
      { number: 13, text: "Die Söhne Amrams: Aaron und Mose*. Und Aaron wurde ausgesondert, das Hochheilige zu heiligen, er und seine Söhne für ewig*, vor dem HERRN Rauchopfer darzubringen*, ihm zu dienen und in seinem Namen zu segnen, für ewig*.", footnotes: ["℘ Kap. 5,29; 2Mo 6,20", "℘ 2Mo 28,1.36-38; Hebr 5,1.4", "℘ Kap. 6,34", "℘ 3Mo 9,22; 4Mo 6,23-27; 5Mo 10,8; Hebr 9,6"] },
      { number: 14, text: "Die Söhne des Mose, des Mannes Gottes*, wurden dem Stamm des Levi zugerechnet.", footnotes: ["℘ 5Mo 33,1; 2Chr 30,16; Esr 3,2"] },
      { number: 15, text: "Die Söhne Moses: Gerschom und Eliëser*.", footnotes: ["℘ 2Mo 18,3.4"] },
      { number: 16, text: "*Die Söhne Gerschoms: Schebuël, das Oberhaupt*.", footnotes: ["℘ V. 16-23: Kap. 24,20-30", "℘ Kap. 26,24-26"] },
      { number: 17, text: "Und die Söhne Eliësers waren: Rehabja, das Oberhaupt; und Eliëser hatte keine anderen Söhne; aber die Söhne Rehabjas waren überaus zahlreich*. —", footnotes: ["℘ Kap. 26,24-26"] },
      { number: 18, text: "Die Söhne Jizhars: Schelomit, das Oberhaupt." },
      { number: 19, text: "Die Söhne Hebrons: Jerija, das Oberhaupt*, Amarja, der zweite, Jahasiël, der dritte, und Jekamam, der vierte.", footnotes: ["℘ Kap. 26,31"] },
      { number: 20, text: "Die Söhne Usiëls: Micha, das Oberhaupt, und Jischija, der zweite." },
      { number: 21, text: "Die Söhne Meraris: Machli und Muschi*. Die Söhne Machlis: Eleasar und Kisch.", footnotes: ["℘ Kap. 6,4; 4Mo 3,33"] },
      { number: 22, text: "Und Eleasar starb, und er hatte keine Söhne, sondern nur Töchter; und die Söhne des Kisch, ihre Brüder, nahmen sie zu Frauen*.", footnotes: ["℘ 4Mo 36,6"] },
      { number: 23, text: "Die Söhne Muschis: Machli und Eder und Jeremot, zusammen drei." },
      { number: 24, text: "Das waren die Söhne Levi nach ihren Vaterhäusern, Familienoberhäuptern*, wie sie gemustert wurden* nach der Zählung* der Namen, Kopf für Kopf, die die Arbeit taten für den Dienst des Hauses des HERRN, von zwanzig Jahren an und darüber*.", footnotes: ["w. Häupter(n) der Väter", "Andere lesen mit Textkorrektur: nach ihren Dienstabteilungen", "w. Zahl", "℘ 4Mo 4,3; Esr 3,8; Neh 7,1"] },
      { number: 25, text: "Denn David sagte: Der HERR, der Gott Israels, hat seinem Volk Ruhe verschafft*, und er wohnt in Jerusalem für ewig*.", footnotes: ["℘ Kap. 22,18; Jos 23,1", "℘ Ps 132,14; 135,21; Joe 4,21; Sach 2,14"] },
      { number: 26, text: "So haben auch die Leviten die Wohnung und alle ihre Geräte für ihren Dienst nicht mehr zu tragen* —", footnotes: ["℘ 2Chr 35,3"] },
      { number: 27, text: "denn nach den letzten* Worten Davids ist das die Zählung* der Söhne Levi von zwanzig Jahren an und darüber* —,", footnotes: ["o. den späteren", "w. Zahl", "℘ 4Mo 4,3; 2Chr 31,17"] },
      { number: 28, text: "denn ihr Platz ist an der Seite der Söhne Aaron zum Dienst am Haus des HERRN hinsichtlich der Vorhöfe und der Zellen und zur Reinigung alles Heiligen und hinsichtlich dessen, was im Dienst am Haus Gottes zu tun ist*:", footnotes: ["w. hinsichtlich der Arbeit für den Dienst des Hauses Gottes\n℘ 4Mo 3,6-9; 2Chr 23,4.6"] },
      { number: 29, text: "für die Schaubrote* und für den Weizengrieß zum Speisopfer und für die ungesäuerten Fladen und für die Pfanne und für den Teig* und für alles Hohl- und Längenmaß*.", footnotes: ["w. für das aufgeschichtete Brot\n℘ 3Mo 24,5-8", "w. das Eingerührte\n℘ 3Mo 2,4-7", "℘ 3Mo 19,35.36"] },
      { number: 30, text: "Und ihre Aufgabe ist es, Morgen für Morgen anzutreten, um den HERRN zu preisen und zu loben*, und ebenso am Abend*,", footnotes: ["℘ V. 5", "℘ Ps 92,3; 134,1"] },
      { number: 31, text: "und alle Brandopfer dem HERRN zu opfern an den Sabbaten, an den Neumonden und an den Festen, abgezählt* nach der für sie geltenden Vorschrift*, regelmäßig vor dem HERRN*.", footnotes: ["w. nach der Zahl", "℘ 4Mo 28,2", "℘ 2Chr 24,14"] },
      { number: 32, text: "Und sie versahen den Dienst am Zelt der Begegnung und den Dienst am Heiligtum* und den Dienst der Söhne Aaron, ihrer Brüder*, bei der Bedienung des Hauses des HERRN.", footnotes: ["℘ 4Mo 18,5; 5Mo 18,7; Hes 44,14", "d. h. sie unterstützten ihre Brüder in ihrem Dienst"] },
    ]},
    { number: 24, verses: [
      { number: 1, text: "*Auch die Söhne Aaron hatten ihre Abteilungen*: Die Söhne Aaron: Nadab und Abihu, Eleasar und Itamar.", heading: "Abteilungen der Priester", footnotes: ["℘ V. 1-19: vgl. Kap. 5,27-34; 6,34-38", "℘ Kap. 23,6"] },
      { number: 2, text: "Und Nadab und Abihu starben vor ihrem Vater, und sie hatten keine Söhne; und Eleasar und Itamar übten den Priesterdienst aus*.", footnotes: ["℘ 4Mo 3,2-4"] },
      { number: 3, text: "Und David teilte sie gemeinsam mit Zadok von den Söhnen Eleasars und Ahimelech von den Söhnen Itamars* nach ihrem Amt in ihren Dienst ein*.", footnotes: ["℘ Kap. 18,16", "℘ 2Chr 8,14; Lk 1,8"] },
      { number: 4, text: "*Und die Söhne Eleasars wurden in der Gesamtzahl der Männer zahlreicher befunden als die Söhne Itamars. Und sie teilten sie so ein: Von den Söhnen Eleasars sechzehn Häupter für die Vaterhäuser und von den Söhnen Itamars acht Häupter für ihre Vaterhäuser.", footnotes: ["℘ V. 4-19: vgl. Neh 12,12-21"] },
      { number: 5, text: "Und zwar teilten sie diese wie jene durch Lose ein*, denn die Obersten des Heiligtums*, die Obersten vor Gott*, waren aus den Söhnen Eleasars und aus den Söhnen Itamars.", footnotes: ["℘ Kap. 25,8; Jos 18,10; Lk 1,9", "℘ Jes 43,28", "w. die Obersten Gottes\n℘ Kap. 9,11"] },
      { number: 6, text: "Und der Schreiber Schemaja, der Sohn Netanels, von Levi, schrieb sie auf in Gegenwart des Königs und der Obersten und des Priesters Zadok und Ahimelechs, des Sohnes Abjatars, und der Familienoberhäupter*, der Priester und der Leviten. Je ein Vaterhaus wurde ausgelost für Eleasar, und je eins wurde ausgelost für Itamar*.", footnotes: ["w. Häupter der Väter", "so mit mehreren Handschr. und LXX; Mas. T. ist nicht sicher übersetzbar"] },
      { number: 7, text: "Und das erste Los kam heraus für Jojarib, für Jedaja das zweite," },
      { number: 8, text: "für Harim* das dritte, für Seorim das vierte,", footnotes: ["℘ Esr 2,39"] },
      { number: 9, text: "für Malkija das fünfte, für Mijamin das sechste," },
      { number: 10, text: "für Hakkoz* das siebte, für Abija* das achte,", footnotes: ["℘ Esr 2,61", "℘ Lk 1,5"] },
      { number: 11, text: "für Jeschua das neunte, für Schechanja das zehnte," },
      { number: 12, text: "für Eljaschib das elfte, für Jakim das zwölfte," },
      { number: 13, text: "für Huppa das dreizehnte, für Jeschebab das vierzehnte," },
      { number: 14, text: "für Bilga das fünfzehnte, für Immer* das sechzehnte,", footnotes: ["℘ Esr 2,37; Jer 20,1"] },
      { number: 15, text: "für Hesir das siebzehnte, für Pizez das achtzehnte," },
      { number: 16, text: "für Petachja das neunzehnte, für Jeheskel das zwanzigste," },
      { number: 17, text: "für Jachin das einundzwanzigste, für Gamul das zweiundzwanzigste," },
      { number: 18, text: "für Delaja das dreiundzwanzigste, für Maasja das vierundzwanzigste." },
      { number: 19, text: "Das war ihre Amtsordnung* für ihren Dienst, in das Haus des HERRN zu gehen nach ihrer Vorschrift, die ihnen durch ihren Vater Aaron gegeben worden war, wie der HERR, der Gott Israels, ihm geboten hatte*.", footnotes: ["w. ihr Amt", "℘ Kap. 6,34"] },
      { number: 20, text: "*Und zu den übrigen Söhnen Levis gehörten: von den Söhnen Amrams: Schubaël; von den Söhnen Schubaëls: Jechdeja. —", footnotes: ["℘ V. 20-30: Kap. 23,16-23"] },
      { number: 21, text: "Von Rehabja, von den Söhnen Rehabjas: das Oberhaupt, Jischija. —" },
      { number: 22, text: "Von den Jizharitern*: Schelomit; von den Söhnen Schelomits: Jahat. —", footnotes: ["℘ Kap. 6,3"] },
      { number: 23, text: "Und von den Söhnen Hebrons*: Jerija, das Oberhaupt, Amarja, der zweite, Jahasiël, der dritte, Jekamam, der vierte. —", footnotes: ["so mit mehreren Handschr.; Mas. T.: und meine Söhne"] },
      { number: 24, text: "Die Söhne Usiëls: Micha; von den Söhnen Michas: Schamir." },
      { number: 25, text: "Der Bruder Michas war Jischija; von den Söhnen Jischijas: Secharja. —" },
      { number: 26, text: "Die Söhne Meraris*: Machli und Muschi und die Söhne seines Sohnes Jaasia.", footnotes: ["℘ Kap. 6,4"] },
      { number: 27, text: "Die Söhne Meraris von seinem Sohn Jaasia: Schoham und Sakkur und Ibri;" },
      { number: 28, text: "von Machli: Eleasar, der hatte aber keine Söhne;" },
      { number: 29, text: "von Kisch die Söhne des Kisch: Jerachmeel;" },
      { number: 30, text: "und die Söhne Muschis: Machli und Eder und Jeremot. — Das waren die Söhne der Leviten nach ihren Vaterhäusern." },
      { number: 31, text: "Und auch sie warfen Lose wie ihre Brüder, die Söhne Aarons, in Gegenwart des Königs David und Zadoks und Ahimelechs und der Familienoberhäupter*, der Priester und der Leviten, die Familie* des Oberhauptes genauso wie die seines jüngsten Bruders*.", footnotes: ["w. Häupter der Väter", "w. die Väter", "℘ Kap. 25,8; 2Chr 31,15"] },
    ]},
    { number: 25, verses: [
      { number: 1, text: "*Und David und die Obersten des Heeres sonderten die Söhne Asafs und Hemans und Jedutuns zum Dienst aus, die mit Zithern und mit Harfen und mit Zimbeln weissagten*. Und ihre Zahl, die Zahl der Männer, die ihren Dienst taten*, war:", heading: "Abteilungen der Sänger und Musiker", footnotes: ["℘ Kap. 6,16-32; 15,16-21; V. 2-4: V. 9-31", "o. geisterfüllt spielten\n℘ Kap. 13,8; 15,28; 16,4.5; 2Chr 5,12.13; Ps 81,3; 92,2-4; 150,3.4", "w. die Zahl der Männer der Arbeit für ihren Dienst\n℘ 2Chr 8,14; 23,18; Esr 2,41; 6,18; Neh 12,45"] },
      { number: 2, text: "Von den Söhnen Asafs: Sakkur und Josef und Netanja und Asarela, die Söhne Asafs, unter der Leitung Asafs, der nach der Anweisung des Königs weissagte*.", footnotes: ["o. geisterfüllt spielte\n℘ Esr 3,10"] },
      { number: 3, text: "Von Jedutun die Söhne Jedutuns: Gedalja und Zeri und Jesaja, Haschabja und Mattitja, und Schimi, zusammen sechs, unter der Leitung ihres Vaters Jedutun, der mit der Zither weissagte*, um den HERRN zu preisen und zu loben*.", footnotes: ["o. geisterfüllt spielte", "℘ Kap. 16,41.42; 1Sam 10,5"] },
      { number: 4, text: "Von Heman die Söhne Hemans: Bukkija und Mattanja, Usiël, Schubaël und Jerimot, Hananja, Hanani, Eliata, Giddalti und Romamti-Eser, Joschbekascha, Malloti, Hotir, Mahasiot." },
      { number: 5, text: "Alle diese waren Söhne Hemans, des Sehers des Königs* nach der Zusage* Gottes, seine Macht zu erhöhen*; und Gott hatte dem Heman vierzehn Söhne und drei Töchter gegeben.", footnotes: ["℘ 2Chr 35,15", "w. nach den Worten", "w. das Horn zu erhöhen"] },
      { number: 6, text: "Alle diese spielten unter der Leitung ihrer Väter, Asaf und Jedutun und Heman, beim Gesang im Haus des HERRN* auf Zimbeln, Harfen und Zithern*, für den Dienst im Haus Gottes, nach der Anweisung des Königs*.", footnotes: ["℘ 2Chr 23,13; 29,13.14", "℘ 1Kö 10,12", "℘ Neh 11,17; 12,24.46"] },
      { number: 7, text: "Und es war ihre Zahl mit ihren Brüdern, die im Gesang für den HERRN geübt waren*, alles Meister, 288.", footnotes: ["℘ 2Chr 34,12"] },
      { number: 8, text: "*Und sie warfen Lose* um ihren Dienst, der Kleine genauso wie der Große, der Meister mit dem Schüler*.", footnotes: ["℘ V. 9-31: V. 2-4", "℘ Kap. 24,5.31", "℘ Kap. 26,13"] },
      { number: 9, text: "Und das erste Los kam heraus für Asaf, für Josef*; für Gedalja das zweite: Er und seine Brüder und seine Söhne waren zwölf;", footnotes: ["d. h. es fiel auf Josef von den Söhnen Asafs"] },
      { number: 10, text: "das dritte für Sakkur: seine Söhne und seine Brüder, zwölf;" },
      { number: 11, text: "das vierte für Zeri: seine Söhne und seine Brüder, zwölf;" },
      { number: 12, text: "das fünfte für Netanja: seine Söhne und seine Brüder, zwölf;" },
      { number: 13, text: "das sechste für Bukkija: seine Söhne und seine Brüder, zwölf;" },
      { number: 14, text: "das siebte für Asarela: seine Söhne und seine Brüder, zwölf;" },
      { number: 15, text: "das achte für Jesaja: seine Söhne und seine Brüder, zwölf;" },
      { number: 16, text: "das neunte für Mattanja: seine Söhne und seine Brüder, zwölf;" },
      { number: 17, text: "das zehnte für Schimi: seine Söhne und seine Brüder, zwölf;" },
      { number: 18, text: "das elfte für Asarel: seine Söhne und seine Brüder, zwölf;" },
      { number: 19, text: "das zwölfte für Haschabja: seine Söhne und seine Brüder, zwölf;" },
      { number: 20, text: "das dreizehnte für Schubaël: seine Söhne und seine Brüder, zwölf;" },
      { number: 21, text: "das vierzehnte für Mattitja: seine Söhne und seine Brüder, zwölf;" },
      { number: 22, text: "das fünfzehnte für Jeremot: seine Söhne und seine Brüder, zwölf;" },
      { number: 23, text: "das sechzehnte für Hananja: seine Söhne und seine Brüder, zwölf;" },
      { number: 24, text: "das siebzehnte für Joschbekascha: seine Söhne und seine Brüder, zwölf;" },
      { number: 25, text: "das achtzehnte für Hanani: seine Söhne und seine Brüder, zwölf;" },
      { number: 26, text: "das neunzehnte für Malloti: seine Söhne und seine Brüder, zwölf;" },
      { number: 27, text: "das zwanzigste für Eliata: seine Söhne und seine Brüder, zwölf;" },
      { number: 28, text: "das einundzwanzigste für Hotir: seine Söhne und seine Brüder, zwölf;" },
      { number: 29, text: "das zweiundzwanzigste für Giddalti: seine Söhne und seine Brüder, zwölf;" },
      { number: 30, text: "das dreiundzwanzigste für Mahasiot: seine Söhne und seine Brüder, zwölf;" },
      { number: 31, text: "das vierundzwanzigste für Romamti-Eser: seine Söhne und seine Brüder, zwölf." },
    ]},
    { number: 26, verses: [
      { number: 1, text: "*Zu den Abteilungen der Torhüter* gehörten; von den Korachitern: Meschelemja, der Sohn des Kore, von den Söhnen Asafs.", heading: "Abteilungen der Torhüter", footnotes: ["℘ V. 1-28: Kap. 9,14-32", "℘ Kap. 23,5; 2Chr 8,14; Hes 44,11"] },
      { number: 2, text: "Und Meschelemja hatte Söhne: Secharja war der Erstgeborene, Jediaël der zweite, Sebadja der dritte, Jatniël der vierte," },
      { number: 3, text: "Elam der fünfte, Johanan der sechste, Eljoënai der siebte. —" },
      { number: 4, text: "Und Obed-Edom hatte Söhne: Schemaja war der Erstgeborene, Josabad der zweite, Joach der dritte und Sachar der vierte und Netanel der fünfte," },
      { number: 5, text: "Ammiël der sechste, Issaschar der siebte, Pëulletai der achte, denn Gott hatte ihn gesegnet*. —", footnotes: ["℘ Kap. 13,14; 2Sam 6,12"] },
      { number: 6, text: "Und seinem Sohn Schemaja wurden auch Söhne geboren, die in dem Haus ihres Vaters herrschten, denn sie waren angesehene* Männer.", footnotes: ["o. vermögende, tüchtige"] },
      { number: 7, text: "Die Söhne Schemajas: Otni und Refaël und Obed, Elsabad und seine Brüder, tüchtige Männer*, Elihu und Semachja.", footnotes: ["w. Söhne der Kraft"] },
      { number: 8, text: "Alle diese von den Söhnen Obed-Edoms, sie und ihre Söhne und ihre Brüder, waren tüchtige Männer*, fähig zum Dienst, 62 von Obed-Edom. —", footnotes: ["w. Männer der Kraft"] },
      { number: 9, text: "Und Meschelemja hatte Söhne und Brüder, tüchtige Männer*, achtzehn. —", footnotes: ["w. Söhne der Kraft"] },
      { number: 10, text: "Und Hosa*, von den Söhnen Meraris, hatte Söhne: Schimri war das Oberhaupt — obwohl er nicht der Erstgeborene war, machte* sein Vater ihn doch zum Oberhaupt —,", footnotes: ["℘ Kap. 16,38", "o. da der Erstgeborene nicht mehr da war, machte"] },
      { number: 11, text: "Hilkija der zweite, Tebalja der dritte, Secharja der vierte. Alle Söhne und Brüder Hosas waren dreizehn." },
      { number: 12, text: "Diese Abteilungen der Torhüter, die Gesamtzahl* der Männer, hatten die Aufgabe*, ebenso wie ihre Brüder im Haus des HERRN zu dienen*.", footnotes: ["o. die Häupter", "o. die Wachen; o. die Dienste", "℘ Kap. 9,23-27"] },
      { number: 13, text: "Und sie warfen Lose nach ihren Vaterhäusern, ob klein, ob groß*, für jedes Tor.", footnotes: ["℘ Kap. 25,8"] },
      { number: 14, text: "Und auf Meschelemja fiel das Los für den Osten. Und sie warfen Lose für seinen Sohn Secharja, der ein verständiger Ratgeber war; und sein Los fiel* für den Norden.", footnotes: ["w. kam heraus"] },
      { number: 15, text: "Auf Obed-Edom* für den Süden; und seinen Söhnen fiel das Vorratshaus zu*.", footnotes: ["℘ 2Chr 25,24", "℘ Neh 12,25"] },
      { number: 16, text: "Auf Schuppim und auf Hosa für den Westen mit dem Tor Schallechet, an der aufsteigenden Straße, Dienstabteilung neben Dienstabteilung*.", footnotes: ["o. Wache gegen Wache"] },
      { number: 17, text: "Im Osten waren täglich sechs Leviten, im Norden täglich vier, im Süden täglich vier, und bei dem Vorratshaus* je zwei;", footnotes: ["℘ Neh 12,25"] },
      { number: 18, text: "am Parbar* im Westen: vier an der Straße, zwei am Parbar.", footnotes: ["d. i. wahrscheinlich ein Anbau an der Westseite des Tempels\n℘ 2Kö 23,11"] },
      { number: 19, text: "Das sind die Abteilungen der Torhüter von den Söhnen der Korachiter und von den Söhnen Meraris." },
      { number: 20, text: "Und die Leviten, ihre Brüder, waren* über die Schätze des Hauses Gottes und über die Schätze an heiligen Gaben* gesetzt*. —", heading: "Schatzmeister, Vorsteher und Richter", footnotes: ["so mit LXX; Mas. T.: Und die Leviten: Ahija war", "o. heiligen Dingen", "℘ Kap. 9,28.29; 28,12; Esr 8,28; Neh 12,44"] },
      { number: 21, text: "Die Söhne Ladans, die Söhne des Gerschoniters, die von Ladan, die Familienoberhäupter* von Ladan, dem Gerschoniter, die Jehiëliter*:", footnotes: ["w. Häupter der Väter", "℘ Kap. 23,8; 29,8"] },
      { number: 22, text: "Die Söhne der Jehiëliter, Setam und sein Bruder Joel, waren über die Schätze des Hauses des HERRN gesetzt. —" },
      { number: 23, text: "Was die Amramiter, die Jizhariter, die Hebroniter, die Usiëliter betrifft," },
      { number: 24, text: "so war Schubaël, der Sohn Gerschoms, des Sohnes des Mose*, Oberaufseher* über die Schätze. —", footnotes: ["℘ Kap. 23,16", "w. Fürst"] },
      { number: 25, text: "Und sein Bruder Eliëser hatte einen Sohn, Rehabja*, und dessen Sohn war Jesaja und dessen Sohn Joram und dessen Sohn Sichri und dessen Sohn Schelomit*.", footnotes: ["so mit LXX; Mas. T.: Und seine Brüder von Eliëser her: dessen Sohn Rehabja", "℘ Kap. 23,17.18"] },
      { number: 26, text: "Dieser Schelomit und seine Brüder waren über alle Schätze an heiligen Gaben* gesetzt, die der König David und die Familienoberhäupter*, die Obersten über Tausend und über Hundert, und die Obersten des Heeres geweiht hatten —", footnotes: ["o. heiligen Dingen", "w. Häupter der Väter"] },
      { number: 27, text: "von der Kriegsbeute und von dem Plündergut hatten sie es geweiht zur Unterstützung des Hauses des HERRN* —,", footnotes: ["℘ Kap. 18,11; 2Sam 8,11; 2Chr 5,1"] },
      { number: 28, text: "und über alles, was der Seher Samuel und Saul, der Sohn des Kisch, und Abner, der Sohn des Ner, und Joab, der Sohn der Zeruja, geweiht hatten. Alles Geweihte stand unter der Obhut* Schelomits und seiner Brüder. —", footnotes: ["w. unter der Hand"] },
      { number: 29, text: "Von den Jizharitern waren Kenanja und seine Söhne für die äußeren Aufgaben*, als Verwalter* und Richter, über Israel eingesetzt*. —", footnotes: ["w. die äußere Arbeit", "w. Schreiber; d. i. eine Beamtenbezeichnung", "℘ Kap. 23,4; 5Mo 17,8.9"] },
      { number: 30, text: "Von den Hebronitern waren Haschabja* und seine Brüder, 1 700 tüchtige Männer*, zur Aufsicht über Israel diesseits des Jordan nach Westen hin in allen Aufgaben* für den HERRN und im Dienst des Königs eingesetzt*. —", footnotes: ["℘ Kap. 27,17", "w. 1 700 Söhne der Kraft", "w. in jeder Arbeit", "℘ 2Chr 19,11"] },
      { number: 31, text: "Von den Hebronitern war Jerija das Oberhaupt* — was die Hebroniter nach ihrer Generationenfolge* und ihren Familien* betrifft, so forschte man unter ihnen im vierzigsten Jahr der Königsherrschaft Davids*, und es fanden sich unter ihnen angesehene Männer* in Jaser in Gilead* —,", footnotes: ["℘ Kap. 23,19", "s. Anm. zu Kap. 5,7", "w. ihren Vätern", "℘ Kap. 29,27", "o. vermögende Männer", "℘ Jos 21,39"] },
      { number: 32, text: "und seine Brüder, 2 700 tüchtige Männer*, waren Familienoberhäupter*. Und der König David setzte sie über die Rubeniter und die Gaditer und den halben Stamm Manasse*, für alle Angelegenheiten Gottes und für die Angelegenheiten des Königs*.", footnotes: ["w. 2 700 Söhne der Kraft", "w. Häupter der Väter", "℘ Jos 1,12", "℘ 2Chr 19,11"] },
    ]},
    { number: 27, verses: [
      { number: 1, text: "*Und dies sind die Söhne Israel nach ihrer Zahl, die Familienoberhäupter* und die Obersten über Tausend und über Hundert* und ihre Verwalter*, die dem König dienten in allen Angelegenheiten der Abteilungen, die Monat für Monat antraten und abtraten, alle Monate des Jahres*. Jede Abteilung zählte 24 000 Mann.", heading: "Heerführer, Stammesfürsten und Beamte", footnotes: ["℘ V. 1-15: Kap. 11,10-47; 2Sam 23,8-39", "w. Häupter der Väter", "℘ 1Sam 8,12", "w. Schreiber; d. i. eine Beamtenbezeichnung\n℘ Jos 23,1; 2Chr 1,2", "℘ 1Kö 4,7"] },
      { number: 2, text: "Über die erste Abteilung für den ersten Monat war Joschobam, der Sohn Sabdiëls, eingesetzt; und in seiner Abteilung waren 24 000 Mann." },
      { number: 3, text: "Er war von den Söhnen des Perez und war das Oberhaupt aller Obersten des Heeres für den ersten Monat." },
      { number: 4, text: "Und über die Abteilung des zweiten Monats war Dodai, der Ahoachiter eingesetzt; und von seiner Abteilung war Miklot Führer*; und in seiner Abteilung waren 24 000 Mann.", footnotes: ["w. Fürst"] },
      { number: 5, text: "Der Oberste des dritten Heeres* für den dritten Monat war Benaja, der Sohn des Priesters* Jojada* als Oberhaupt; und in seiner Abteilung waren 24 000 Mann.", footnotes: ["o. der dritte Heeroberste", "d. i. vielleicht ein Ehrentitel", "℘ V. 34; Kap. 12,28; 1Kö 2,35"] },
      { number: 6, text: "Dieser Benaja war ein Held unter den Dreißig und Anführer über die Dreißig; und über seine Abteilung war sein Sohn Ammisabad eingesetzt." },
      { number: 7, text: "Der vierte für den vierten Monat war Asaël, der Bruder Joabs*, und nach ihm sein Sohn Sebadja; und in seiner Abteilung waren 24 000 Mann.", footnotes: ["℘ 2Sam 2,18"] },
      { number: 8, text: "Der fünfte für den fünften Monat war der Oberste Schamhut, der Serachiter; und in seiner Abteilung waren 24 000 Mann." },
      { number: 9, text: "Der sechste für den sechsten Monat war Ira, der Sohn des Ikkesch, der Tekoïter; und in seiner Abteilung waren 24 000 Mann." },
      { number: 10, text: "Der siebte für den siebten Monat war Helez, der Peletiter, von den Söhnen Ephraim; und in seiner Abteilung waren 24 000 Mann." },
      { number: 11, text: "Der achte für den achten Monat war Sibbechai, der Huschatiter*, von den Serachitern; und in seiner Abteilung waren 24 000 Mann.", footnotes: ["℘ Kap. 20,4"] },
      { number: 12, text: "Der neunte für den neunten Monat war Abiëser, der Anatotiter, von den Benjaminitern; und in seiner Abteilung waren 24 000 Mann." },
      { number: 13, text: "Der zehnte für den zehnten Monat war Mahrai, der Netofatiter, von den Serachitern; und in seiner Abteilung waren 24 000 Mann." },
      { number: 14, text: "Der elfte für den elften Monat war Benaja, der Piratoniter, von den Söhnen Ephraim; und in seiner Abteilung waren 24 000 Mann." },
      { number: 15, text: "Der zwölfte für den zwölften Monat war Heldai, der Netofatiter von Otniël*; und in seiner Abteilung waren 24 000 Mann.", footnotes: ["℘ Jos 15,17"] },
      { number: 16, text: "*Und über die Stämme Israels waren Folgende eingesetzt: Fürst von den Rubenitern war Eliëser, der Sohn Sichris; von den Simeonitern Schefatja, der Sohn Maachas;", footnotes: ["℘ V. 16-22: 1Mo 35,23-26; 4Mo 1,5-16"] },
      { number: 17, text: "von Levi Haschabja*, der Sohn Kemuëls; von Aaron Zadok*;", footnotes: ["℘ Kap. 26,30", "℘ Kap. 6,38; 12,29"] },
      { number: 18, text: "von Juda Elihu, einer von den Brüdern Davids*; von Issaschar Omri, der Sohn Michaels;", footnotes: ["℘ Kap. 2,13"] },
      { number: 19, text: "von Sebulon Jischmaja, der Sohn Obadjas; von Naftali Jeremot, der Sohn Asriëls;" },
      { number: 20, text: "von den Söhnen Ephraim Hoschea, der Sohn Asasjas; von dem halben Stamm Manasse Joel, der Sohn Pedajas;" },
      { number: 21, text: "von der Hälfte des Stammes Manasse in Gilead Jiddo, der Sohn Secharjas; von Benjamin Jaasiël, der Sohn Abners;" },
      { number: 22, text: "von Dan Asarel, der Sohn Jerohams. Das sind die Obersten der Stämme Israels." },
      { number: 23, text: "Und David nahm die Zahl derer von zwanzig Jahren und darunter nicht auf*; denn der HERR hatte gesagt, dass er Israel mehren werde wie die Sterne des Himmels*.", footnotes: ["℘ 2Sam 24,1-9", "℘ 1Mo 22,17"] },
      { number: 24, text: "Joab, der Sohn der Zeruja, hatte zu zählen begonnen, aber er vollendete es nicht, denn es kam wegen dieser Sache ein Zorn über Israel.* Und so wurde die Zahl nicht in die Aufzählung des Buches der Geschichte* des Königs David aufgenommen*.", footnotes: ["℘ Kap. 21,5-7; 2Sam 24,15", "w. des Buches der Begebenheiten der Tage", "℘ 2Sam 24,1-9"] },
      { number: 25, text: "Und über die Vorräte* des Königs in Jerusalem war Asmawet*, der Sohn Adiëls, eingesetzt. Und über die Vorräte auf dem Feld, in den Städten und in den Dörfern und in den Türmen war Jonatan, der Sohn Usijas, eingesetzt.", footnotes: ["o. Schätze", "℘ 2Sam 23,31"] },
      { number: 26, text: "Und über die Feldarbeiter beim Ackerbau: Esri, der Sohn Kelubs." },
      { number: 27, text: "Und über die Weinberge*: Schimi, der Ramatiter; und über das, was in den Weinbergen an Weinvorräten war: Sabdi, der Schifmiter*.", footnotes: ["℘ 2Chr 26,10; Pred 2,4", "℘ 4Mo 34,10; 1Sam 30,28"] },
      { number: 28, text: "Und über die Olivenbäume und die Maulbeerfeigenbäume, die in der Niederung* waren: Baal-Hanan, der Gederiter*; und über die Ölvorräte: Joasch.", footnotes: ["hebr. Schefelah; d. i. der Küstenstreifen zwischen Jafo und Gaza", "℘ Jos 15,36.41"] },
      { number: 29, text: "Und über die Rinder, die in der Scharonebene* weideten: Schitrai, der Scharoniter; und über die Rinder in den Ebenen*: Schafat, der Sohn Adlais;", footnotes: ["℘ Kap. 5,16; Jes 35,2; 65,10", "℘ 5Mo 1,7; 2Chr 26,10"] },
      { number: 30, text: "und über die Kamele: Obil, der Ismaeliter; und über die Eselinnen: Jechdeja, der Meronotiter*;", footnotes: ["℘ Neh 3,7"] },
      { number: 31, text: "und über die Schafe*: Jasis, der Hagariter*. Alle diese waren Verwalter* des Eigentums, das der König David hatte.", footnotes: ["℘ Pred 2,7", "℘ Kap. 5,19", "o. Oberste(n)"] },
      { number: 32, text: "Und Jonatan*, der Onkel Davids, war Ratgeber; er war ein einsichtiger und schriftkundiger Mann. Und Jehiël, der Sohn Hachmonis, war bei den Söhnen des Königs.", footnotes: ["℘ Kap. 20,7; 2Sam 13,3"] },
      { number: 33, text: "Und Ahitofel war auch Ratgeber des Königs*. Und Huschai, der Arkiter*, war Freund des Königs*.", footnotes: ["℘ 2Sam 15,12", "℘ 2Sam 15,37", "»Freund des Königs« ist ein Amtstitel und dürfte so viel wie »Ratgeber« bedeuten."] },
      { number: 34, text: "Und nach Ahitofel waren es Jojada*, der Sohn Benajas, und Abjatar*. Und Joab war Heeroberster des Königs*.", footnotes: ["℘ V. 5", "℘ 1Kö 1,7", "℘ Kap. 11,6; 18,15"] },
    ]},
    { number: 28, verses: [
      { number: 1, text: "Und David versammelte alle Obersten Israels*, die Obersten der Stämme* und die Obersten der Abteilungen, die dem König dienten*, und die Obersten über Tausend und die Obersten über Hundert und die Verwalter* über das ganze Eigentum und den ganzen Viehbestand des Königs* und seiner Söhne samt den Hofbeamten* und den Helden* und allen angesehenen* Männern nach Jerusalem.", heading: "Ansprache Davids vor den Obersten des Volkes — Auftrag zum Tempelbau und Einsetzung Salomos zum König", footnotes: ["℘ Kap. 23,2", "℘ Kap. 27,16-22", "℘ Kap. 27,1-15", "o. Oberste(n)", "℘ Kap. 27,25-31; 29,1.6", "w. Eunuchen", "℘ Kap. 11,10-47", "o. vermögenden"] },
      { number: 2, text: "*Und der König David erhob sich, stellte sich auf seine Füße und sagte: Hört mich, meine Brüder und mein Volk! Ich hatte mir in meinem Herzen vorgenommen, ein Haus der Ruhe zu bauen* für die Lade des Bundes des HERRN* und für den Schemel der Füße unseres Gottes*; und ich stellte Material bereit*, es zu bauen.", footnotes: ["℘ V. 2-7: Kap. 17,1-14; 22,7-10; 2Sam 7,1-16", "℘ 1Kö 8,17", "℘ Ps 132,2-5", "℘ Ps 99,5; 110,1; Jes 66,1; Kla 2,1; Hes 43,7", "o. und ich richte mein Herz darauf"] },
      { number: 3, text: "Aber Gott sprach zu mir: Du sollst meinem Namen kein Haus bauen*! Denn du bist ein Mann der Kriege und hast Blut fließen lassen.", footnotes: ["℘ 2Sam 7,5; 2Chr 6,9"] },
      { number: 4, text: "Und der HERR, der Gott Israels, hat mich aus dem ganzen Haus meines Vaters erwählt*, damit ich König über Israel sei für ewig. Denn Juda hat er zum Fürsten erwählt und im Haus Juda das Haus meines Vaters, und unter den Söhnen meines Vaters hat er an mir Gefallen gehabt, so dass er mich zum König machte über ganz Israel*.", footnotes: ["℘ Kap. 5,2; Ps 78,68; 89,4", "℘ 2Sam 5,3"] },
      { number: 5, text: "Und von allen meinen Söhnen — denn der HERR hat mir viele Söhne gegeben* — hat er meinen Sohn Salomo erwählt, dass er auf dem Thron der Königsherrschaft des HERRN über Israel sitze*.", footnotes: ["℘ Kap. 3,1-9", "℘ Kap. 23,1; 29,1.23; 5Mo 17,15; 2Chr 1,9"] },
      { number: 6, text: "Und er sprach zu mir: Dein Sohn Salomo, er soll mein Haus und meine Höfe bauen*! Denn ich habe ihn mir zum Sohn erwählt, und ich will ihm Vater sein.", footnotes: ["℘ 1Kö 8,20"] },
      { number: 7, text: "Und ich werde seine Königsherrschaft bestätigen für ewig, wenn er daran festhalten wird, meine Gebote und meine Rechtsbestimmungen zu tun*, wie es heute der Fall ist.", footnotes: ["℘ Kap. 22,13; 1Kö 3,14"] },
      { number: 8, text: "Und nun, vor den Augen von ganz Israel, der Versammlung des HERRN, und vor den Ohren unseres Gottes: Beachtet und sucht alle Gebote des HERRN, eures Gottes*, damit ihr dieses gute Land besitzt und es euren Söhnen nach euch vererbt für ewig*.", footnotes: ["℘ 2Mo 23,13; 5Mo 27,1", "℘ 5Mo 5,33; Jos 24,20; Esr 9,12"] },
      { number: 9, text: "Und du, mein Sohn Salomo, erkenne den Gott deines Vaters* und diene ihm mit ungeteiltem Herzen und mit williger Seele*! Denn der HERR erforscht alle Herzen*, und alles Streben der Gedanken kennt er*. Wenn du ihn suchst, wird er sich von dir finden lassen*; wenn du ihn aber verlässt, wird er dich verwerfen für ewig*.", footnotes: ["℘ Jer 22,16", "℘ Kap. 29,19; 5Mo 10,12; 1Kö 8,61", "℘ Kap. 29,17; Ps 7,10; 17,3; Jer 11,20", "℘ 1Kö 8,39; Hes 11,5; Lk 5,22", "℘ Jer 29,13.14; Mt 7,7", "℘ 2Chr 12,5; Esr 8,22; Spr 4,4; Hebr 6,4-6"] },
      { number: 10, text: "Sieh nun, dass der HERR dich erwählt hat*, ihm ein Haus zu bauen als Heiligtum! Sei stark und handle*!", footnotes: ["o. Sieh nun zu, denn der HERR hat dich erwählt", "℘ V. 20; Kap. 22,13.16; 1Kö 2,2"] },
      { number: 11, text: "Und David gab seinem Sohn Salomo den Plan* der Vorhalle des Tempels* und seiner Gebäude* und seiner Schatzkammern und seiner Obergemächer und seiner Innenräume* und des Raumes* der Deckplatte*;", heading: "Der Plan des Tempels", footnotes: ["w. die Bauart", "℘ 2Mo 25,9; 2Chr 3,3", "so mit LXX; Mas. T.: und seine Gebäude", "℘ 1Kö 6,5; 2Chr 3,9", "w. Hauses", "o. der Sühneplatte. — Das hebr. Grundwort kann »bedecken« und »sühnen« bedeuten."] },
      { number: 12, text: "und den Plan* von allem, was durch den Geist in ihm war*: für die Höfe des Hauses des HERRN und alle Zellen ringsum*; für die Schatzkammern des Hauses Gottes und die Schatzkammern der heiligen Gaben*;", footnotes: ["w. die Bauart", "℘ V. 19", "℘ Jer 35,2", "o. und alle Zellen ringsum für Schätze des Hauses Gottes und die Schätze der heiligen Dinge\n℘ Kap. 26,20; 1Kö 7,51"] },
      { number: 13, text: "und für die Abteilungen der Priester und Leviten und für alle Dienstarbeiten im Haus des HERRN; und für alle Geräte des Dienstes im Haus des HERRN;" },
      { number: 14, text: "*für das Gold gemäß dem Goldgewicht für alle Geräte jedes Dienstes; für alle silbernen Geräte gemäß dem Gewicht für alle Geräte jedes Dienstes.", footnotes: ["℘ V. 14-19: 2Chr 4,7-5,1"] },
      { number: 15, text: "Und er gab das Gewicht für die goldenen Leuchter an und für ihre goldenen Lampen gemäß dem Gewicht jedes Leuchters und seiner Lampen; und für die silbernen Leuchter gemäß dem Gewicht eines Leuchters und seiner Lampen, je nach der Aufgabe* jedes Leuchters;", footnotes: ["w. dem Dienst"] },
      { number: 16, text: "und das Goldgewicht für die Tische der Schaubrote*, für jeden Tisch; und das Silber für die silbernen Tische;", footnotes: ["w. für die Tische der Schicht; d. h. der aufgeschichteten Brote"] },
      { number: 17, text: "und die Gabeln und die Sprengschalen und die Kannen aus reinem Gold; und das Gewicht für die goldenen Becher nach dem Gewicht jedes Bechers; und für die silbernen Becher gemäß dem Gewicht jedes Bechers;" },
      { number: 18, text: "und für den Rauchopferaltar aus geläutertem Gold gemäß seinem Gewicht; und den Plan des Wagens der Cherubim von Gold, die die Flügel ausbreiten und die Lade des Bundes des HERRN beschirmen. —" },
      { number: 19, text: "Das alles hat er mich aufgrund einer Schrift aus der Hand des HERRN gelehrt*, alle Arbeiten des Plans.", footnotes: ["o. Das alles hat er mich, weil die Hand des HERRN auf mir war, aufgrund einer Schrift gelehrt\n℘ V. 12; 2Mo 26,30"] },
      { number: 20, text: "Und David sagte zu seinem Sohn Salomo: Sei stark und mutig, und handle*; fürchte dich nicht und sei nicht niedergeschlagen*! Denn Gott, der HERR, mein Gott, wird mit dir sein*. Er wird dich nicht aufgeben und dich nicht verlassen*, bis alle Arbeit für den Dienst des Hauses des HERRN vollendet ist*.", footnotes: ["℘ V. 10; 1Kö 6,38; Esr 10,4", "℘ Jos 1,9", "℘ Hag 1,13", "℘ 5Mo 31,6; Hebr 13,5", "℘ 1Kö 6,38"] },
      { number: 21, text: "Und siehe, da sind die Abteilungen der Priester und der Leviten für jeden Dienst des Hauses Gottes*; und in aller Arbeit sind bei dir solche, die bereitwillig und geschickt sind zu jedem Dienst*, und die Obersten und das ganze Volk für alle deine Anordnungen*.", footnotes: ["℘ Kap. 24; 25; 26", "w. sind bei dir lauter Bereitwillige in Weisheit zu jedem Dienst\n℘ 2Mo 36,1.2", "w. Worte"] },
    ]},
    { number: 29, verses: [
      { number: 1, text: "*Und der König David sagte zu der ganzen Versammlung*: Mein Sohn Salomo, der Einzige, den Gott erwählt hat*, ist noch jung und zart; das Werk aber ist groß, denn nicht für einen Menschen ist dieser Palast*, sondern für Gott den HERRN.", heading: "Beisteuer zum Tempelbau", footnotes: ["℘ V. 1-5: Kap. 22,2-5", "℘ Kap. 28,1", "℘ Kap. 28,5", "w. die Burg"] },
      { number: 2, text: "Und mit all meiner Kraft habe ich für das Haus meines Gottes bereitgestellt*: das Gold für das goldene Gerät und das Silber für das silberne und die Bronze für das bronzene, das Eisen für das eiserne und das Holz für das hölzerne Gerät; Onyxsteine* und eingefasste Steine*, Steine zur Verzierung und Mosaiksteine und allerlei Edelsteine und Alabastersteine in Menge.", footnotes: ["℘ Kap. 22,14.16; 2Kor 8,3.4", "℘ 2Mo 28,9; 2Chr 3,6", "℘ V. 5"] },
      { number: 3, text: "Und außerdem, weil ich Gefallen habe an dem Haus meines Gottes, habe ich, was ich als Eigentum an Gold und Silber selbst besitze, für das Haus meines Gottes gegeben, über all das hinaus, was ich für das Haus des Heiligtums bereitgestellt habe:" },
      { number: 4, text: "3 000 Talente Gold von Gold aus Ofir* und 7 000 Talente geläutertes Silber, zum Überziehen der Wände der Räume*;", footnotes: ["℘ 1Kö 9,28", "w. der Häuser"] },
      { number: 5, text: "Gold für das goldene und Silber für das silberne Gerät und für jede Arbeit von Künstlerhand. Wer ist nun bereitwillig, heute seine Hand ebenso für den HERRN zu füllen?*", footnotes: ["℘ 2Mo 25,2"] },
      { number: 6, text: "Und die Obersten der Sippen* und die Obersten der Stämme Israels und die Obersten über Tausend und über Hundert und die Obersten über den königlichen Dienst* zeigten sich bereitwillig*;", footnotes: ["w. der Väter", "℘ Kap. 28,1", "℘ 2Chr 35,8"] },
      { number: 7, text: "und sie gaben für die Arbeit am Haus Gottes 5 000 Talente Gold und 10 000 Dariken und 10 000 Talente Silber* und 18 000 Talente Bronze und 100 000 Talente Eisen.", footnotes: ["℘ Esr 2,69"] },
      { number: 8, text: "Und bei wem sich Edelsteine fanden, der gab* sie für den Schatz des Hauses des HERRN* in die Hand Jehiëls*, des Gerschoniters. —", footnotes: ["w. die gaben", "℘ 2Mo 35,21", "℘ Kap. 26,21"] },
      { number: 9, text: "Und das Volk freute sich über ihre Bereitwilligkeit, denn mit ungeteiltem Herzen zeigten sie sich bereitwillig für den HERRN*; und auch der König David freute sich mit großer Freude*.", footnotes: ["℘ 2Kö 12,5; Esr 1,6; 2Kor 9,7", "℘ 2Chr 24,10; Phil 4,10"] },
      { number: 10, text: "Und David pries den HERRN* vor den Augen der ganzen Versammlung*, und David sprach: Gepriesen seist du, HERR, Gott unseres Vaters Israel*, von Ewigkeit zu Ewigkeit*!", heading: "Davids Gebet — Salbung Salomos und Zadoks — Davids Tod", footnotes: ["o. dankte dem HERRN; o. segnete den HERRN", "℘ 2Chr 31,8; Neh 8,6; Ps 22,26", "℘ 1Mo 33,20; Esr 7,27", "℘ 1Kö 8,15; Dan 2,20; Ps 57,6"] },
      { number: 11, text: "Dein, HERR, ist die Größe und die Stärke und die Herrlichkeit und der Glanz und die Majestät*; denn alles im Himmel und auf Erden ist dein*. Dein, HERR, ist das Königtum*, und du bist über alles erhaben als Haupt*.", footnotes: ["℘ 1Tim 1,17; Offb 5,12.13", "℘ 1Mo 14,19; Jos 3,11.13; Neh 9,5.6", "℘ Ps 10,16; Jer 10,10; 1Tim 1,17", "℘ Ps 103,19"] },
      { number: 12, text: "Und Reichtum und Ehre* kommen von dir*, und du bist Herrscher über alles*. Und in deiner Hand sind Macht* und Stärke, und in deiner Hand liegt es, einen jeden groß und stark zu machen*.", footnotes: ["o. Herrlichkeit", "℘ 5Mo 8,18; 1Sam 2,7", "℘ Ps 103,19", "℘ Ps 62,12", "℘ 2Chr 20,6"] },
      { number: 13, text: "Und nun, unser Gott, wir preisen dich, und wir loben deinen herrlichen Namen*.", footnotes: ["℘ 5Mo 32,3; Ps 145,1-6; Dan 4,34"] },
      { number: 14, text: "Denn wer bin ich*, und was ist mein Volk, dass wir imstande waren, auf solche Weise freigebig* zu sein? Denn von dir kommt alles, und aus deiner Hand haben wir dir gegeben*.", footnotes: ["℘ Kap. 17,16; 2Mo 3,11; 2Sam 7,18; 2Chr 2,5", "o. bereitwillig", "℘ 5Mo 16,10.17"] },
      { number: 15, text: "Denn wir sind Fremde vor dir und Beisassen* wie alle unsere Väter*; wie ein Schatten sind unsere Tage auf Erden*, und es gibt keine Hoffnung*.", footnotes: ["d. i. ein Ansässiger ohne Bürgerrecht", "℘ 1Mo 23,4; 47,9; Hebr 11,13", "℘ Hi 8,9; Pred 6,12", "o. Sicherheit\n℘ Hi 14,10; Hebr 9,27"] },
      { number: 16, text: "HERR, unser Gott, diese ganze Menge, die wir bereitgestellt haben, um dir ein Haus zu bauen für deinen heiligen Namen, von deiner Hand ist sie, und das alles ist dein." },
      { number: 17, text: "Ich habe erkannt, mein Gott, dass du das Herz prüfst*, und an Aufrichtigkeit hast du Gefallen*. Ich nun, in Aufrichtigkeit meines Herzens habe ich das alles bereitwillig gegeben; und ich habe jetzt mit Freuden gesehen, dass auch dein Volk, das sich hier befindet, dir bereitwillig gegeben hat*.", footnotes: ["℘ Kap. 28,9; 2Chr 6,30; 1Thes 2,4", "℘ Ps 51,8", "℘ V. 9"] },
      { number: 18, text: "HERR, Gott unserer Väter Abraham, Isaak und Israel*, bewahre dieses für ewig als Streben der Gedanken im Herzen deines Volkes*, und richte ihr Herz zu dir*!", footnotes: ["℘ 2Mo 3,15; 2Chr 30,6", "℘ 5Mo 5,29", "℘ 2Thes 3,5"] },
      { number: 19, text: "Und meinem Sohn Salomo gib ein ungeteiltes Herz*, deine Gebote, deine Zeugnisse* und deine Ordnungen zu beachten* und das alles zu tun und den Palast zu bauen, den ich vorbereitet habe!", footnotes: ["℘ Kap. 28,9; 2Chr 6,30; 1Thes 2,4", "o. Mahnungen", "℘ Kap. 28,9; Ps 72,2"] },
      { number: 20, text: "Und David sagte zu der ganzen Versammlung: Preist* doch den HERRN, euren Gott*! Und die ganze Versammlung pries* den HERRN*, den Gott ihrer Väter; und sie verneigten sich und warfen sich nieder vor dem HERRN und vor dem König.", footnotes: ["o. Segnet; o. Dankt", "℘ Neh 9,5; Ps 135,19", "o. segnete; o. dankte", "℘ Neh 8,6"] },
      { number: 21, text: "Und am folgenden Tage brachten sie Schlachtopfer dem HERRN dar*, und sie opferten dem HERRN Brandopfer: tausend Stiere, tausend Widder, tausend Lämmer und ihre Trankopfer und Schlachtopfer in Menge für ganz Israel.", footnotes: ["w. schlachteten sie Schlachtopfer dem HERRN"] },
      { number: 22, text: "Und sie aßen und tranken vor dem HERRN an jenem Tag mit großer Freude*. Und sie machten Salomo, den Sohn Davids, zum zweiten Mal zum König*. Und ihn salbten sie dem HERRN zum Fürsten* und Zadok zum Priester.", footnotes: ["℘ Kap. 12,40; 2Mo 18,12; 5Mo 12,7; Neh 8,12", "℘ Kap. 23,1", "℘ 1Kö 1,39"] },
      { number: 23, text: "So setzte sich Salomo auf den Thron des HERRN* als König anstelle seines Vaters David*, und er hatte Gelingen; und ganz Israel gehorchte ihm*.", footnotes: ["℘ 2Kö 11,19; 2Chr 9,8; 23,20", "℘ Kap. 28,5; 1Kö 1,30.35.46; 2Chr 1,8; Spr 1,1", "℘ 5Mo 34,9; 2Chr 9,30"] },
      { number: 24, text: "Und alle Obersten und die Helden und auch alle Söhne des Königs David unterwarfen sich dem König Salomo." },
      { number: 25, text: "Und der HERR machte Salomo überaus groß vor den Augen von ganz Israel*, und er gab ihm Majestät der Königsherrschaft, wie sie vor ihm bei keinem König über Israel gewesen war*.", footnotes: ["℘ Jos 4,14; 2Chr 1,1", "℘ 1Kö 1,37; 3,12.13; Pred 2,9"] },
      { number: 26, text: "So regierte David, der Sohn Isais, über ganz Israel." },
      { number: 27, text: "Und die Tage, die er über ganz Israel regierte, waren vierzig Jahre*. In Hebron regierte er sieben Jahre*, und in Jerusalem regierte er 33 Jahre.", footnotes: ["℘ Kap. 26,31", "℘ Kap. 3,4"] },
      { number: 28, text: "Und er starb in gutem Alter*, satt an Tagen*, Reichtum und Ehre*. Und sein Sohn Salomo wurde an seiner Stelle König*.", footnotes: ["℘ Apg 13,36", "℘ Kap. 23,1", "o. Herrlichkeit\n℘ 2Chr 32,27.29", "℘ Kap. 28,5; 1Kö 1,30.35.46; 2Chr 1,8; Spr 1,1"] },
      { number: 29, text: "Und die Geschichte* des Königs David, die frühere und die spätere*, siehe, die ist geschrieben in der Geschichte* des Sehers Samuel* und in der Geschichte* des Propheten Nathan* und in der Geschichte* Gads, des Schauenden*;", footnotes: ["w. die (den) Begebenheiten, o. die (den) Worte(n)", "℘ 2Chr 12,15", "w. die (den) Begebenheiten, o. die (den) Worte(n)", "℘ 1Sam 9,9; 1Chr 21,9", "w. die (den) Begebenheiten, o. die (den) Worte(n)", "℘ Kap. 9,22; 2Sam 7,2; 2Chr 9,29", "w. die (den) Begebenheiten, o. die (den) Worte(n)", "℘ Kap. 21,9"] },
      { number: 30, text: "dazu seine ganze Regierung und seine Macht und die Zeiten, die über ihn und über Israel und über alle Königreiche der Länder dahingegangen sind." },
    ]},
  ]
};
